window.HB_TR["numbers"]["ks"]=["1.\\tتہٕ خداوند کٔر موسیٰ سٍتـ̡ سینا کِس بیابانس مَنٛز، جماعت کِس خیمہ خانس مَنٛز، دۆیمہِ ریتہٕ کِس گۄڈنِکِس دۅہہٕ پیٹھ، دۆیمِس ؤریس مَنٛز، یێلہِ تِم مصرٕچ سرزمینہٕ منزٕ نیرنہٕ پتہٕ وونُن،\n2.\\tتِمن ہٕندِس عیالس پتہٕ، تِہندِ مٲلِس سٍتـ̡ سارِنٕے جمٲژ ہُند مجموعہٕ رٔٹِو، تِمن ہٕندِس مٲلِس سٍتـ̡ {تِہٕندِ} ناوَن ہٕندِس تعدادس سٍتـ̡ رٔٹِو۔\n3. وُہُہ وُہُر وُہُر وٲنسہِ پیٹھٕ یُس اسرٲیلِس مَنٛز جنگس مَنٛز نیرنس لایق آسہِ، تۅہہ تہٕ ہارون کٔرِو تِمن ہٕندِس لشکر سٍتـ̡ گنزراونہٕ۔\n4. تہٕ توے سٍتـ̡ آسہِ پرٮ۪تھ قبیلُک اکھ نفر ۔ پرٮ۪تھ کانٛہہ اوس پننین مٲلن ہٕندِس گرُک سربراہ۔\n5.\\tتہٕ یِم {چِھ} تِمن نفرن ہٕندِ ناو یِم توے سٍتـ̡ کھڑا گژھِ: {قٔبیٖلہٕ} روبن سٕندِ۔ الیزور شیدیور سُند نیچو۔\n6. شمعون سُند؛ زُرِشَدایی سُنٛد نیٚچُو۔\n7. یہوداہُک ؛ ناہشون امیناداب سُند نیچو۔\n8. اِساچار سٕندِ۔ نیتھنیل زوار سُند نیچو۔\n9. زبولون سٕندِ۔ ایلاب ہیلون سُند نیچو۔\n10. یوسف سٕندِ اولاد: افرائیم سٕندِ۔ الیشامہ امیہود سُند نیچو: منسیٰ سُند۔ گمالیئل، پیڈہزور سُند نیچو۔\n11. بینجمن سٕندِ۔ عابدان، گِدونی سُنٛد نیٚچُو۔\n12. ڈین سٕنز؛ اَمِشادایی سُنٛد نیٚچُو۔\n13. آشر سٕندِ۔ پیگیل، اوکران سُنٛد نیٚچُو۔\n14. گاڈ سُند؛ الیاسوف اوس ڈیول سُند نیچو۔ {ڈیول: تہٕ چُھ ونان، ریویل}\n15. نفتالی ہُند؛ احیرا اِنان سُنٛد نیٚچُو۔\n16.\\tیِم ٲسۍ جمٲژ ہٕندِس مشہوٗر، پننین بابن ہٕندِس قبیلن ہٕندِ شہزادہٕ، اسرٲیلِس مَنٛز ساسہٕ بٔدۍ ہٕندِس سردار۔\n17. تہٕ موسیٰ تہٕ ہارون رٔٹۍ یِم نفر یِمن ہُند ظٲہر چھُ تِمن ہٕندِس ناوَو سٍتـ̡ کرنہٕ آمُت:\n18.\\tتہٕ تِمو کٔر دٔیمہِ ریتہٕ کِس گۄڈنِکِس دۅہہٕ سٍتـ̡ سارِنٕے جماعت جمع تہٕ تِمو کٔر پننین عیالن پتہٕ، پننین مٲلن ہٕندِس گرٕ سٍتـ̡ ناوَن ہٕندِ تعدادٕ مُطٲبق، وُہن ؤرین تہٕ امہِ کھۄتہٕ زیادٕ وٲنسہِ ہٕندِ حسابہٕ۔\n19.\\tیِتھٕ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت، تِتھۍ کٔرِن تِم سینا کِس بیابانس مَنٛز گنزراونہٕ۔\n20.\\tتہٕ روبن سٕندِ اولاد، یُس اسرٲیلُک زِٹھہِ نیچو اوس، پننین خاندانن پتہٕ، پننین مٲلن ہٕندِس گرس سٍتـ̡ ، ناوَن ہٕندِ تعدادٕ مُطٲبق، وُہن وُہُن وُہُر تہٕ امہِ کھۄتہٕ زیادٕ وٲنسہِ ہُند پرٮ۪تھ کانہہ مرد یُس جنگس منز نیرنس لایق اوس۔\n21.\\tیِمن ہُند تعداد اوس روبن سٕندِس قبیلس منز، {حتیٰ کہ} ٲسۍ ژتٲجی تہٕ شیہ ساس پانژھ ہتھ۔\n22.\\tشمعون سٕندٮ۪ن شُرین منز، تِہندِ خاندانہٕ پتہٕ، پننین مٲلن ہٕندِس گرٕ سٍتـ̡ یِمن ہٕندِس ناون ہٕندِس تعدادس مُطٲبق، وُہن وُہُن وُہُر تہٕ اَمہِ کھۄتہٕ زیادٕ وٲنسہِ ہٕندِس مردس سٍتـ̡ یُس جنگس منز نیرنس لایق اوس۔\n23.\\tیِمن ہُند تعداد اوس شمعون سٕندِس قبیلس منز، تِمن ہُند تعداد اوس پنژاہ تہٕ نو ساس ترے ہتھ۔\n24.\\tگاد سٕندِس شُرِس منز، تِمن ہٕندِس عیالس پتہٕ، تِمن ہٕندِس مٲلِس سٕندِس گرس مُطٲبق، وُہن وُہُن وُہُر تہٕ اَمہِ کھۄتہٕ زیادٕ ناوَن ہٕندِ تعدادٕ مُطٲبِق، یِم سارِنٕے جنگس منز نیرنس لایق ٲسۍ۔\n25.\\tیِمن ہُند تعداد اوس گاد قبیلہٕ سٍتـ̡ {حتی} ژتٲجی تہٕ پانژتٲجی ساس شیہ ہتھ پنژاہ۔\n26.\\tیہوداہ کِس اولادس منز، پننین خاندانن پتہٕ، پننین مٲلن ہٕندِس گرس سٍتـ̡ ، وُہن وُہُن وٲنسہِ تہٕ امہِ کھوتہٕ زیادٕ ناوَن ہٕندِ تعدادٕ مُطٲبق، سارِنٕے یِم جنگس منز نیرنس لایق ٲسۍ۔\n27.\\tیِمن ہُند تعداد اوس یہوداہ قبیلہٕ سٍتـ̡ {حتی} تریہ تہٕ ژۅداہ ساس تہٕ شیہ ہتھ۔\n28.\\tاِساکر سٕندِ شُرۍ، تِہندِ عیالہٕ پتہٕ، پننین مٲلن ہٕندِس گرٕ سٍتـ̡ ، وُہن وُہُن وُہُر تہٕ امہِ کھۄتہٕ زیادٕ ناوَن ہٕندِ تعدادٕ مُطٲبق، سارِنٕے یِم جنگس منز نیرنس لایق ٲسۍ۔\n29.\\tیِمن ہُند تعداد اوس، یِمن ہُند تعداد اوس اِساکر سٕندِس قبیلس منز، ژۅن ساس ژور ہتھ۔\n30.\\tزبولون کین شُرین منز، پننین خاندانن پتہٕ، پننین مٲلن ہٕندِ گرٕ سٍتۍ، وُہن ؤرین تہٕ امہِ کھوتہٕ زیادٕ وٲنسہِ ہٕندِس ناون ہٕندِ تعدادٕ مطٲبق، سارِنٕے یِم جنگس منز نیرنس لایق ٲسۍ۔\n31.\\tیِمن ہُند تعداد اوس زبولون قبیلہٕ سٍتـ̡ {حتی} سٍتـ̡ ستھ ساس ژور ہتھ۔\n32.\\tیوسف سٕندِ اولاد، یعنی افرائیم سٕندِ اولاد، پننین خاندانن پتہٕ، پننین مٲلن ہٕندِس گرس مطٲبق، وُہن وُہُن وُہُر تہٕ امہِ کھوتہٕ زیادٕ، سارِنٕے یِم جنگس منز نیرنس لایق ٲسۍ۔\n33.\\tیِمن ہُند تعداد اوس افرائیم سٕندِس قبیلس منز، تِم ٲسۍ ژتٲجی ساس پانژھ ہتھ۔\n34.\\tمنسی ہٕندِس شُرِس منز، تِہندِ عیال پتہٕ، پننین مٲلن ہٕندِس گرس سٍتـ̡ ، وُہن وُہُن وُہُر وٲنسہِ پیٹھٕ تہٕ زیادٕ وٲنسہِ ہٕندِس ناوَن ہٕندِ تعدادٕ مُطٲبق، سارِنٕے یِم جنگس منز نیرنس لایق ٲسۍ۔\n35.\\tیِمن منز یِمن ہُند شمار اوس کرنہٕ آمُت، تِمن ہُند تعداد اوس مناسشہ کِس قبیلس منز، تِمن ہُند تعداد اوس ترہ زٕ ساس زٕ ہتھ۔\n36.\\tبنیامین سٕندِ شُرۍ، تِہٕندِس عیالس پتہٕ، پننین مٲلن ہٕندِس گرٕ سٍتـ̡ ، وُہن وُہُن وُہُر تہٕ اَمہِ کھۄتہٕ زیادٕ ناوَن ہٕندِ تعدادٕ مُطٲبق، سارِنٕے یِم جنگس مَنٛز نیرنس لایق ٲسۍ۔\n37.\\tیِمن ہُند تعداد اوس بنیامین سٕندِ قبیلہٕ سٍتـ̡ {even } ترٕہ پانژھ ساس ژور ہتھ۔\n38.\\tدانن ہٕندِس شُرین ہٕندِس نسلہٕ سٍتـ̡ ، پننین عیالن ہٕندِس گرٕ سٍتـ̡ ، وُہن وُہُن وُہُر تہٕ اَمہِ کھۄتہٕ زیادٕ وٲنسہِ ہٕندِس ناون ہٕندِس تعدادس مُطٲبق، سارِنٕے یِم جنگس منز نیرنس لایق ٲسۍ۔\n39.\\tیِمن منز یِمن ہُند تعداد اوس دِنہٕ آمُت، تِم ٲسۍ تریہ تہٕ زٕ ساس ستھ ہتھ۔\n40.\\tآشر سٕندٮ۪ن شُرین ہٕندِس نسلہٕ سٍتـ̡ ، پننین عیالن ہٕندِس گرٕ سٍتـ̡ ، وُہن وُہُن وُہُر تہٕ زیادٕ وٲنسہِ ہٕندِس ناون ہٕندِ تعدادٕ مُطٲبق ، سارِنٕے یِم جنگس منز نیرنس لایق ٲسۍ۔\n41.\\tیِمن ہُند تعداد اوس آشر قبیلس منز، {حتیٰ کہ} ٲسِکھ ژتٲجی تہٕ اکھ ساس پانژھ ہتھ۔\n42.\\tنفتالی ہٕندٮ۪ن شُرین منز، پننین خاندانن پتہٕ، پننین مٲلن ہٕندِ گرٕ سٍتۍ، وُہن ؤرین تہٕ امہِ کھوتہٕ زیادٕ ناوَن ہٕندِ تعدادٕ مطٲبق، سارِنٕے یِم جنگس منز نیرنس لایق ٲسۍ۔\n43.\\tیِمن ہُند تعداد اوس نفتالی قبیلہٕ سٍتـ̡ {حتیٰ کہ} پنژاہ تریہ ساس ژور ہتھ۔\n44.\\tیِم چھِ تِم یِم موسیٰ تہٕ ہارون گنزراونہٕ آمٕتۍ ٲسۍ، تہٕ اسرٲیلٕکۍ شہزادٕ ٲسۍ باہ نفر: پرٮ۪تھ اکھ اوس پننین مٲلن ہٕندِس گرس خٲطرٕ۔\n45.\\tیِتھے پٲٹھـ̡ تِم سارِنٕے یِم اسرٲیلـ̡ سٕندِس مٲلِس سٍتـ̡ وُہن وُہُن وٲنسہِ پى۪ٹھہٕ وٲنسہِ پى۪ٹھ، سارِنٕے یِم اسرٲیلـ̡ سٍتـ̡ جنگس مَنٛز نیرنس لایق ٲسۍ۔\n46.\\tتِمن سارِنٕے سٍتـ̡ یِمن ہُند تعداد اوس شیہ ہتھ تہٕ تریہ ساس تہٕ پانژھ ہتھ پنژاہ۔\n47.\\tمگر لاوی تہندِس مٲلہِ سٕندِس قبیلس پٲٹھۍ، تِمن منز اوس نہٕ شمار کرنہٕ آمُت۔\n48.\\tکیازِ خداوند اوس موسیٰ ہس سٍتـ̡ کتھ کٔرمٕژ،\n49.\\tصرف گژھ نہ لیوی قبیلہٕ گنزراونہٕ تہٕ نہ کرو تِمن ہُند تعداد بنی اسرٲیلِس منز۔\n50.\\tمگر توے کرِ لاوی شہادت کِس خیمہ خانس پیٹھ، تہٕ اَمہ کِس سارِنٕے بانن تہٕ سارِنٕے چیزن پى۪ٹھ، تِم گژھن خیمہ تہٕ اَمہ سٍتـ̡ سارِنٕے بانہٕ رٔٹِتھ۔ تہٕ تِم کرَن اَتھ خدمت تہٕ خیمہ خانس اندۍ اندۍ اندۍ ڈیرٕ۔\n51. تہٕ یێلہِ خیمہ برونہہ کُن بِہِتھ، لاوی یِن سُہ بۄن تہٕ یێلہِ خیمہ لاگنہٕ یِن، لاوی یِن سُہ قٲیم کرنہٕ۔\n52.\\tتہٕ بنی اسرٲیلِس پَنٕنہِ خیمہ لگاوُن، پرٮ۪تھ کانہہ شخص پنہٕ نِس خٲمہٕ سٍتـ̡ تہٕ پرٮ۪تھ کُنہِ شخٕص پَنٕنـ̡ پَنٕنـ̡ سٍتـ̡ پَنٕنـ̡ سٍتـ̡ پَنٕن\n53.\\tمگر لاوی گژھن گوٲہی ہٕندِس خیمہ خانس اندۍ پٔکھۍ پھیُرُن، یُتھ زن بنی اسرٲیلِچ جماعت ہٕندِس اجتماعس پیٹھ گژھہِ نہٕ کانہہ قہر تہٕ لاوی گوٲہی ہٕندِس خیمہ ہُند ذمہ دار۔\n54. تہٕ بنی اسرٲیلیو کٔر یُس خداوند موسیٰ سُند حکم دِیُتمُت اوس تِمو تہِ کٔرِتھ۔","1. تہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ کتھ ،\n2. بنی اسرٲیلُک پرٮ۪تھ کانہہ شخص گژھِ پننِس مٲلہِ سٕندِس گرس ہُند جھنڈٕ ہیتھ پننہِ معیارٕ سٍتـ̡ پَنٕنـ̡ پۯاونہٕ یُن۔ {دور...: ہیب۔ اوور اگینسٹ}\n3.\\tتہٕ مشرقس کُن آفتاب کھسنہٕ کِس طرفہٕ گژھن یہوداہ کِس خٲمہِ ہٕندِس معیارس سٍتـ̡ پنہٕ نِس فوجس مَنٛز رٔلِتھ تہٕ اَمیناڈاب سُند نیچو نہشون بنہِ یہوداہ کِس اولادَن ہُند کپتان۔\n4.\\tتہٕ تٔمۍ سُند میزبان، تہٕ یِمن ہُند تعداد اوس، ٲسۍ تریہ تہٕ ژۅداہ ساس تہٕ شیہ ہتھ۔\n5.\\tیُس أمِس سٍتـ̡ رٔلِتھ آسہِ، تِم آسہِ اِسخرُک قبیلہٕ، تہٕ نیتھانیل یُس زوار سُند نیچو آسہِ، یُس عیساکار سٕندٮ۪ن شُرین ہُند کپتان۔\n6.\\tتہٕ تٔمۍ سُند میزبان، تہٕ یِمن ہُند تعداد اوس، تِم ٲسۍ پنژاہ ژور ساس ژور ہتھ۔\n7.\\tزیبولون قبیلہٕ: تہٕ ہیلون سُند نیچو الیاب بنہِ زبولون کین بچن ہُند کپتان۔\n8.\\tتہٕ تٔمۍ سُند میزبان، تہٕ یِمن ہُند تعداد اوس، ٲسۍ پنژاہ ستھ ساس ژور ہتھ۔\n9.\\tیہوداہ کِس خٲمس مَنٛز یِم سارِنٕے گٔژِھتھ ٲسۍ تِمن ہٕندِس فوجس مَنٛز اکھ لچھ تہٕ ژور ساس تہٕ شیہ ساس تہٕ ژور ہتھ۔ یِم گژھن گۄڈٕ شروع کرنہٕ۔\n10.\\tجنوبس طرفہٕ آسہِ روبن سٕندِ خٲمہِ ہُند معیار تہٕ روبن سٕندِ شُرین ہُند کپتان آسہِ شیدیور سُند نیچو۔\n11. تہٕ تٔمۍ سُند میزبان، تہٕ یِمن ہُند تعداد اوس، ٲسۍ ژتٲجی تہٕ شیہ ساس پانژھ ہتھ۔\n12.\\tیُس أمِس سٍتـ̡\n13.\\tتہٕ تٔمۍ سُند میزبان، تہٕ یِمن ہُند تعداد اوس، تِمن ہُند تعداد اوس پنژاہ تہٕ نو ساس ترے ہتھ۔\n14.\\tگاد سُند قبیلہٕ: تہٕ گاد سٕندِس نیچوُن ہُند کپتان آسہِ، یُس ریویل سُند نیچو آسہِ۔ {Reuel: تہٕ چُھ ونان، ڈیول}\n15.\\tتہٕ تٔمۍ سُند میزبان، تہٕ یِمن ہُند تعداد اوس، تِم ٲسۍ ژتٲجی تہٕ پانژٕ ساس تہٕ شیہ ہتھ پنژاہ۔\n16.\\tروبن سٕندِس خٲمس مَنٛز یِم سارِنٕے گٔمٕتۍ ٲسۍ، تِمن ہٕندِس فوجس منز ٲسۍ اکھ لچھ پنژاہ ساس تہٕ اکھ ساس ژور ہتھ پنژاہ۔ تہٕ تِم گژھن دوٚیمِس درجَس مَنٛز نیران۔\n17. تیلہِ گژھہِ جمٲژ ہُند خیمہ لیوی ہٕندِس خٲمس سٍتـ̡ برونہہ کُن نیرُن، یێلہِ تِم یێلہِ تِمن ہٕندِس معیارس مُطٲبق پنہٕ نِس جایہِ پٲٹھۍ۔\n18.\\tمغرب طرفہٕ آسہِ افرائیم سٕندِ خٲمہِ ہُند معیار تہٕ افرائیم سٕندِس نیچوُن ہُند کپتان آسہِ امیہود سُند نیچو۔\n19.\\tتہٕ تٔمۍ سُند میزبان، تہٕ یِمن ہُند تعداد اوس ژتٲجی ساس تہٕ پانژھ ہتھ۔\n20.\\tتہٕ تٔمِس سٍتـ̡ آسہِ منسیٰ سُند قبیلہٕ، تہٕ منسی ہٕندِس اولادَن ہُند کپتان آسہِ گمالیئیل، یُس پیڈہزور سُند نیچو آسہِ۔\n21.\\tتہٕ تٔمۍ سُند میزبان، تہٕ یِمن ہُند تعداد اوس، تِمن ہُند تعداد اوس ترٕہ زٕ ساس تہٕ زٕ ہتھ۔\n22. پَتہٕ بنیامین سُند قبیلہٕ: تہٕ بنیامین سٕندِس نیچوُن ہُند کپتان آسہِ عابدان، یُس گِدعونی سُند نیچو آسہِ۔\n23.\\tتہٕ تٔمۍ سُند میزبان، تہٕ یِمن ہُند تعداد اوس، ٲسۍ ترہ تہٕ پانژٕ ساس ژور ہتھ۔\n24.\\tافرائیم سٕندِس خٲمس مَنٛز یِم سارِنٕے گٔمٕتۍ ٲسۍ، تِمن ہٕندِس فوجس منز ٲسۍ اکھ لچھ ٲٹھ ساس تہٕ ہتھ ۔ تہٕ تِم گژھن تریمہِ درجس منز برونہہ کُن۔\n25.\\tدان سٕندِ خٲمہِ ہُند معیار آسہِ شمالس کُن تہندِس فوجس سٍتـ̡ تہٕ دانن ہٕندِس شُرین ہُند کپتان آسہِ اَمیشادایی ہُند نیچو۔\n26.\\tتہٕ تٔمۍ سُند میزبان، تہٕ یِمن ہُند تعداد اوس، ٲسۍ تریہ تہٕ زٕ ساس ستھ ہتھ۔\n27.\\tتہٕ یِم أمِس سٍتـ̡ ڈیرٕ تراوان چِھہ، تِم آسہِ آشرُک قبیلہٕ: تہٕ آشر سٕندِس شُرین ہُند کپتان آسہِ اوکران سُند نیچو۔\n28.\\tتہٕ تٔمۍ سُند میزبان، تہٕ یِمن ہُند تعداد اوس ژتٲجی تہٕ اکھ ساس پانژھ ہتھ۔\n29.\\tپَتہٕ نفتالی ہُند قبیلہٕ: تہٕ نفتالی ہٕندٮ۪ن شُرین ہُند کپتان آسہِ اِنان سُند نیچو۔\n30.\\tتہٕ تٔمۍ سُند میزبان، تہٕ یِمن ہُند تعداد اوس، ٲسۍ پنژاہ تریہ ساس ژور ہتھ۔\n31.\\tدان سٕندِس خٲمس مَنٛز یِم سارِنٕے شُمار ٲسۍ، تِم ٲسۍ اکھ لچھ ساس ستھ ساس شیہ ہتھ۔ تِم گژھن پننین معیارن سٍتۍ پتھ کُن۔\n32.\\tیِم چھِ تِم یِم تِمن ہٕندِس مٲلِس سٍتـ̡ گٔنزراوٕنـ̡ سٍتـ̡ شیہ لچھ تہٕ ترے ساس تہٕ پانژھ ہتھ پنژاہ ٲسۍ۔\n33. مگر لاوی ٲسۍ نہٕ بنی اسرٲیلِس مَنٛز شمار کرنہٕ آمٕتۍ۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n34. تہٕ بنی اِسرٲیلِو کٔر یُس خداوند موسیٰ سُند حکم دِیُتمُت اوس تِمو کٔرِتھ تہٕ یِتھٕ پٲٹھۍ کٔر تِمو پننِس مٲلِس سٕندِ گرٕ مُطٲبِق پنہٕ نِس عیالس پٲٹھۍ۔","1. یِم تہِ چھِ ہارون تہٕ موسیٰ سٕنزِ نسلہٕ سٍتـ̡ ییمہِ دۅہہٕ {یُس}خداوند کُنہِ سینا کِس پہاڑس مَنٛز موسىٰ سٍتـ̡ کتھ کٔر۔\n2. تہٕ یِم چھِ ہارون سٕندٮ۪ن نیٚچوٮ۪ن ہٕندِ ناو۔ نداب گوڈنیک زامُت، تہٕ ابیہو، الیعازر تہٕ اِتھمار۔\n3. یِم چھِ ہارون سٕندٮ۪ن نیچوین ہٕندِ ناو، یِم پادٕرۍ مسح کرنہٕ آمٕتۍ ٲسۍ، یِم تٔمۍ پادٕرۍ سٕندِس دفترس مَنٛز خدمت کرنہٕ خٲطرٕ وقف کٔرۍ۔ {کُس...: ہیب۔ کمۍ سُند اتھہٕ اوس بٔرتھ}\n4. تہٕ نداب تہٕ ابیہو گٔیہِ خداوند سٕندِ برونہہ کُن، ییلہ تِمو سینا کِس بیابانس مَنٛز خداوند سٕندِس برونہہ کُن عجیب نار پیش کٔر، تہٕ تمن اوس نہٕ کانہہ شُر: تہٕ الیعازر تہٕ اِتھمار کٔر پننِس مٲلس ہارون سٕندِس نظرس منز پادٕرۍ سٕندِس دفترس مَنٛز خدمت۔\n5. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n6.\\tلاوی قبیلہٕ أنِو نزدیک، تہٕ تِم کٔرِو ہارون سٕندِس برونہہ کُن پیش، یُتھ تِم أمِس خدمت کٔرِتھ۔\n7. تہٕ تِم تھاون تٔمۍ سُند ذمہ دار، تہٕ سارِنٕے جماعتُک ذمہ داری، یُس خیمہ خانہٕ کِس خٲمس برونہہ کُن تھاوُن۔\n8.\\tتہٕ تِم تھاون جمٲژ ہٕندِس خیمہ ہٕندِس سارِنٕے آلات، تہٕ بنی اسرٲیلِچ خدمت کرنہٕ خٲطرٕ۔\n9. تہٕ توے دِیُن لاوی ہارونس تہٕ تٔمۍ سٕندِس نیچوِس دِنہٕ۔\n10. تہٕ تُہۍ کٔرِو ہارون تہٕ تٔمۍ سٕندِس نیچوِس مُقرر تہٕ تِم گژھن پننِس پادٕرۍ سٕندِس عہدس پیٹھ پیارُن، تہٕ یُس اجنبی یُس نزدیک یِیہِ مارنہٕ۔\n11. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n12. تہٕ وُچھمُت بہٕ چُھس اسرٲیِل کِس بُلِس مَنٛز لاوی نِش نِنہٕ آمُت یُس سارِنٕے گۅڈنِچہِ اولاد سٍتـ̡ یُس بنی اسرٲیلِس مَنٛز چُھہ کھولان چُھ، تێمہِ مۅکھہ آسہِ لاوی میٲنۍ ۔\n13.\\tکیازِ سارِنٕے گۅڈنِچ اولاد چھِ میٲنۍ ۔ {کیازِ} ییمہِ دۅہہ میہ مصرٕکِس سرزمینس مَنٛز سارِنٕے گۅڈنِچہِ زُو زامُت دِژ، میہ کٔر پانس خٲطرٕ سارِنٕے گۅڈنِچ زٲنِتھ، انسان تہٕ جانور دونوی: تِم آسن میٲنۍ آسن: بہٕ چُھس خداوند ۔\n14. تہٕ خداوند کٔر سینا کِس بیابانس مَنٛز موسیٰ سٕنز کتھ ،\n15.\\tلیوی سٕندِ شُرِ ہُند شُمار کٔرِو تِہندِ مٲلہِ سٕندِس گرس سٍتـ̡ تہندِس عیالس سٍتـ̡ شُمار کرنہٕ۔\n16. تہٕ موسىٰ کٔر تِم خداوند سٕندِ کلامٕ مُطٲبق گنزراونہٕ، یُس أمِس حکم اوس دِنہٕ آمُت۔ {لفظ: ہیب۔ ٲس}\n17.\\tتہٕ یِم ٲسۍ لیوی سٕندِ نیچوۍ ناوٕ سٍتـ̡ ۔ گرشون، تہٕ کوہتھ، تہٕ میراری۔\n18.\\tتہٕ یِم چھِ گرشون سٕندٮ۪ن نیٚچوٮ۪ن ہٕندِ ناو۔ لبنی تہٕ شیمی۔\n19.\\tتہٕ کوہات سٕندِ نیچوۍ تہندِس عیالس سٍتـ̡ ۔ امرام، تہٕ ایزہار، ہیبرون تہٕ عزیل۔\n20.\\tتہٕ میراری سٕندِ نیچوۍ تہندِ عیالہٕ سٍتـ̡ ۔ مہلی، تہٕ مشی۔ یِم چھِ تِہنٛدین مٲلن ہٕندِ گرٕ مُطٲبِق لاوِین ہُند خاندان۔\n21.\\tگرشون سُند خاندان اوس لبنین ہُند خاندان، تہٕ شِمتین ہُند خاندان: یِم چھِ گرشونیتن ہُند خاندان۔\n22.\\tیِمن ہُند تعداد اوس سارِنٕے نَرن ہٕندِ تعدادٕ مُطٲبق، اَکہِ رٮ۪تہٕ وٲنسہِ پیٹھٕ تہٕ اَمہِ کھۄتہٕ زیادٕ، یِمن ہُند تعداد اوس سَتھ ساس تہٕ پانژھ ہتھ۔\n23.\\tگرشونیتن ہٕندِ عیال گژھن خیمہ خانس پتھ کُن مغربس کُن۔\n24.\\tتہٕ گرشونیتن ہٕندِس مٲلِس سٕندِس گرُک سردار آسہِ، یُس لایل سُند نیچو آسہِ۔\n25.\\tتہٕ گرشون سٕندِس نیچوِس ہُند ذمہ دار آسہِ خیمہ تہٕ خیمہ تہٕ اَمہ ہٕندِس دروازس پیٹھ پھانسی دِنہٕ۔\n26.\\tتہٕ صحنُک پھانسی تہٕ دربارٕکہِ دروازُک پردٕ، یُس خیمہ خانہٕ سٍتـ̡ تہٕ قربان گاہٕ سٍتـ̡ چُھ، تہٕ اَمہ کِس سارِنٕے خدمتہٕ خٲطرٕ چُھہ اَمہِ سٍتـ̡ رَزٕ۔\n27.\\tتہٕ کوہات سُند خاندان، تہٕ ایزہارین ہُند خاندان، تہٕ حبرونین ہُند خاندان، تہٕ عزیلین ہُند خاندان: یِم چھِ کوہاتی خاندان۔\n28.\\tسارِنٕے مردن ہٕندِس تعدادس منز، اَکہِ رٮ۪تہٕ پیٹھٕ تہٕ اَمہِ کھۄتہٕ زیادٕ وٲنسہِ، ٲٹھ ساس شیہ ہتھ ٲسِتھ، یُس مقدس مقامُک ذمہ دار اوس۔\n29.\\tکوہات کین نیچوین ہٕندِ عیال گژھن خیمہ کِس جنوبس کُن رٔٹِتھ۔\n30.\\tتہٕ کوہثین ہٕندِس خاندانن ہٕندِس مٲلِس سٕندِس گرُک سردار آسہِ عزیل سُند نیچو۔\n31. تہٕ تِہُند ذِمہٕ آسہِ صندوق، تہٕ میز، تہٕ شمعدان، قربان گاہٕ، تہٕ مقدس مقامٕچ بانہٕ یِمن سٍتـ̡ تِم خدمت کران چھِ، تہٕ پھانسی تہٕ اَمہ ہٕنزِ سارِنٕے خدمت۔\n32.\\tتہٕ ہارون سُند نیچو الیعازر بنہِ لاوِین ہٕندِس سردارس پیٹھ سردار، تہٕ یِمن ہٕندِس نِگارس سٍتـ̡ یِم مقدس مقامس پیٹھ رٔٹِتھ آسہِ۔\n33.\\tمیراری ہُند خاندان اوس مہلٮن ہُند تہٕ مشیتن ہُند خاندان: یِم چھِ میراری ہُند خاندان۔\n34.\\tتہٕ یِمن منز سارنٕے مردن ہٕندِ تعدادٕ مُطٲبق ٲسۍ أکِس ریتس پیٹھٕ تہٕ امہِ کھوتہٕ زیادٕ شیہ ساس تہٕ زٕ ہتھ۔\n35.\\tتہٕ میراری خاندانن ہٕندِس مٲلہِ سٕندِس گرُک سردار اوس ابیحیل سُند نیچو زُریئل: {یِم} گژھن خیمہ کِس طرفہٕ شمالس کُن۔\n36.\\tتہٕ میراری کین نیچوین ہٕنزِ تحویل تہٕ ذمہ داری آسہِ خیمہ ہٕندِس تختس تہٕ اَمہِ ہٕندِس سٍتـ̡ تہٕ اَمہِ ہٕندِس ستونہٕ تہٕ اَمہِ ہٕندِس سارِنٕے بانہٕ تہٕ سارِنٕے بانہٕ تہٕ یِمن ہٕندِس سارِنٕے سٍتـ̡ خدمت کرٕنـ̡ ﴿تَر...: حب﴾۔ چارج سُند دفتر}\n37.\\tتہٕ دربارٕکۍ تھَم تہٕ تِہٕندِ ساکٹ، تہٕ تِہٕنزِ پِنہٕ تہٕ تِہٕنزِ رَزٕ۔\n38.\\tمگر یُس مشرقس کُن خیمہ خانس برونہہ کُن ڈیرٕ تراوان چُھ، {حتیٰ کہ} مشرقس کُن جماعت کِس خیمہ برونہہ کُن، موسیٰ تہٕ ہارون تہٕ تٔمۍ سٕندِ نیچوۍ، یِم بنی اسرٲیلِن ہٕندِ خٲطرٕ مقدس مقامچ ذمہ داری تھاوان چھِ۔ تہٕ یُس اجنبی یُس نزدیک یِیہِ مارنہٕ۔\n39.\\tیِم سارِنٕے لاوِین ہُند شُمار اوس کرنہٕ آمُت، یُس موسىٰ تہٕ ہارون خداوند سٕندِس حُکمس مُطٲبق گنزراونہٕ آمُت اوس، سارِنٕے نَر ٲسۍ اَکہِ رٮ۪تہٕ پیٹھٕ تہٕ اَمہِ کھۄتہٕ زیادٕ سارِنٕے مرد وُہُن تہٕ زٕ ساس۔\n40. تہٕ خداوند ووٚن موسیٰ سٕندِس زِ اَکہِ رٮ۪تہٕ وٲنسہِ پیٹھٕ تہٕ اَمہِ کھۄتہٕ زیادٕ وٲنسہِ ہٕندِس سارِنٕے نَرَن ہُند گٔنزراوُن تہٕ تِمن ہُند ناو ہییُن۔\n41. تہٕ تێہہ رٔٹِو میانہِ خٲطرٕ لاوی (بہٕ چُھس خداوند چُھہ) بنی اسرٲیلِس مَنٛز سارِنٕے گۅڈنِکِس زامتس بجایہ۔ تہٕ بنی اسرٲیلِن ہٕندِس چارواین منز سارِوٕے گۅڈنچہ بجایہ لاوِین ہٕندِس چاروٲے سٍتـ̡ ۔\n42. تہٕ موسىٰ کٔر خداوند سُند حکم دِنہٕ آمُت، بنی اسرٲیلِس مَنٛز سارِنٕے گۅڈٕ زامُت۔\n43.\\tتہٕ سارِنٕے گۅڈنِچہِ نَرٕچ تعداد مُطٲبِق، یِمن ہُند تعداد اوس أکِس ریتس پیٹھٕ تہٕ اَمہِ کھۄتہٕ زیادٕ، تِمن ہُند تعداد اوس وُہ زٕ ساس زٕ ہتھ تہٕ ترہ تہٕ ترہ وُہُن۔\n44. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ کتھ ،\n45.\\tبنی اسرٲیلِس مَنٛز سارِوٕے گۅڈنچہ اولاد بجایہ رٔٹِو لاوی تہٕ لاوِین ہٕندِ چاروِ بجایہ رٔٹِو۔ تہٕ لاوی گژھن میٲنۍ آسن: بہٕ چُھس خداوند چُھس۔\n46. تہٕ یِمن ہٕندِ خٲطرٕ یِم اسرٲیلِکۍ اولاد ہٕندِس زٕ ہتھ تریہ ترہ تہٕ ترہ زُو چھِ نجات دِنہٕ یِن، یِم لاویو کھوتہٕ زیادٕ چھِ۔\n47.\\tژیہ پانژھ شیکل تہِ نِن، مقدس مقامس منز شیکل گژھنہ پتہ تہِ نِن:(شیکل {is} وُہ گیرہ:)\n48.\\tتہٕ تُہۍ دِیُن پونسہٕ، یێمہِ سٍتـ̡ یِمن ہُند طاق تعداد چھُ یِوان دِنہٕ، ہارونس تہٕ تٔمۍ سٕندِس نیچوِس دِنہٕ۔\n49.\\tتہٕ موسىٰ ہیوٚت تِمن ہٕندِس فدٲژ ہٕندِس پٲنسہٕ یِم لاویو دٔسۍ چھِنہٕ آمٕتۍ۔\n50. بنی اسرائیل سٕندِس گۅڈنِکِس زامتس سٍتـ̡ رٔٹِتھ رٔٹـ̡ اکھ ساس تریہ ہتھ تہٕ پانژھ {شیکل}، مقدس مقامک شیکل پتہٕ:\n51. تہٕ موسىٰ دِژ تِمن ہٕندِ پٲنسہٕ یُس خداوند سٕندِ کلامٕ مُطٲبق ہارون تہٕ تٔمۍ سٕندِس نیچوِس دِنہٕ آمُت اوس، یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔","1. تہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ کتھ ،\n2.\\tلیوی سٕندٮ۪ن نیچویو منزٕ نِیُن تہندِس مٲلِس سٕندِس گرس سٍتـ̡ کُہات سٕندِس نیچوِس سٍتـ̡ رٔٹِتھ\n3. ترہ وُہُر وٲنسہِ پیٹھٕ پنژاہ وُہُر وٲنسہِ تام یِم سٲری میزبانس مَنٛز دٲخل سپدان چھِ، جماعت کِس خیمہ خانس مَنٛز کٲم کرنہٕ خٲطرٕ۔\n4. یہِ گژھہِ حضرت کِس خیمہ خانس مَنٛز کوہات سٕندٮ۪ن نیٚچوٮ۪ن ہٕنز خدمت، {مُقدس} کتھِ مُتلِق :\n5. تہٕ یێلہِ یێلہِ خۅم برونہہ کُن بِہِتھ، ہارون تہٕ تٔمۍ سٕندِ نیچوۍ یِن تہٕ تِم یِن پردٕ تہٕ گوٲہی ہٕندِس صندوقس سٍتـ̡ ؤلِتھ:\n6.\\tتہٕ اتھ پیٹھ تراوُن بٔرِس کھالُک پوشہٕ، تہٕ اتھ پیٹھ گژھہِ پوٗرٕ نیوٗل پلو لاگُن، تہٕ اَمہ کِس ڈنڈس منز تراوُن۔\n7.\\tتہٕ شیو بریڈ کِس میزس پیٹھ ترٲوِن تِم نیوٗل رنٛگُک پلو تہٕ اَتھ پیٹھ تھووُن برتن تہٕ چمچہٕ تہٕ پیالہ تہٕ پوشہٕ تہٕ اتھ پیٹھ گژھن مسلسل روٹی یِنہٕ: {کور ...: یا تراوُن سٍتۍ}\n8.\\tتہٕ تِم یِمن پیٹھ سرخ پوشہٕ لاگُن، تہٕ سُہ لٔگِتھ لٔگِتھ تہٕ یِمن ہٕندِس لٔٹِس منز تراوُن۔\n9.\\tتہٕ تِم نِن نیوٗل رنٛگُک پلو، تہٕ گاشُک شمع، تہٕ تٔمۍ سٕندِس چراغَس تہٕ تٔمۍ سٕندِس چمڑس تہٕ تٔمۍ سٕندِس نِش تہٕ تِمن ہٕندِس سارِنٕے تیٖلٕکۍ بانہٕ ؤلِتھ، یِمن سٍتـ̡ تِم اَتھ سٍتـ̡ خدمت کران چھِ:\n10. تہٕ تِم تھاون یہِ تہٕ اَمہِ سٕندِس سارِنٕے بانہٕ بٔرِس کھالَس منز، تہٕ تھاوُن أکِس سلاخس پیٹھ۔\n11. تہٕ سۄنہٕ قربان گاہَس پیٹھ پھٔہلِن تِم نیوٗل رنٛگُک پلو، تہٕ اَتھ کٔرِن بٔرِن ہٕندِس کھالہٕ سٍتـ̡ ؤلِتھ، تہٕ اَتھ کِس لٔٹِس پٲٹھۍ۔\n12.\\tتہٕ تِم نِن وزارتٕکۍ سٲری آلات، یِمو سٍتـ̡ تِم عبادت گاہَس مَنٛز خدمت کران چھِ، تہٕ تِمن نِش نیوٗل پلو لاگُن، تہٕ یِمن ہٕندِس کھالَس سٍتـ̡ تھپھ کٔرِتھ، تہٕ یِمن ہٕندِس سلاخس پیٹھ:\n13. تہٕ تِم کٔڈِن قربان گاہٕ پیٹھٕ سوٗر تہٕ اَتھ پیٹھ واگن رنگُک پلو پھٔہلِتھ:\n14.\\tتہٕ تِم تھاون اَتھ سٍتـ̡ سارِنٕے بانہٕ، یێمہِ سٍتـ̡ تِم اَتھ سٍتـ̡ خدمت کران چِھ، حتیٰ کہِ سٍتـ̡ چِھہ سٍتـ̡ س� تہٕ تِم پھٔہلِن اَتھ پٮ۪ٹھ بٔڑٮ۪ن ہٕنٛدٮ۪ن کھالن ہُنٛد اکھ پردٕ، تہٕ اَتھ ہٕنٛدِس لٔٹِس پٮ۪ٹھ ترٛاونہٕ۔ {بیسن: یا، پیالہٕ}\n15. تہٕ یێلہِ ہارون تہٕ تٔمۍ سٕندِس نیچویو مقدس مقامس تہٕ مقدس خانہٕ ہٕندِس سارِنٕے بانہٕ ہُند احاطہ کرُن ختم کرُن، یێلہِ زن خٲمہٕ برونہہ کُن گژھُن۔ اَمہِ پتہٕ یِن کوہات سٕندِ نیچوۍ یِن {یہ} مگر تِم گژھن نہٕ {کُنہِ} مُقدس چیزس اَتھٕ لاگن، نتہٕ گژھن تِم مَرٕ۔ یِم {چیز} چِھہ جماعت کِس خیمہ خانس منز کوہات سٕندٮ۪ن نیچوین ہُند بوج۔\n16.\\tتہٕ ہارون سٕندِس نیچوِس الیعزر سٕندِس دفترس مُتلِق چُھہ گاشہٕ خٲطرٕ تیٖل تہٕ مٔدٕر بُن، تہٕ دِشُک ماز تہٕ مسح کرنُک تیل، تہٕ سارنٕے خیمہ خانن ہٕنز نگرٲنی تہٕ اَتھ مَنٛز موجود سارِنٕے چیزن ہٕنز نگرٲنی کرٕنۍ۔\n17. تہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ کتھ کرنہٕ،\n18.\\tلاوِین منزٕ کٔرِو نہٕ کوہاتی خاندانن ہٕندِس قبیلس منزٕ ژٹُن:\n19.\\tمگر یِتھٕ پٲٹھۍ کرو تِمن سٍتـ̡ یێلہِ تِم زندٕ روزن، تہٕ یێلہِ تِم مقدس چیزن تام واتناوٕن: ہارون تہٕ تٔمۍ سٕندِس نیچوِس گژھن اژُن، تہٕ یِم پرٮ۪تھ أکِس پننہِ خدمتہٕ تہٕ پننِس بوجھس خٲطرٕ مقرر کرنہٕ۔\n20.\\tمگر تِم گژھن نہٕ اژنہٕ مۅکھہٕ یِم مقدس چیز کٔرِتھ چھِ، نتہٕ گژھن تِم مرُن۔\n21. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n22.\\tگرشون سٕندٮ۪ن نیچوٮ۪ن ہُند رقم تہِ رٔٹِو، تِہندین مٲلن ہٕندِس گرس منز، تہندِس عیالس سٍتـ̡ نِیو۔\n23.\\tترہ وُہُر وٲنسہِ پیٹھٕ پنژاہ وُہُر وٲنسہِ تام پٔزِو تِمن ہُند گٔنزراوُن۔ یِم سٲری چِھ خدمت انجام دِنہٕ خٲطرٕ دٲخل گژان، جماعت کِس خیمہ خانس مَنٛز کٲم کرنہٕ خٲطرٕ۔ {پرفارم کرنہٕ خٲطرٕ...: ہیب۔ جنگ کرُن}\n24.\\tیہ {چُھ} گرشونائٹن ہٕندِس خاندانن ہٕنز خدمت، خدمت کرنہٕ خٲطرٕ، تہٕ بوجھہٕ خٲطرٕ: {بوجھ: یا، گاڑۍ}\n25. تہٕ تِم گژھن خیمہ خانہٕ ہٕندِ پردٕ، تہٕ جمٲژ ہُند خیمہ تہٕ تٔمۍ سُند پردٕ تہٕ یُس اَتھ پیٹھ ہیرِ کُن چھُ، تہٕ جماعت ہٕندِس خیمہ کِس دروازس پیٹھ پھانسی دِنہٕ۔\n26.\\tتہٕ دربارٕچ پھانسی تہٕ دربارٕکہِ دروازٕ کِس دروازس خٲطرٕ پھانسی دِنہٕ، یُس خیمہ تہٕ قربان گاہٕ سٍتـ̡ چُھ، تہٕ تِہٕنزِ رسٕ، تہٕ تِہٕنزِ خدمتٕکۍ سٲری آلات، تہٕ یِمن ہٕندِ خٲطرٕ بناونہٕ آمٕتۍ سٲری آلات، یِتھٕ پٲٹھۍ گژھن تِم خدمت کرنہٕ۔\n27.\\tہارون تہٕ تٔمۍ سٕندِس نیچوِس سٕنزِ تعیناتی وِزِ گژھِ گرشونیتن ہٕندٮ۪ن نیٚچوٮ۪ن ہٕنزِ سارِنٕے بوجَن تہٕ سارِنٕے خدمتہٕ سٍتـ̡ تہٕ تِمن ہٕندِس سارِنٕے بوجَس مَنٛز تہٕ تِمن ہٕندِس سارِنٕے بوجَس مَنٛز مُقرر کرنہٕ۔ {تقرری: ہیب۔ ٲس}\n28.\\tیہِ چُھہ جماعت کِس خیمہ خانس مَنٛز گرشون سٕندٮ۪ن نیچوین ہٕندِس عیالن ہٕنز خدمت: تہٕ تِہُند ذِمہٕ آسہِ ہارون سٕندِس نیچوِس اِتھامار سٕندِس اتھس تل ۔\n29.\\tیێلہِ زَن میراری ہٕندِس نیچوِس سٍتـ̡ تہندِس عیالس سٍتـ̡ تہندِس گرس سٍتـ̡ گٔنزراوُن۔\n30.\\tترٕہ وُہُر وٲنسہِ پیٹھٕ پنژاہ وُہُر وٲنسہِ تام گژھِو تِمن ہُند گنزراونہٕ یُن، یُس خدمتس مَنٛز دٲخل سپدان چُھ، یُس جماعت کِس خیمہ خانہٕ سٕنز کٲم انجام دِنہٕ باپتھ۔ {سروس: ہیب۔ جنگ}\n31. تہٕ یہِ چُھہ تِہُند بوجُک چارج، جماعت کِس خیمہ خانس مَنٛز تِہٕنزِ سارِنٕے خدمتہٕ مُطٲبِق۔ خیمہ خانہٕ ہٕندِ تختہٕ، تہٕ اَمہ کِس سٲرۍ، تہٕ اَمہ کِس تھَم تہٕ اَمہ کِس ساکٹ،\n32.\\tتہٕ اندۍ پکھۍ دربارٕکۍ تھم، تہٕ تِہٕندِ ساکٹ، تہٕ تِہٕنزِ پِنہٕ تہٕ تِہٕنزِ رزِ، تِہٕندِس سارِنٕے آلاتَس سٍتۍ، تہٕ تِہٕنزِ سارِنٕے خدمتہٕ سٍتـ̡ تہٕ ناوٕ سٍتـ̡ تہٕ تِہٕندِس بوجُک اَلہٕ گٔژھِو۔\n33.\\tیہِ چُھہ میراری کین نیچوین ہٕندِس عیالن ہٕنزِ خدمتہٕ مُطٲبق، جماعت کِس خیمہ مَنٛز، ہارون سٕندِس نیچوِس اِتھمار سٕندِس اتھس سٍتـ̡ خدمت۔\n34.\\tتہٕ موسیٰ تہٕ ہارون تہٕ جماعت ہٕندِس سردارس کٔر کوہثین ہٕندِس نیچوِس تہندِس عیالس پتہٕ تہٕ تِہندین مٲلن ہٕندِس گرس پتہٕ گنزراونہٕ۔\n35.\\tترہ وُہُر وٲنسہِ پیٹھٕ پنژاہ وُہُر وٲنسہِ تام، یُس جماعت کِس خیمہ خانس مَنٛز کٲم کرنہٕ خٲطرٕ خدمتس مَنٛز دٲخل سپدان چُھ:\n36.\\tتہٕ یِمن ہٕندِس عیالس سٍتـ̡ تِمن ہُند تعداد اوس زٕ ساس ستھ ہتھ پنژاہ۔\n37. یِم ٲسۍ کوہاتی خاندانن مَنٛز شمار کرنہٕ آمٕتۍ، یِم سارِوٕے یِم جماعت کِس خیمہ خانس مَنٛز خدمت کٔرِتھ، یُس موسىٰ تہٕ ہارون حضرت موسیٰ سٕندِ اتھہٕ سٍتـ̡ خداوند سٕندِس حکمس مُطٲبق گنزراونہٕ آو۔\n38.\\tتہٕ یِم گرشون سٕندِس نیچوِس سٍتـ̡ تہٕ تِہندین مٲلن ہٕندِس گرس سٍتـ̡ شمار کرنہٕ آمٕتۍ،\n39.\\tترہ وُہُر وٲنسہِ پیٹھٕ تہٕ پنژاہ وُہُر وٲنسہِ تام یُس پرٮ۪تھ کانہہ یُس عبادتس مَنٛز دٲخل سپدان چُھ، یُس جماعت کِس خیمہ کِس کامہِ مۅکھہٕ چُھہ دٲخل سپدان۔\n40.\\tیِمن ہٕندِس مٲلِس سٍتـ̡ یِمن ہٕندِس گرس سٍتـ̡ تِمن ہٕندِس گرس سٍتـ̡ شمار کرنہٕ آمُت اوس، تِم ٲسۍ زٕ ساس تہٕ شیہ ہتھ ترٕہ۔\n41.\\tیِم چھِ تِم یِم گرشون سٕندِس نیچوین ہٕندِس عیالس مَنٛز شمار کرنہٕ آمٕتۍ، یِمن سارِنٕے یِم جماعت کِس خیمہ خانس مَنٛز خدمت کٔرِتھ، یِمن موسىٰ تہٕ ہارون خداوند سٕندِس حکمس مُطٲبق شمار کٔرۍ۔\n42.\\tتہٕ تِم یِمن ہٕندِس مٲلِس سٕندِس گرس سٍتـ̡ میراری ہٕندِس نیچوین ہٕندِس خاندانس مَنٛز شمار کرنہٕ آمٕتۍ،\n43.\\tترہ وُہُر وٲنسہِ پیٹھٕ پنژاہ وُہُر وٲنسہِ تام یُس پرٮ۪تھ کانہہ یُس عبادتس مَنٛز دٲخل سپدان چُھ، یُس جماعت کِس خیمہ مَنٛز کٲم کرنہٕ خٲطرٕ دٲخل سپدان چُھ،\n44.\\tیِمن ہٕندِس عیالس سٍتـ̡ شمار کرنہٕ آمُت اوس، تِم ٲسۍ ترے ساس زٕ ہتھ۔\n45.\\tیِم چھِ تِم یِم مراری سٕندِس نیچوَن ہٕندِس عیالس مَنٛز شمار کرنہٕ آمٕتۍ، یِمن موسىٰ تہٕ ہارون حضرت موسىٰ سٕندِ اتھہٕ سٍتـ̡ خداوند سٕندِ کلامَس مُطٲبق گنزراونہٕ آمٕتۍ۔\n46. یِمن سارِنٕے لوین ہُند شمار اوس، یِمن موسیٰ تہٕ ہارون تہٕ اسرٲیلِکۍ سردار تہٕ تِہندین عیالن پتہٕ تہٕ تِہندین مٲلن ہٕندِس گرس پٲٹھۍ،\n47.\\tترہ وُہُر وٲنسہِ پیٹھٕ پنژاہ وُہُر وٲنسہِ تام یُس پریتھ کانہہ یُس وزارت ہٕنز خدمت کرنہٕ خٲطرٕ یوان اوس، تہٕ جماعت کِس خیمہ خانس مَنٛز بوجٕچ خدمت،\n48.\\tیِمن ہُند تعداد اوس ٲٹھ ساس پانژھ ہتھ ژور۔\n49.\\tخداوند سٕندِ حُکمَس مُطٲبق آیہ تِم موسىٰ سٕندِ اتھہٕ سٍتـ̡ گنزراونہٕ، پرٮ۪تھ أکِس سٕنزِ خدمتہٕ مُطٲبق تہٕ تٔمۍ سٕندِس بوجھہٕ مُطٲبق: یِتھٕ پٲٹھۍ آیہ تِمن ہُند شُمار کرنہٕ، یِتھ کٔنۍ خداوند موسىٰ سُند حُکُم دِیُت۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2.\\tبنی اسرٲیلِس حکم دِیُن زِ تِم کٔرِن پرٮ۪تھ کوڑھ تہٕ پرٮ۪تھ کانہہ یُس مُردن ہٕندِ دٔسۍ ناپاک آسہِ، تہٕ یُس مُردن ہٕندِ دٔسۍ ناپاک آسہِ۔\n3.\\tمرد تہٕ زنانہٕ دۅشوے کٔرِو، یِمن کُنہِ خٲمہٕ ورٲے تراوُن۔ زِ تِم چھِنہٕ پنٕنۍ خٲمَن ناپاک کَران، یَتھ مَنٛز بہٕ روزان چھُس۔\n4. تہٕ بنی اسرٲیلو کٔر یۅہے تہٕ کٔرِکھ تِم خٲمہٕ ورٲے کٔرِتھ، یِتھٕ پٲٹھۍ خداوند موسیٰ سٍتـ̡ کتھ کٔر، تِتھے کٔنۍ کٔر بنی اسرٲیلِ۔\n5. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n6.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، یێلہِ کانہہ مرد یا زنانہٕ کُنہِ تہِ گناہ کرِ یُس مرد کرِ، تہٕ سُہ شخص گژھہِ مجرم ۔\n7. تیلہٕ گژھن تِم پننِس گناہُک اقرار یُس تمو کورمُت چُھ، تہٕ سُہ کرِ پنٕنِس خطاہُک بدلہٕ تہٕ اَتھ مَنٛز دِیہِ پوٗنٛژِم حصہٕ، تہٕ یٔمِس سٍتـ̡ دِیہِ تٔمِس سٍتـ̡ یٔمِس سٍتـ̡ گُناہ آسہِ۔\n8.\\tمگر یێلہِ أمِس شخصس کانہہ رشتہ دار آسہِ نہٕ یُس گناہ کُن بدلہٕ دِنہٕ یُن، یێلہِ گُناہ یُس خداوند سٕندِس سٍتـ̡ دِنہٕ یُن، یێلہِ تہِ گژھہِ پادٕرِس سٍتـ̡ دِنہٕ یُن۔ کفارہٕ کِس رٔمِس سٍتـ̡ یُس تٔمِس خٲطرٕ کفارہ دِنہٕ ییہِ۔\n9. تہٕ بنی اسرٲیلن ہٕندِس سارِنٕے مُقدس چیزن ہُند پرٮ۪تھ کانہہ نذرانہ یُس تِم پادٕرِس نِش انان چھِ، سُہ گژھہِ تٔمۍ سُند آسُن۔ {پیشکش: یا، ہیو پیش کش}\n10. تہٕ پرتھ انسان سُند مقدس چیز گژھہِ تٔمۍ سُند آسُن: یُس کانہہ انسان پادٕرِس دِیہ، سُہ آسہِ تٔمِس سُند۔\n11. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n12.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، تہٕ تِمن ونُن، یێلہِ کٲنٛسہِ مردٕ سٕنزِ زنانہٕ نیرِ، تہٕ تٔمِس سٍتـ̡ زیادٕ زیادتی کرٕن،\n13.\\tتہٕ اکھ مرد گژھہِ أمِس سٍتـ̡ جسمٲنی سٍتـ̡ روزُن، تہٕ سُہ گژھہِ پننِس خاوندس نِش ژوٗرِ تھاونہٕ یُن، تہٕ سُہ گژھہِ نِش نِنہٕ یُن، تہٕ سُہ گژھہِ نہٕ تس خلاف کانہہ گواہ دِنہٕ، تہٕ نہ گژھہِ سُہ نِنہٕ یُن۔\n14. تہٕ حسدُک روح چُھ أمِس سٍتـ̡ یێلہِ تہٕ سُہ گژھہِ پننہِ زنانہِ سٍتـ̡ حسد کٔرِتھ، تہٕ سُہ گژھہِ نہٕ ناپاک کرنہٕ۔\n15.\\tتیلہِ گژھہِ مرد پننہِ زنانہِ پادٕرِس نِش أنِتھ تہٕ سُہ اَنِن أمِس خٲطرٕ دٔہِم حِصہٕ۔ سُہ تراوِ نہٕ اتھ پیٹھ تیٖل تہٕ نہ تراوِ لوبان ۔ تکیازِ یہ چھہ حسدچ پیشکش، یادگارچ پیشکش، یُس بدکاری یادس منز انان چھہ۔\n16.\\tتہٕ پادٕرۍ اَنِن أمِس نزدیک، تہٕ تھاوِ أمِس خداوند سٕندِس برونہہ کُن:\n17.\\tتہٕ پادٕرۍ چُھہ میژِ ہٕندِس بانس مَنٛز مقدس آب نِنہٕ۔ تہٕ خیمہ کِس فرشس منز موجود گردِ سٍتـ̡ یُس پادٕرۍ نِیہِ تہٕ آبس مَنٛز تراوُن:\n18.\\tتہٕ پادٕرۍ کٔرِن زنانہِ ہٕندِس اتھس منز تہٕ زنانہِ ہُند کلہٕ کُل، تہٕ تٔمِس اتھس مَنٛز تراوُن یادگارُک نذرانہ یُس حسدُک نذرانہ چھُ: تہٕ پادٕرۍ سٕندِس اتھس مَنٛز آسہِ سُہ تلخ آب یُس لعنتُک سبب بٔنِتھ:\n19.\\tتہٕ پادٕرۍ کرِ أمِس حلف دِتھ زنانہِ سٍتـ̡ وَنُن، یێلہِ نہٕ تۅہہِ سٍتـ̡ کانہہ مرد آسہِ نہٕ ژے سٍتـ̡ بێیِس سٍتـ̡ ناپاک گٔژھمُت، تێلہِ گژھہِ یێمہِ تلخ آبہٕ نِش آزاد سپدُن یُس بد دُعا کران چُھہ: {بییِس سٍتـ̡...: یا پننِس خاوندس سٍتـ̡ آسنہٕ کِس اِختِیارس منز:  ہیب۔ تہندِس خانٛدارس تحت}\n20.\\tمگر اگر تہۍ پننِس خاوندس بدلہٕ بییِس نِش گٔژھِو، تہٕ یێلہِ تہٕ تۅہہِ بێیہِ تہٕ کانہہ نفر آسہِ تۅہہِ سٍتـ̡ پنہٕ نِس خاوندس سٍتـ̡ لوٚگمُت:\n21. تیلہِ کرِ پادٕرۍ زنانہِ ہُند لعنتُک حلف تہٕ پادٕرۍ زنانہِ ونُن، خداوند بناو تۅہہِ پننہِ لُکہٕ مَنٛز لعنت، تہٕ یێلہِ خداوند تُہٕنزِ رانہِ سٕتہِ تہٕ تُہٕندِس یٔڈ پھۄلِتھ دِیہِ۔ {روٹ: ہیب۔ زوال }\n22.\\tتہٕ یُس آب یُس لعنتُک سبب بنان چُھ، سُہ گژھہِ تۅہہِ ہٕندِس یٔڈ پھۄلاونہٕ مۅکھہٕ، تہٕ زنانہٕ وَنُن آمین، آمین۔\n23.\\tتہٕ پادٕرۍ یِم لعنتٕ أکِس کتابہِ مَنٛز لیکھِتھ، تہٕ سُہ کرِ تِمن تلخ آبہٕ سٍتـ̡ مُٹاونہٕ:\n24.\\tتہٕ سُہ دِیہِ زنانہِ سُہ تلخ آب یُس لعنتُک سبب بنان چُھ، تہٕ یُس آب یُس لعنتُک سبب بنان چُھ، سُہ گژھہِ أمِس اندر اژُن، {تہٕ بنہِ} تلخ بنہِ۔\n25. تیلہِ کٔرِن پادٕرۍ زنانہِ ہٕندِ اتھہٕ منزٕ حسدُک نذرانہ نِش تہٕ خداوند سٕندِس برونہہ کُن نذرانہ لہراوُن تہٕ قربان گاہس پیٹھ پیش کرُن:\n26.\\tتہٕ پادٕرۍ نِیہِ نذرانہٕ مَنٛز اکھ مُٹھہٕ رٔٹِتھ تہٕ دِیہِ قربان گاہس پیٹھ زالنہٕ، تہٕ امہِ پتہٕ دِیہِ زنانہِ آب چنہٕ۔\n27.\\tتہٕ ییلہ أمِس آب چیٚنہٕ خٲطرٕ دِیہِ، تیلہِ گژھہِ یہِ سپدِ، یێلہِ سۄ ناپاک گژھہِ، تہٕ پننِس خاوندس خلاف زیادتی کرِ، سُہ آب گژھہِ أمِس اندر اژُن، تہٕ یُس بد دُعا دِیہِ تٔمِس اندر اژُن، تہٕ تٔمِس یٔڈ گژھہِ پھۄلُن، تہٕ تٔمۍ سٕنزِ رانہٕ گٔژِھہِ، تہٕ زنانہٕ گژھہِ پننین لوکن مَنٛز لعنت۔\n28.\\tتہٕ اگر زنانہٕ ناپاک گژھہِ نہ، بلکہ گژھہِ پاک روزُن۔ تیلہ گژھہِ سۅ آزاد، تہٕ بیول پییہِ۔\n29.\\tیہِ چُھ حسدُک قانون، یێلہِ زنانہٕ پننِس خاوندس بدلہٕ بییِس نِش نیران چِھ، تہٕ سُہ چُھ ناپاک سپدان۔\n30. یا ییلہ تس حسدُک روح ییہِ تہٕ سُہ پننہِ زنانہِ سٍتـ̡ حسد کرِ، تہٕ سُہ کرِ زنانہٕ خداوند سٕندِس برونہہ کُن تھاوُن، تہٕ پادٕرۍ کرِ أمِس سٍتـ̡ یہ سورے شریعت عمل۔\n31.\\tتیلہِ گژھہِ مرد بدکاری سٍتـ̡ بے قصور، تہٕ یہِ زنانہِ گژھہِ پننہِ بدکاری سٍتـ̡ برداش۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، تہٕ تِمن ونُن، یێلہِ کُنہِ تہِ مرد یا زنانہٕ نَصٕر سُند عہد کٔرِتھ، خداوند سٍتـ̡ الگ کرُن: {الگ کرُن...: یا پانس ناصری بناونُک﴾\n3.\\tسُہ گژھِ شرابہٕ تہٕ تیز شرابہٕ نِش الگ کَرُن، تہٕ سُہ گژھِ نہٕ شرابُک سرکہٕ یا تیز شرابُک سرکہٕ چیٚنہٕ، نَہ گژھِ سُہ انگور چیٚنہٕ تہٕ نَہ نم انگور کھٮ۪نہٕ یا خشک کٔرِتھ۔\n4. جدایی ہٕندِس سارِنٕے دۅہس سٍتـ̡ گژھہِ نہٕ سُہ کُلِس سٍتـ̡ بٔنِتھ کھٮ۪نہٕ یُس کُلِس سٍتـ̡ بٔنِتھ آسہِ۔ {علیحدگی: یا، ناصریت} {vine...: Heb. شرابٕچ بیل}\n5. تٔمۍ سٕندِس جدایی ہٕندِس عہد کِس سارِنٕے دۅہہٕ گژھہِ نہٕ تٔمِس کلس پیٹھ کانہہ استرا یِنہٕ: یوتام نہٕ سُہ دۅہ پوٗرٕ گژھن، یێمہِ سٍتـ̡ سُہ خداوند سٍتـ̡ الگ کرِ، سُہ روزِ پاک روزُن، {تہٕ} گژھہِ پننِس کلہٕ سٕندِس مَس ہٕندِس تالہٕ پھٔہلِتھ۔\n6. سارِنٕے دۅہہٕ یێلہِ سُہ خداوند سٕندِس نِش الگ گژھِ، سُہ گژھہِ نہٕ کُنہِ تہِ لاشہٕ سٍتـ̡ یِنہٕ۔\n7. سُہ گژھِ نہٕ پننِس مٲلِس خٲطرٕ، یا ماجہِ، بٲے سٕندِ خٲطرٕ، یا پننہِ بینہِ ہٕندِ خٲطرٕ ناپاک بناوُن، تکیازِ تٔمۍ سٕندِس خدایہِ سٕندِ خٲطرٕ چھُ تٔمۍ سٕندِس کلس پیٹھ۔ {تقدیس: ہیب۔ علیحدگی}\n8. تٔمۍ سٕندِ جدایی ہٕندِ سارِنٕے دۅہہٕ چُھ سُہ خداوند سٕندِ خٲطرٕ پاک۔\n9. تہٕ یێلہِ کانہہ انسان اچانک مٔرِتھ تہٕ تٔمِس سٍتـ̡ تٔمۍ سٕندِس تقدس ہُند سر ناپاک کرِ۔ تیلہِ کرِ سُہ پننہِ پاکیزگی ہٕندِس دۅہس منز کلہٕ کاسُن، سٔتِمہِ دۅہہ کرِ سُہ کلہٕ۔\n10. تہٕ ٲٹھمہِ دۅہہ اَنِن زٕ کچھو، یا زٕ کۅتر پادٕرِس نِش، جماعت کِس خیمہ کِس دروازس پیٹھ۔\n11.\\tتہٕ پادٕرۍ کرِ اَکھ گۅنہٕ نِشہ نذرانہٕ خٲطرٕ، تہٕ بیٛاکھ دِیہِ زالنہٕ خٲطرٕ، تہٕ تٔمِس خٲطرٕ کفارہٕ دِیہِ، یُس تٔمِس مُردٕ سٕندِ دٔسۍ گۅنہٕ کورمُت اوس، تہٕ تٔمِس دۅہہ کرِ تٔمِس کلہٕ پاک کرنہٕ۔\n12. تہٕ سُہ کرِ خداوند سٕندِ خٲطرٕ پننہِ جدایی ہٕندِس دۅہہٕ مقدس تہٕ گۅڈنِکہِ ؤرِیُک اکھ کٹہٕ بچہٕ اَنِن ناپاک کرنہٕ خٲطرٕ، مگر یِم دۅہ گٔیہِ تٔمۍ سٕندِ جدایی ہٕندِس دۅہہٕ سٍتـ̡ ضایع گٔیہِ۔ { ضایع گژھُن: ہیب۔ زوال }\n13.\\tتہٕ یِہ چُھ ناصری سُند شریعت، یێلہِ تٔمۍ سٕندِ جدایی ہُند دۅہ پوٗرٕ سپدِ: سُہ یِیہِ جماعت کِس خیمہ کِس دروازس پیٹھ اننہٕ:\n14. تہٕ سُہ کرِ خداوند سٕندِ خٲطرٕ پنُن نذرانہ پیش کرنہٕ، یُس گۅڈنِکِس ؤریس ہُند کۅکرٕ دِنہٕ خٲطرٕ بے داغ آسہِ، تہٕ گۅنہٕ کِس نذرانہ خٲطرٕ گۅنہٕ نِشہ روٚس کُنہِ کۅکرِ ہُند کۅکرٕ تہٕ اکھ کۅکرٕ یُس صلح کِس نذرانہ خٲطرٕ بے داغ آسہِ۔\n15.\\tتہٕ خمیر روٚس روٹی ہٕنز اکھ ٹوکرٕ، تیٖلس سٍتـ̡ رلاونہٕ آمٕژ عمدہ آٹٕچ کیک تہٕ تیٖلہٕ سٍتـ̡ مسح کرنہٕ آمٕژ خمیر روٚس روٹی تہٕ تِہٕندِ مازٕچ نذرانہ تہٕ تِہٕندِ شرابٕچ نذرانہٕ۔\n16. تہٕ پادٕرۍ کرِ خداوند سٕندِس برونہہ کُن، تہٕ پَنُن گۅنہٕ نذرانہٕ تہٕ تٔمۍ سٕنز دزنہٕ نذرانہ پیش کرِ۔\n17.\\tتہٕ سُہ کرِ خداوند سٕندِ خٲطرٕ امن ہٕنز قربانی دِنہٕ، خمیر روٚس روٹی ہٕنزِ ٹوٗکرِ سٍتـ̡ تہٕ پادٕرۍ کرِ پنُن ماز تہٕ شرابٕچ نذرانہ تہِ۔\n18.\\tتہٕ ناصری کرِ پننہِ جدایی ہُند کلہ جماعت ہٕندِس خیمہ کِس دروازس پیٹھ، تہٕ پننہِ جدایی ہٕندِس کلُک مس رٔٹِتھ تراوُن تہٕ اتھ نارس مَنٛز تراوُن یُس {چُھ} امن ہٕندِس نذرانہ سٍتـ̡ دِنہٕ آمُت۔\n19.\\tتہٕ پادٕرۍ کٔرِن نٔرِتھ کُنہِ تہٕ اکھ خمیر روٚس کیک تہٕ اکھ خمیر روٚس کۅکرِ تہٕ تِمن ہٕندِس اتھس پیٹھ تراوُن، تٔمۍ سٕندِس مَس کھوٗر کرنہٕ پتہٕ۔\n20.\\tتہٕ پادٕرۍ کرِ تِمن خداوند سٕندِ برونہہ کُن لہر ہٕندِس نذرس سٍتـ̡ یێلہِ ہُند نذر۔\n21. یہِ چُھ ناصری سُند شریعت یُس خدایہِ سٕندِ جدایی خٲطرٕ نذر کورمُت چُھ، یُس تٔمۍ سُند اَتھٕ میلہِ: یُس وعدٕ تٔمۍ سُند عہد کورمُت چُھ، تِتھٕ پٲٹھـ̡ پزِ أمِس جدایی ہٕندِس قانونس پٲٹھـ̡ کرُن۔\n22. تہٕ خداوند کٔر موسیٰ سٕنز کتھ ،\n23.\\tہارون تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡ کتھ کرٕن، یِتھٕ پٲٹھـ̡ کٔرِو تُہۍ بنی اِسرٲیلِس برکت دِن، تہٕ تِمن ؤنِو،\n24.\\tخداوند چُھہ تۅہہِ برکت دِوان تہٕ رژھراوُن:\n25.\\tخداوند کرِ توے سٍتـ̡ پنُن بُتھ چمکُن، تہٕ کرِ توے سٍتـ̡ مہربان:\n26.\\tخداوند تُلِتھ تُلِتھ تہٕ دِیُن ژے امن۔\n27. تہٕ تِم تھاون میٲنۍ ناو بنی اسرٲیلِس پیٹھ۔ تہٕ بہٕ کٔرٕ تمن دعا۔","1. تہٕ یہِ سپُد تمہِ دۅہہ ییمہِ دۅہہ موسىٰ ہن خیمہ پوٗرٕ پٲٹھـ̡ قایم کورمُت، تہٕ کوٚرُن مسح تہٕ تِمن ہٕندِس سارِنٕے سامانہٕ تہٕ تِمن ہٕندِس سارِنٕے بانہٕ تہٕ تِمن مسح کٔرِتھ پاک کورمُت۔\n2.\\tزِ اسرٲیلٕکۍ شہزادٕ، پننین مٲلن ہٕندِس گرٕکۍ سربراہ، یِم قبیلن ہٕندِ شہزادٕ ٲسۍ، تہٕ یِمن ہٕندِس نمبرس پیٹھ ٲسۍ، تِمو دِژ پیشکش: {تہٕ ٲسۍ: حب۔ کُس کھڑا اوس}\n3. تہٕ تِمو أنۍ خدایہِ برونہہ کُن پنٕنۍ نذرانہ ، شےٚ ؤلِتھ گاڑِ تہٕ باہ بیل۔ دۄن شہزادن خٲطرٕ اکھ ویگن، تہٕ پرٮ۪تھ أکِس خٲطرٕ اکھ داند تہٕ تِمو أنۍ تِم خیمہ برونہہ کُن۔\n4. تہٕ خداوند کٔر موسیٰ سٕنز کتھ ،\n5. تِمن نِش رٔٹِو، یُتھ زن تِم جماعت ہٕندِس خیمہ خانہٕ ہٕنز خدمت کرٕنۍ۔ تہٕ تُہۍ دِیُن تِم لاوِین تہٕ پرٮ۪تھ أکِس شخصس تٔمۍ سٕنزِ خدمتہٕ مُطٲبق دِنہٕ۔\n6.\\tتہٕ موسىٰ نِن گاڑِ تہٕ بیل تہٕ دِتُن لاوِین نِش۔\n7. زٕ ویگن تہٕ ژور بیل دِژ تِمن ہٕنزِ خدمتہٕ مُطٲبق گرشون سٕندِس نیچوِس ۔\n8. تہٕ ژور ویگن تہٕ ٲٹھ بیل دِژ تِمن ہٕنزِ خدمتہٕ مُطٲبق ہارون پادٕرۍ سٕندِس نیچوِس اِتھامار سٕندِس اتھس منز۔\n9.\\tمگر کوہات سٕندِس نیچوِس دِژ نہٕ تِمن ہٕندِس مُقدس سٍتـ̡ تِمن ہٕندِس پھیکس پیٹھ تُلنہٕ۔\n10.\\tتہٕ شہزادو کٔر قربان گاہ وقف کرنہٕ خٲطرٕ پیشکش، ییمہِ دۅہہ یہ مسح آو کرنہٕ، شہزادو تہِ کٔر قربان گاہَس برونہہ کُن پنٕنۍ نذرانہ پیش۔\n11. تہٕ خداوند ووٚن موسیٰ سٕندِس دۅہٕ قربان گاہ وقف کرنہٕ خٲطرٕ۔\n12.\\tیُس گۅڈنچہ دۅہہ پنُن نذرانہ پیش کور، سہ اوس یہوداہ قبیلہٕ سُند امناداب سُند نیچو نہشون:\n13.\\tتہٕ تٔمۍ سُند نذرانہ اوس اکھ رۄپہٕ چارجر، امیک وزن اوس اکھ ہتھ ترہ شیکل، اکھ رۄپہٕ پیالہ ستتھ شیکل، مقدس مقامہٕ کس شیکل پتہٕ۔ یم دۅشوے ٲسۍ ماز پیش کرنہ خاطرہ تیٖلس سیتۍ رٔلتھ باریک آٹہ بٔرتھ:\n14.\\tدَہ {شیکل} سۄنہٕ ہُند اکھ چمچ، بٔرِتھ بٔرِتھ:\n15.\\tاکھ جوان بیل، اکھ کۅکر، گۅڈنچہ ؤری ہُند اکھ کۅکر، زالنہٕ خٲطرٕ:\n16.\\tژھاوُن ہُند اکھ شُر:\n17.\\tتہٕ امنٕچ قربانی خٲطرٕ، زٕ بیل، پانژھ ژھاوٕل، پانژھ ژھاوٕل، گۄڈنِکِس ؤریس ہٕندِ پانژھ کٹہٕ بچہٕ: یہِ اوس امیناڈاب سٕندِ نیچو نہشون سُند نذران۔\n18.\\tدۆیمہِ دۅہہ کٔر عیساکرُک شہزادہ زوار سٕندِ نیچوۍ نیتھنیلن پیشکش:\n19.\\tتٔمۍ کٔر پننہِ پیش کش خٲطرٕ اکھ رۅپہٕ چارجر، یُس وزن اکھ ہتھ ترہ شیکل، اکھ رۅپہٕ پیالہ ستتھ شیکل، مقدس مقامہٕ کِس شیکل پتہٕ۔ یم دۅشوے ٲسۍ ماز پیش کرنہ خاطرہ تیٖلس سیتۍ رٔلتھ باریک آٹہ سیتۍ بٔرتھ:\n20.\\tدَہَن ہُند اکھ چمچہٕ سۄنہٕ، یُس اگربَس سٍتۍ بٔرِتھ:\n21.\\tاکھ جوان بیل، اکھ کۅکر، گۅڈنچہ ؤری ہُند اکھ کۅکر، زالنہٕ خٲطرٕ:\n22.\\tژھاوُل سُند اکھ شُر:\n23.\\tتہٕ امن ہٕندِ قربانی خٲطرٕ، زٕ بیل، پانژھ ژھاوٕل، پانژھ ژھاوٕرۍ، گۄڈنِکہِ ؤرۍ یِکۍ پانژھ دانٛدٕرۍ: یہِ اوس زوار سٕندِس نیچو نیتھنیل سُند نذران۔\n24.\\tتریمہِ دۅہہ کٔر زیبولون سٕندِس اولادس ہُند شہزادہ ہیلون سُند نیچو الیاب، {دِژ پیشکش}۔\n25.\\tتٔمۍ سُند نذرانہ اوس اکھ رۅپہٕ چارجر، یُس وزن اکھ ہتھ ترہ شیکل، اکھ رۅپہٕ پیالہ ستتھ شیکل، مقدس مقامہ کِس شیکل پتہٕ۔ یم دۅشوے ٲسۍ ماز پیش کرنہ خاطرہ تیٖلس سیتۍ رٔلتھ باریک آٹہ سیتۍ بٔرتھ:\n26.\\tدَہَن ہُند اَکھ سۄنہٕ چمچ، یُس بُورِ سٍتۍ بٔرِتھ:\n27.\\tاکھ جوان دان، اکھ کۅکر، گۅڈنچہ ؤری ہُند اکھ کۅکر، زالنہٕ خٲطرٕ:\n28.\\tگۅنہٕ نذرانہٕ خٲطرٕ ژھاوُن ہُند اکھ شُر:\n29.\\tتہٕ امن ہٕندِ قربانی خٲطرٕ، زٕ بیل، پانژھ ژھاوٕل، پانژھ ژھاوٕل، گۄڈنِکِس ؤریس ہٕندِس پانژھ کٹہٕ بچہٕ: یہِ اوس ہیلون سُند نیچو الیاب سُند نذران۔\n30.\\tژوٗرمہِ دۅہہ روبن سٕندِس شُرین ہٕندِس شہزادس شیدیور سٕندِس نیچوِس الیزورن کٔر پیش کرنہٕ:\n31.\\tتٔمۍ سُند نذرانہ اوس اکھ ہتھ ترہ شیکل وزنُک اکھ رۅپہٕ پیالہ تہٕ ستتھ شیکلن ہُند اکھ رۄپہٕ پیالہ یُس مقدس مقامہٕ کِس شیکل پَتہٕ اوس۔ یم دۅشوے ٲسۍ ماز پیش کرنہ خاطرہ تیٖلس سیتۍ رٔلتھ باریک آٹہ سیتۍ بٔرتھ:\n32.\\tدَہَن ہُند اَکھ سۄنہٕ چمچ، یُس بخور سٍتۍ بٔرِتھ:\n33.\\tاکھ جوان بیل، اکھ کۅکر، گۅڈنچہ ؤری ہُند اکھ کۅکر، زالنہٕ خٲطرٕ:\n34.\\tژھاوُن ہُند اکھ شُر:\n35.\\tتہٕ امن ہٕندِ قربانی خٲطرٕ، زٕ بیل، پانژھ ژھاوٕن، پانژھ ژھاوٕل، گۄڈنِکہِ ؤریٕکۍ پانژھ کٹہٕ: یہِ اوس شیدُور سٕندِس نیچوِس الیزور سٕنز نذران۔\n36.\\tپوٗنٛژمہِ دۅہہ کٔر شمعون سٕندٮ۪ن شُرین ہٕندِس شہزادٕ زُرِشدایی سٕندِس نیچوِس شیلومیل {دِژ پیشکش}:\n37.\\tتٔمۍ سُند نذرانہ اوس اَکھ رۄپہٕ چارجر، یُس وزن اوس اکھ ہتھ ترہ شیکل، اکھ رۄپہٕ پیالہ ستتھ شیکل، مقدس مقامہٕ کِس شیکل پتہٕ۔ یم دۅشوے ٲسۍ ماز پیش کرنہ خاطرہ تیٖلس سیتۍ رٔلتھ باریک آٹہ سیتۍ بٔرتھ:\n38.\\tدَہَن ہُند اَکھ سۄنہٕ چمچ، یُس بُورٕ سٍتۍ بٔرِتھ:\n39.\\tاکھ جوان دانٛد، اکھ کۅکر، گۅڈنچہ ؤری ہُند اکھ کۅکر، زالنہٕ خٲطرٕ:\n40.\\tگۅنہٕ خٲطرٕ ژھاوُن ہُند اکھ بچہ:\n41.\\tتہٕ امنٕچ قربانی خٲطرٕ، زٕ بیل، پانژھ کٔرۍ، پانژھ ژھاوٕل، گۄڈنِکِس ؤریس ہٕندِ پانژھ کٹہٕ: یہِ اوس زُرِشدایی سُند نیچو شیلومیل سُند نذران۔\n42.\\tشیٚمہِ دۅہہٕ دِیوُل سُند نیچو، یُس گاد کِس اولادَن ہُند شہزادٕ اوس، {پیش کرنہٕ}:\n43.\\tتٔمۍ سُند نذرانہ اوس اکھ ہتھ ترہ شیکل وزنُک اکھ رۄپہٕ پیالہ تہٕ ستتھ شیکلن ہُند رۄپہٕ پیالہ یُس مقدس خانہٕ کِس شیکل پتہٕ اوس۔ یم دۅشوے ٲسۍ ماز پیش کرنہ خاطرہ تیٖلس سیتۍ رٔلتھ باریک آٹہ سیتۍ بٔرتھ:\n44.\\tدَہَن ہُند اکھ سۄنہٕ چمچ، یُس بُورِ سٍتۍ بٔرِتھ:\n45. اکھ جوان بیل، اکھ کۅکر، گۅڈنچہ ؤری ہُند اکھ کۅکر، زالنہٕ خٲطرٕ:\n46.\\tژھاوُن ہُند اکھ شُر:\n47.\\tتہٕ امن ہٕندِ قربانی خٲطرٕ، زٕ بیل، پانژھ کۅکرۍ، پانژھ ژھاوٕن، گۅڈنچہ ؤری ہٕندِ پانژھ کۅکرِ بچہٕ: یہِ اوس دوویلُک نیچو الیاصف سُند نذران۔\n48.\\tسٔتِمہِ دۅہہٕ کٔر افرایم سٕندِس اولادَن ہُند شہزادٕ اَمی ہود سُند نیچو الیشامہ {پیش کرنہٕ}:\n49.\\tتٔمۍ سُند نذرانہ اوس اَکھ رۄپہٕ چارجر، یُس وزن اوس اکھ ہتھ ترہ شیکل، اکھ رۅپہٕ پیالہ ستتھ شیکل۔ یم دۅشوے ٲسۍ ماز پیش کرنہ خاطرہ تیٖلس سیتۍ رٔلتھ باریک آٹہ سیتۍ بٔرتھ:\n50.\\tدَہَن ہُند اَکھ سۄنہٕ چمچ، یُس بُورِ سٍتۍ بٔرِتھ:\n51.\\tاکھ جوان داند ، اکھ کۅکر، گۅڈنچہ ؤری ہُند اکھ کۅکر، زالنہٕ خٲطرٕ:\n52.\\tژھاوُن ہُند اکھ شُر:\n53.\\tتہٕ امن ہٕندِ قربانی خٲطرٕ، زٕ بیل، پانژھ ژھاوٕن، پانژھ ژھاوٕل، گۄڈنِکِس ؤریس ہٕندِ پانژھ کٹہٕ بچہٕ: یہِ اوس امیہود سٕندِ نیچو الیشامہ سُند نذران۔\n54.\\tٲٹھمہِ دۅہہ دِژ مناسہ سٕندِس بچن ہٕندِس شہزادٕ پداہزور سُند نیچو جمالیل:\n55.\\tتٔمۍ سُند نذرانہ اوس اکھ ہتھ ترہ شیکل وزنُک اکھ رۅپہٕ پیالہ تہٕ ستتھ شیکلن ہُند اکھ رۅپہٕ پیالہ یُس مقدس مقامہٕ کِس شیکل پَتہٕ اوس۔ یم دۅشوے ٲسۍ ماز پیش کرنہ خاطرہ تیٖلس سیتۍ رٔلتھ باریک آٹہ سیتۍ بٔرتھ:\n56.\\tدَہَن ہُند اکھ سۄنہٕ چمچ، بُرٕ سٍتۍ بٔرِتھ:\n57.\\tاکھ جوان بیل، اکھ کۅکر، گۅڈنچہ ؤری ہُند اکھ کۅکر، زالنہٕ خٲطرٕ:\n58.\\tژھاوُن ہُند اکھ شُر:\n59.\\tتہٕ امن ہٕنزِ قربانی خٲطرٕ، زٕ بیل، پانژھ ژھاوٕل، پانژھ ژھاوٕرۍ، گۄڈنِکِس ؤریس ہٕندِ پانژھ کٹہٕ: یہِ اوس پدازور سٕندِس نیچو جمالیل سُند نذران۔\n60. نٔومہِ دۅہہٕ گِدونی سُند نیچو عابدان، یُس بنیامین سٕندٮ۪ن بچن ہُند شہزادٕ اوس، {پیش کٔرِتھ}:\n61.\\tتٔمۍ سُند نذرانہ اوس اکھ رۅپہٕ چارجر، یُس وزن اکھ ہتھ ترہ شیکل اوس، اکھ رۅپہٕ پیالہ ستتھ شیکل۔ یم دۅشوے ٲسۍ ماز پیش کرنہ خاطرہ تیٖلس سیتۍ رٔلتھ باریک آٹہ سیتۍ بٔرتھ:\n62.\\tدَہَن ہُند اَکھ سۄنہٕ چمچ، بٔرِتھ بٔرِتھ:\n63.\\tاکھ جوان بیل، اکھ کۅکر، گۅڈنچہ ؤری ہُند اکھ کۅکر، زالنہٕ خٲطرٕ:\n64.\\tژھاوُل سُند اکھ شُر:\n65.\\tتہٕ امن ہٕندِ قربانی خٲطرٕ، زٕ بیل، پانژھ کۅکر، پانژھ ژھاوٕن، گۅڈنچہ ؤری ہٕندِ پانژھ کۅکرِ بچہٕ: یہِ اوس گِدونی سٕندِس نیچو عابدان سُند نذران۔\n66.\\tدٔہمہِ دۅہہ دِژ دٲن سٕندِس شُرِ ہُند شہزادٕ اَمِشادایی سُند نیچو احیزَر:\n67.\\tتٔمۍ سُند نذرانہ اوس اکھ رۅپہٕ چارجر، یُس وزن اکھ ہتھ ترہ شیکل، اکھ رۅپہٕ پیالہ ستتھ شیکل اوس، مقدس مقامہ کس شیکل پتہٕ۔ یم دۅشوے ٲسۍ ماز پیش کرنہ خاطرہ تیٖلس سیتۍ رٔلتھ باریک آٹہ سیتۍ بٔرتھ:\n68.\\tدَہَن ہُند اَکھ سۄنہٕ چمچ، یُس بُورٕ سٍتۍ بٔرِتھ:\n69.\\tاکھ جوان بیل، اکھ کۅکر، گۅڈنچہ ؤری ہُند اکھ کۅکر، زالنہٕ خٲطرٕ:\n70.\\tژھاوُل سُند اکھ شُر:\n71.\\tتہٕ امن ہٕندِ قربانی خٲطرٕ، زٕ بیل، پانژھ کۅکر، پانژھ ژھاوٕل، گۅڈنچہ ؤری ہٕندِ پانژھ کٹہٕ: یہِ اوس اَمِشدایی سٕندِس نیچوِس احیزر سُند نذران۔\n72.\\tکاہمہِ دۅہہ آشر سٕندِس بچن ہُند شہزادہ اوکران سُند نیچو پاگیل، {پیش کٔرِتھ}:\n73.\\tتٔمۍ سُند نذرانہ اوس اکھ رۅپہٕ چارجر، یُس وزن اکھ ہتھ ترہ شیکل، اکھ رۅپہٕ پیالہ ستتھ شیکل۔ یم دۅشوے ٲسۍ ماز پیش کرنہ خاطرہ تیٖلس سیتۍ رٔلتھ باریک آٹہ سیتۍ بٔرتھ:\n74.\\tدَہَن ہُند اکھ سۄنہٕ چمچ، یُس بُورِ سٍتۍ بٔرِتھ:\n75.\\tاکھ جوان دانٛد، اکھ کۅکر، گۅڈنچہ ؤری ہُند اکھ کۅکر، زالنہٕ خٲطرٕ:\n76.\\tژھاوُن ہُند اکھ شُر:\n77.\\tتہٕ امن ہٕنزِ قربانی خٲطرٕ، زٕ بیل، پانژھ ژھاوٕل، پانژھ ژھاوٕرۍ، گۄڈنِکہِ ؤرۍ یِکۍ پانژھ کۅکرۍ: یہِ اوس اوکران سٕندِس نیچوِس پاگیل سُند نذران۔\n78.\\tبٔہمہِ دۅہہ دِژ نفتالی ہٕندِس شُرین ہُند شہزادہ اِنان سُند نیچو احیرہ، {پیش کرنہٕ}:\n79.\\tتٔمۍ سُند نذرانہ اوس اَکھ رۄپہٕ چارجر، یُس وزن اوس اکھ ہتھ ترہ شیکل، اکھ رۅپہٕ پیالہ ستتھ شیکل۔ یم دۅشوے ٲسۍ ماز پیش کرنہ خاطرہ تیٖلس سیتۍ رٔلتھ باریک آٹہ سیتۍ بٔرتھ:\n80.\\tدَہَن ہُند اَکھ سۄنہٕ چمچ، یُس بُورٕ سٍتۍ بٔرِتھ:\n81.\\tاکھ جوان بیل، اکھ کۅکر، گۅڈنچہ ؤری ہُند اکھ کۅکر، زالنہٕ خٲطرٕ:\n82.\\tژھاوُن ہُند اکھ شُر:\n83.\\tتہٕ امنٕچ قربانی خٲطرٕ، زٕ بیل، پانژھ باوٕل، پانژھ ژھاوٕل، گۄڈنِکِس ؤریس ہٕندِ پانژھ کٹہٕ: یہِ اوس اِنان سٕندِس نیچوِس احیرہ سُند نذران۔\n84.\\tیہ اوس قربان گاہُک وقف کرنہٕ آمُت، تمہِ دۅہہ ییلہ یہِ مسح کرنہٕ آو، اسرٲیلِکۍ شہزادن دٔسۍ مسح کرنہٕ آو: باہ رۄپہٕ پیالہٕ، باہ رۄپہٕ پیالہٕ، باہ چمچہٕ سۄنہٕ۔\n85.\\tرۅپہِ ہُند پرٮ۪تھ کُنہِ کُنہِ رۅپہٕ سٍتـ̡ رۅپہٕ ہٕندِس بانہٕ {وزن} زٕ ساس تہٕ ژور ہتھ {شیکل} ، مقدس مقامہٕ کِس شیکل پَتہٕ ۔\n86.\\tسۅنہٕ چمچہٕ {ٲس} باہ بٔرِتھ، اگربتی سٍتۍ بٔرِتھ، {وزن} دَہ {شیکل}، مقدس مقامہٕ کِس شیکل پتہٕ: چمچن ہُند سورُے سون {اوس} اکھ ہتھ {شیکل}۔\n87.\\tدزنہٕ خٲطرٕ سارِنٕے بیل ٲسۍ باہ بیل، گۅڈنچہ ؤری ہٕندِ باہ دانٛد، گۅڈنچہ ؤری ہٕندِ دانٛدٕ باہ تہٕ ژھاوٕنۍ بچہٕ تہٕ گۅنہٕ خٲطرٕ بَہہ بچہٕ۔\n88.\\tتہٕ سارِنٕے بیل ٲسۍ امن ہٕندِ قربانی خٲطرٕ ژۅوُہ تہٕ ژۅۅن بیل، مینڈٕ شیٹھ، ژھاوٕل شیٹھ، گۅڈنِکِس ؤریس ہٕندِ کۅکرِ شیٹھ۔ یہٕ {اوس}قربان گاہک وقف، تمہٕ پتہٕ آو یہٕ مسح کرنہٕ۔\n89.\\tتہٕ ییلہ موسیٰ أمِس سٍتـ̡ کتھ کرنہٕ خٲطرٕ جماعت کِس خیمہ خانس مَنٛز گٔیہ، تێلہِ بوز أمِس سٍتـ̡ رحمتٕچ کرسی پیٹھٕ یُس گواہی ہٕندِس صندوقس پیٹھ اوس، دۄن کروبن درمِیان ٲس، تہٕ تٔمۍ کٔر أمِس سٍتـ̡ کتھ کرنہٕ۔ {أمِس سٍتۍ: یعنی خدایس سٍتۍ}","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2.\\tہارونس سٍتـ̡ کتھ کرٕن، تہٕ ونُن زِ ییلہ ژے چراغ روشن کرِ، سَتھ شمعہٕ دِنہٕ یِنہٕ وٲلِس شمعس سٍتـ̡ گاش دِنہٕ۔\n3. تہٕ ہارون کٔر یہِ ۔ یِتھٕ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت تٔمۍ سٕندِس شمعس سٍتـ̡ شمعہٕ سٍتـ̡ چُھہ شمعہٕ سٍتـ̡ شمعہٕ سٍتـ\n4.\\tتہٕ شمعدان سٕنز یہِ کٲم ٲس سۄنہٕ سٕندِس سٍتـ̡ ، اَمہ کِس گُلَس تام، اَمہ کِس پوشن تام، {اوس} مارنہٕ آمٕژ کٲم: یُس نمونہٕ مُطٲبق خداوند موسیٰ ہس ہٲومُت اوس، تێلہِ بنوو تٔمۍ شمعدان ۔\n5. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n6.\\tلاوی نِو بنی اسرٲیلِس منز، تہٕ تِمن پاک کرُن۔\n7. تہٕ یِتھٕ پٲٹھۍ کٔرِو تِمن پاک کرنہٕ خٲطرٕ، تِمن پۯاوُن صاف کرنہٕ خٲطرٕ، تہٕ تِمن پَنُن سورُے ماز کھوٗر کٔرِتھ، تہٕ پَنُن صاف کرُن۔ {تِمن کرُن شیو...: ہیب۔ تِم گژھن ریزر اپارِ نیرُن، وغیرہ}\n8.\\tتیلہٕ نِن تِم اکھ جوان دانٛد تٔمۍ سٕندِس مازٕچ نذرانہ سٍتۍ، تیلَس سٍتـ̡ رٔلِتھ رٔلِتھ تہٕ بیاکھ بچہٕ بیل نِنہٕ یُن گۅناہ ہٕندِس نذرانہ سٍتـ̡ نِنہٕ۔\n9. تہٕ تُہۍ أنِو لاوی جماعت کِس خیمہ خانس برونہہ کُن، تہٕ تُہۍ کٔرِو بنی اِسرٲیلِچ سارِنٕے مجلسہٕ یکجا کرنہٕ۔\n10. تہٕ تُہہِ کٔرِو لاوِین ہٕندِس برونہہ کُن تہٕ بنی اسرٲیلِس پَنٕنہِ اتھہٕ لاوِین پیٹھ۔\n11. تہٕ ہارون کرِ خداوند سٕندِس برونہہ کُن لاوی پیش کرنہٕ یُتھ زن تِم خداوند سٕنز خدمت انجام دِتھ۔ {پیشکش: ہیب۔ لہر} {پیشکش: Heb. لہرِ ہنز پیشکش} {تِم...: ہیب۔ تِم ہیکن پھٲنٛسہِ دِنہٕ خٲطرٕ ٲسِتھ، وغیرہ}\n12.\\tتہٕ لاوی گژھن بیلن ہٕندِس کلس پیٹھ اتھہٕ تھاوُن، تہٕ تُہۍ کرِ اکھ گۅنہٕ خٲطرٕ تہٕ بیٛاکھ زالنہٕ خٲطرٕ، یُس لاوِین ہٕندِ خٲطرٕ کفارہ دِنہٕ خٲطرٕ۔\n13. تہٕ توے تھاو لاوی ہارونس برونہہ کُن تہٕ تٔمۍ سٕندِس نیچوِس برونہہ کُن، تہٕ تِمن کٔرِو خداوند سٕندِ خٲطرٕ نذرانہ پیش کرنہٕ۔\n14. یِتھٕ پٲٹھـ̡ کٔرِو توے لاوِین اِسرٲیلـ̡ سٍتـ̡ الگ کٔرِتھ، تہٕ لیوی گژھن میٲنۍ ۔\n15. تہٕ اَمہِ پتہٕ گژھن لاوی جماعت کِس خیمہ خانہٕ چہِ خدمت کرنہٕ خٲطرٕ اژُن، تہٕ تِمن پاک کٔرِو تہٕ تِمن نذرانہ خٲطرٕ پیش کرُن۔\n16.\\tتِکیازِ تِم چھِ بنی اِسرٲیلِس منزٕ پوٗرٕ پٲٹھـ̡ دِنہٕ آمٕتـ̡ ۔ یِتھٕ بجایہ چُھہ پرٮ۪تھ کُنہِ رحم کھولنہٕ بجایہ، {حتیٰ کہِ} اسرٲیلِکۍ سارِنٕے بچن ہٕندِس گۄڈنِکِس زامتس بجایہ چُھہ مے تِم پانس نِش نِوان۔\n17.\\tیێلہِ چُھہ میہ سارِنٕے بچہٕ سٍتـ̡ میٲنۍ انسان تہٕ جانور دِنہٕ آمُت: ییمہِ دۅہہ میہ مصرٕکِس سرزمینس مَنٛز پرٮ۪تھ أکِس گۄڈنِکِس زامتس مارٕ دِژ، مے کٔر تِم پانس خٲطرٕ پاک۔\n18. تہٕ مے چُھس لاوی بنی اسرٲیلِہ سٕندِس سارِنٕے زامتـ̡ سٍتـ̡ رٔٹمٕتـ̡ ۔\n19. تہٕ مے چُھس لاوِین ہارون تہٕ تٔمۍ سٕندِس نیچوِس اِسرٲیلِس مَنٛز اکھ تحفہٕ دِژمُت، یُتھ زن بنی اِسرٲیلِیَن ہٕنز خدمت کٔرِتھ تہٕ بنی اسرٲیلِین ہٕندِس خٲطرٕ کفارہٕ دِنہٕ یِن، یُتھ زن بنی اسرٲیلِس مَنٛز گژھہِ نہٕ کانہہ وبا سپدُن،  ییلہِ بنی اسرائیل مقدس مقامس نزدیک وٲتِتھ۔ {اکھ تحفہٕ: ہیب۔ دِنہٕ آمُت}\n20. تہٕ موسیٰ تہٕ ہارون تہٕ بنی اسرٲیلن ہٕنزِ سارِنٕے جمٲژ کٔر لاوِین سٍتـ̡ یُس خداوند موسیٰ ہس لاوِین متعلق حکم دِیُتمُت اوس، یِتھے پٲٹھۍ کٔر بنی اسرٲیلـ̡ تِمن سٍتـ̡ ۔\n21. تہٕ لاوی کٔر پاک تہٕ تِمو کٔر پَنٕنۍ پلو چھلان۔ تہٕ ہارونن کٔر تِمن خداوند سٕندِ برونہہ کُن نذرانہ پیش کرنہٕ۔ تہٕ ہارونن کٔر تِمن پاک کرنہٕ خٲطرٕ کفارہٕ۔\n22. تہٕ اَمہِ پَتہٕ گٔیہِ لاوی ہارونس برونہہ تہٕ تٔمۍ سٕندِس نیچوِس برونہہ کُن جماعت کِس خیمہ خانس مَنٛز پنٕنۍ خدمت کرنہٕ خٲطرٕ، یِتھ کٔنۍ خداوند موسیٰ ہس لاوِین مُتلق حُکُم دِیُتمُت، تِتھۍ کٔر تِمو تِمن سٍتـ̡ ۔\n23.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن\n24. یہِ {چُھ} یُس {چُھ} لاوِین سٍتـ̡ تعلق تھاوان: وُہن تہٕ پَنژٕوُن وُہُر وٲنسہِ پى۪ٹھہٕ پى۪ٹھ:{to...: Heb. جنگ کرُن، وغیرہ}\n25.\\tتہٕ پنژاہ وُہُر وٲنسہِ پیٹھٕ گژھن تِم خدمتہٕ کِس انتظارس منز بند کرٕن، تہٕ بییہِ گژھن نہٕ خدمت کرنہٕ: {بند ...: ہیب۔ سروس کہ جنگ پیٹھ واپس}\n26. مگر گژھن پننین باین سٍتـ̡ جماعت کِس خیمہ خانس مَنٛز خدمت کرنہٕ، تہٕ کرِ نہٕ کانہہ خدمت۔ یِتھٕ پٲٹھۍ کٔرِو تُہۍ لاوِین سٍتـ̡ تہندِس اِلزامس سٍتـ̡ کٔرِتھ۔","1.\\tتہٕ خداوند کٔر موسیٰ سٍتـ̡ سینا کِس بیابانس مَنٛز، دۆیمہِ ؤری کِس گۄڈنِکِس رٮ۪تس مَنٛز یِم مصرٕچ سرزمینہٕ منزٕ نیرنہٕ پتہٕ وونُن،\n2. بنی اسرٲیلـ̡ تہِ گژھن فسح تہِ پننِس مُقرر وقتس مُطٲبِق۔\n3.\\tیمہِ ریتہٕ کِس ژۄدٲہمہِ دۅہہٕ تہِ تھاوُن تہٕ تٔمۍ سٕندِس مُقرر وقتس مُطٲبِق تھاوُن۔ {حتیٰ کہ: ہیب۔ دۄن شامن درمیان}\n4. تہٕ موسىٰ ین ووٚن بنی اسرٲیلِس سٍتـ̡ زِ تِم گژھن فسح مناون۔\n5.\\tتہٕ تِمو تھوو گۅڈنِکہِ ریتہٕ کِس ژۄدٲہِمہِ دۅہہٕ سینا کِس بیابانس مَنٛز تہِ، یُس خداوند موسیٰ سُند حکم دِیُتمُت اوس، تِتھے پٲٹھۍ کٔر بنی اسرٲیلِیو تہِ۔\n6.\\tتہٕ کینہہ نفر ٲسۍ یِم أکِس انسانہٕ سٕندِس لاشہٕ سٍتـ̡ ناپاک کٔرِتھ، یِم ہیوٚک نہٕ اَمہِ دۅہہٕ موسٰی سٕندِس تہٕ ہارونس برونہہ کُن وٲتِتھ:\n7.\\tتہٕ تِمو نفرو ووٚن أمِس زِ أسـ̡ چُھہ أکِس انسانہٕ سٕندِس لاشہٕ سٍتـ̡ ناپاک کرنہٕ آمُت، تێلہِ کیازِ چُھہ أسـ̡ پتھ کُن تھونہٕ آمُت، یُتھ زِ أسـ̡ ہێکہِ نہٕ خداوند سٕندِس مُقرر وقتس مَنٛز اِسرٲیلـ̡ سٕندِس مُقرر وقتس مَنٛز نذرانہ پیش کٔرِتھ؟\n8. تہٕ موسىٰ ووٚن تِمَن، رٔٹِتھ رٔٹِو، تہٕ بہٕ بوزٕ خداوند کیا حُکُم کرِ۔\n9. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n10. بنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، یێلہِ تۅہہِ منزٕ یا تُہٕندِس اولادس مَنٛز کانہہ نفر لاشہٕ سٍتـ̡ ناپاک آسہِ، یا دوٗر سفرس مَنٛز آسہِ، توتہِ کرِ سُہ خداوند سٕندِ خٲطرٕ فسح تھاوُن۔\n11.\\tدۆیمہِ ریتُک ژۄدٲہِم دۅہہ تہِ گژھن یہ رژھرُن، {تہٕ} کھیوٚن خمیر روٚس روٹی تہٕ تلخ {جڑی بوٹی}۔\n12. تِم گژھن نہٕ صُبحَس تام اَمہِ مَنٛز کانٛہہ تہِ تراوُن، تہٕ نہ پھُٹراوٕن: فسح کِس سارِنٕے احکامَو مُطٲبِق گژھن تِم یہِ رژھرٕنۍ۔\n13. مگر یُس انسان پاک آسہِ، تہٕ سفرس منز آسہِ نہٕ، تہٕ فسح رژھراونس نِش باز روزِ، سُہ تہِ گژھہِ پننِس لوکَس مَنٛز ژٹنہٕ یُن: کیازِ سُہ چُھ نہٕ خداوند سٕنز قربانی پننِس مُقرر وقتس مَنٛز اَننہٕ، سُہ انسان گژھہِ پَنُن گۅناہ برداشت کرنہٕ۔\n14. تہٕ یێلہِ کانہہ اجنبی چُھہ تۅہہِ منزٕ روزِ، تہٕ روزِ خداہس سٍتـ̡ فسح فسح کِس حکمس مُطٲبق، تہٕ اَمہ کِس طریقس مُطٲبق، سُہ کرِ یِتھٕ پٲٹھۍ کرُن: تہٕ یُس زمینس مَنٛز زامُت اوس، تہٕ تٔمِس خٲطرٕ گژھہِ اَکھ آرڈیننس۔\n15. تہٕ ییمہِ دۅہہ خیمہ کھڑا آو کرنہٕ، اوٚبرن اوس خیمہ وول، یعنی گوٲہی ہُند خیمہ تہٕ صُبحَس تام اوس خیمہ ہُند ظہور۔\n16.\\tیِتھے پٲٹھۍ اوس ہمیشہٕ: اوٚبرُن اوس اَتھ دۅہہٕ تہٕ رٲژ نارُک ظہور۔\n17.\\tییلہ اوبُر خیمہ منزہ تُلنہٕ آو، تمہ پتہ گٔیہِ بنی اسرٲیلِہ سفر تہٕ ییتہِ اوبُر روزان اوس، تتہِ کٔر بنی اسرٲیلِیو پنٕنۍ خیمہ لگاونہٕ۔\n18.\\tخداوند سٕندِس حُکمس سٍتـ̡ کٔر بنی اسرائیلُک سفر، تہٕ خداوند سٕندِس حُکمس مُطٲبق کٔر تِمو پنہٕ نِس خیمَس مَنٛز آرام۔\n19. تہٕ ییلہ اوبُر خیمہ خانس پیٹھ واریاہن دۅہن روٗد، تیلہِ تھوو بنی اسرٲیلِیو رب سُند ذمہ دار، تہٕ سفر کٔرِتھ نہٕ۔ طویل}\n20. تہٕ {یِتھ} اوس یہ، ییٚلہِ اوٚبرُک خیمہ ہٕندِس کُنہِ دۅہہٕ اوس۔ خداوند سٕندِ حُکمَس مُطٲبِق رودۍ تِم پننین خیمن مَنٛز روزان، تہٕ خداوند سٕندِ حُکمَس مُطٲبِق گٔیہِ تِم سفر۔\n21.\\tتہ یتھے پاٹھۍ ییلہ اوٚبرہ صبحس تام روزان اوس، تہ صبحس اوٚبر تُلتھ تہ تمہ پتہ ٲسۍ تم سفر کٔرتھ: چاہے یہ دۅہہ یا رٲژ اوٚبرہ تُلتھ تُلتھ تِمو سفر کٔرۍ۔ {رہائش: ہیب۔ اوس}\n22.\\tیا زٕ دۅہہ، یا اکھ ریتھ، یا اکھ ؤری، یێلہِ اوٚبرُن خیمہ خانس پیٹھ روٗد، اَتھ پیٹھ روٗد اسرٲیلٕکۍ بنی پننین خیمن مَنٛز روزان، تہٕ سفر کٔرِتھ سفر کٔرِتھ۔\n23.\\tخداوند سٕندِس حُکمس مُطٲبق رودۍ تِمو خیمن مَنٛز آرام تہٕ خداوند سٕندِس حُکمس مُطٲبِق گٔیہِ تِمو موسیٰ سٕندِ اتھہٕ سٍتـ̡ خداوند سٕندِس حُکمس مُطٲبِق۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. رۄپہٕ سٕندِ زٕ بٔنِتھ بَنٲیِو۔ تُہۍ بناوِو تِم پوٗرٕ ٹُکرٕ: یُتھ تُہۍ ہیکِو یِم مجلسہٕ بُلاونہٕ خٲطرٕ تہٕ کیمپَن ہٕنٛدِ سفرٕ خٲطرٕ استعمال کٔرِتھ۔\n3. تہٕ یێلہِ تِم پانس سٍتـ̡ پھُوُن دِن، سٲری مجلسہٕ گژھن تۅہہِ سٍتـ̡ جماعت کِس خیمہ کِس دروازس پیٹھ جمع سپدٕنـ̡ ۔\n4. تہٕ اگر تِم اَکہِ {بُرق} سٍتـ̡ وُپھ دِن، تیلہِ گژھن شہزادہٕ، یِم ساسہٕ بٔدۍ اسرٲیلٕکۍ سربراہ چھِ، گژھن پانس پانس پانس سٍتـ̡ جمع کرنہٕ۔\n5.\\tییلہ ژیہ الارم بجہِ، تیلہِ گژھن مشرقس منز موجود کیمپ برونہہ کُن۔\n6.\\tییلہ توہہِ دوٚیمہِ لٹہِ الارم بجاو، تیلہِ گژھن جنوبس طرفہ یِم کیمپ پَنُن سفر کٔرِتھ، تِم گژھن پننہِ سفرٕ خٲطرٕ الارم بجاونہٕ۔\n7.\\tمگر ییلہ جماعت جمع گژھن تیلہِ گژھہِ پھوُن، مگر ژیہ گژھہِ نہ الارم بجاونہ۔\n8.\\tتہٕ ہارون سٕندِ نیچو، پادٕرۍ، بُرٕ دِنہٕ سٍتـ̡ تہٕ تِم روزن تۅہہِ سٍتـ̡ ہمیشہٕ خٲطرٕ اَکہِ آرڈیننس خٲطرٕ۔\n9. تہٕ یێلہِ تُہۍ پننِس ملکس مَنٛز تٔمِس دُشمن سٍتـ̡ جنگ کٔرِو یُس تۅہہِ سٍتـ̡ ظُلم کران چُھ، تیلہِ کٔرِو تُہۍ بُنـ̡ دِنہٕ آمُت۔ تہٕ یِیہِ خداوند پنُن خدایہ سٕندِ برونہہ کُن یاد تھاونہٕ، تہٕ یِیہِ پَنٕنـ̡ دُشمنن نِش بچاوٕنـ̡ ۔\n10. تہٕ پننہِ خوشی ہٕندِس دۅہس منز، تہٕ پنہٕ نِس ریتن ہٕندِس آغازس منز، تہٕ پنہٕ نِس ریتن ہٕندِس آغازس مَنٛز، تہٕ پَنٕنـ̡ سٍتـ̡ سٍتـ̡ دِنہٕ آمٕژ نذرانہ پى۪ٹھ، تہٕ پَنٕنـ̡ امن ہٕندِس نذرانہ سٍتـ̡ بَناوٕنـ̡ ۔ یُتھ زن تِم تُہٕندِس خداہس برونہہ کُن یادگار آسن: بہٕ چُھس خداوند تُہند خدا۔\n11. تہٕ دۆیمہِ ریتہٕ کِس وُہمہِ دۅہہٕ سپُد گوٲہی ہٕندِس خیمہ منزٕ اوبرُک تُلنہٕ۔\n12. تہٕ بنی اسرٲیلیو دراو سینا کِس بیابانہٕ منزٕ پنُن سفر۔ تہٕ اوٚبرُن اوس پران کِس بیابانس منز آرام دِوان۔\n13. تہٕ تِمو کٔر گۅڈٕ موسیٰ سٕندِ اتھہٕ سٍتـ̡ خداوند سٕندِ حُکمس مُطٲبق پنُن سفر۔\n14.\\tگۅڈنچہ لٹہِ گۆو یہوداہ کین بچن ہٕندِس خٲمس مُطٲبق تہٕ تٔمۍ سٕندِس میزبانس پیٹھ اوس امیناڈاب سُند نیچو۔\n15.\\tتہٕ عیساکر سٕندِس اولادَن ہٕندِس قبیلس مَنٛز اوس نیتھانیل یُس زوار سُند نیچو اوس۔\n16.\\tتہٕ زبولون سٕندِس اولاد ہٕندِس قبیلہٕ کِس لشکرس پیٹھ اوس ہیلون سُند نیچو۔\n17. تہٕ خیمہ آو والنہٕ۔ تہٕ گرشون سٕندۍ نیچوۍ تہٕ میراری سٕندۍ نیچوۍ دراو خیمہ ہیتھ برونہہ کُن۔\n18.\\tتہٕ روبن سٕندِ خٲمہِ ہُند معیار آو تِہندِ فوجہٕ مطٲبق برونہہ کُن: تہٕ تٔمۍ سٕندِس میزبانس پیٹھ اوس شیدیور سُند نیچو الیزور۔\n19.\\tتہٕ شمعون سٕندِس بچن ہٕندِس قبیلہٕ کِس لشکرس پیٹھ اوس زُرشادایی سُند نیچو۔\n20.\\tتہٕ گاد سٕندِس اولادَن ہٕندِس قبیلہٕ کِس لشکرس پیٹھ اوس دُویلُن نیچو۔\n21.\\tتہٕ کُہہیتی دِژ مقدس مقامس ہٮ۪تھ برونہہ کُن، تہٕ باقیو کٔر تِمن خلاف خیمہ قٲیم۔ {دوٚیِم: یعنی گرشونائٹس تہٕ میراریٹس}\n22.\\tتہٕ افرائیم سٕندِس بچن ہٕندِس خٲمس ہُند معیار آو تِہندِ فوجہٕ مُطٲبق برونہہ کُن: تہٕ تٔمۍ سٕندِس میزبانس پیٹھ اوس امیہود سُند نیچو۔\n23.\\tتہٕ مناسہ سٕندِس اولادَس ہٕندِس قبیلس پیٹھ اوس گمالیئل یُس پیڈہزور سُند نیچو اوس۔\n24. تہٕ بنیامین سٕندِس اولاد ہٕندِس قبیلہٕ کِس لشکرس پیٹھ اوس عابدان، یُس گدعونی سُند نیچو اوس۔\n25.\\tتہٕ ڈین سٕندٮ۪ن شُرین ہٕندِس خٲمس ہُند معیار آو برونہہ کُن، یُس سارِنٕے خٲمن ہُند بدلہٕ اوس، تہٕ تٔمۍ سٕندِس میزبانس پیٹھ اوس اَمیشادایی ہُند نیچو۔\n26.\\tتہٕ آشر سٕندِس بچن ہٕندِس قبیلہٕ کِس میزبانس پیٹھ اوس اوکران سُند نیچو۔\n27.\\tتہٕ نفتالی ہٕندِس اولادَن ہٕندِس قبیلہٕ کِس لشکرس پیٹھ اوس احیرہ یُس عینان سُند نیچو۔\n28.\\tیِتھے پٲٹھـ̡ سپُد بنی اسرائیل ہُند سفر تہندِس لشکرس مطٲبق، ییلہ تِم برونہہ کُن پٔکۍ۔ {یتھہ پاٹھۍ: ہیب۔ یہٕ}\n29. تہٕ موسىٰ ہن ووٚن موسیٰ سٕندِس مٲلس راگویل سٕندِس نیچوِس ہوبابس سٍتـ̡ یُس موسیٰ سٕندِس مٲلس سٍتـ̡ چُھہ وَننہٕ آمُت، أسـ̡ چُھہ تتھ جایہِ کُن سفر کران یێمہِ مُتلق خداوند ووٚنمُت چُھ، بہٕ دِیہٕ ژے دِنہٕ: تێہہ گژھ اسہِ سٍتـ̡ تہٕ أسـ̡ چُھہ تُہٕندِس سٍتـ̡ نیکی کٔرِتھ، کیازِ خداوند چُھ اسرٲیلِس مُتلق نیک کتھ کٔرمٕژ۔\n30. تہٕ تٔمۍ ووٚن أمِس زِ بہٕ گژھٕ نہٕ نیران۔ مگر بہٕ نیرٕ پننِس زمینس کُن، تہٕ پننین رشتہ دارن کُن۔\n31. تہٕ تٔمۍ ووٚن، اسہِ تراوُن نہٕ، بہٕ چُھس ژےٚ دُعا کران۔ یوت تام ژیہ پتاہ چھکھ زِ أسۍ کِتھہ پاٹھۍ چھہِ بیابانن منز ڈیرٕ تراوُن، تہٕ ژے ہیکو اچھن بجایہ اسہِ خٲطرٕ ٲستھ۔\n32. تہٕ یێلہِ تہِ گژھہِ اسہِ سٍتـ̡ یێلہِ سٍتـ̡ خداوند اسہِ سٍتـ̡ نیکی کرِ۔\n33.\\tتہٕ تِم دراو خداوند سٕندِ پہاڑ پیٹھٕ ترٮ۪ن دۅہن ہُند سفر، تہٕ خداوند سٕندِ عہدُک صندوق دراو تِہندِ خٲطرٕ آرام کرنٕچ جاے ژھارنہٕ خٲطرٕ۔\n34.\\tتہٕ خداوند سُند اوبر اوس تِمن پیٹھ دۅہلہٕ ییلہ تِم خٲمہٕ منزٕ نیبر نیران ٲسۍ۔\n35.\\tتہٕ ییلہ صندوق برونہہ کُن پیوٚو، موسیٰ ین ووٚن زِ وۅتھٕ ووٚتھ، اے خداوند، تہٕ پَنُن دُشمن گژھہِ پھٔٹِتھ پھٔلِتھ۔ تہٕ یِم تۅہہِ سٍتۍ نفرت کران چھِ، تِم ژٔلِن ژٔلِتھ ژ\n36.\\tتہٕ ییلہ یہِ آرام دِیُت، تٔمۍ ووٚن اے خداوند، ساسہٕ بٔدۍ اسرٲیلِس کُن واپس۔ {واریاہ ساس: ہیب۔ دَہ ساس","1. تہٕ ییلہ لوکو شکایت کٔر، یہ گۆو خداوند ناراض تہٕ خداوند بوز۔ تہٕ تٔمۍ سُند شَرارتہٕ دِژ دِنہٕ۔ تہٕ خداوند سُند نار دزِتھ تہٕ یِمن ہٕندِس کیمپس مَنٛز دٔزِتھ دِنہٕ۔ {شکایت: یا، ٲسۍ شکایت کرن وٲلۍ} {یہ اوس ناپسندید: ہیب۔ یہ اوس کنن منز بد کار\n2. تہٕ لُکھ کٔر موسیٰ سٕندِس کُن فریاد ۔ تہٕ یێلہِ موسىٰ کٔر خداوند سٕنز دُعا دُعا، نار گۆو ژھیتہٕ۔ {اوس...: ہیب۔ ڈوب}\n3. تہٕ تٔمۍ ووٚن تٔمِس جایہِ ہُند ناو تِکیازِ یِمن مَنٛز اوس خداوند سُند نار دزان۔ {تبرہ: یعنی اکھ دزنہ}\n4.\\tتہٕ یِمن مَنٛز یُس رَلہٕ وُن اوس تہٕ یِمن مَنٛز یُس رَلہٕ وُن تہٕ وَنُن زِ اسہِ کُس دِیہِ ماز کھٮ۪نہٕ۔ {گٔیہِ...: ہیب۔ ہوس کٔرِتھ ہوس} {روُن...: ہیب۔ واپس، تہٕ رووُن}\n5.\\tاسہِ چھہ گاڈ یاد یُس اسہِ مصرس منز آزادانہ طور کھیوان اوس۔ کۅکرۍ، خربوزہ، تہ پیاز تہ رُہن:\n6.\\tمگر وۅنۍ چھہ سانہِ روح خشک گومت: {اتہِ چھہ نہ کانہہ تہِ، امہ مناہس علاوٕ، {سانہِ اچھن برونہہ کنہِ}۔\n7.\\tتہٕ مَنا اوس دھنیا ہٕندِس رَنٛگ ہٕندِس پٲٹھۍ۔ {امیک رنگ...: ہیب۔ اَمہ کِس أچھ ہٕنز}\n8.\\tلُکھ گٔیہِ نژان تہٕ جمع کٔرِتھ {یہ} گِلہٕ منز، یا کٔرِکھ اَتھ مَنٛز {یہ} مارٹرس منز، تہٕ بنووُن کیک تہٕ اَمیُک ذائقہٕ اوس تازٕ تیٖلُک ذائقہٕ۔\n9.\\tییلہ رٲژ خۅمس پیٹھ شبنم پیوٚو، منہ پیوٚو اتھ پیٹھ۔\n10. اَمہِ پَتہٕ بوز موسیٰ سٕندِس عیالس مَنٛز لُکھ وَنُن، پرٮ۪تھ أکِس خیمہٕ کِس دروازس پیٹھ، تہٕ خداوند سُند غصہٕ گۆو سٮ۪ٹھاہ دِنہٕ۔ موسیٰ تہِ اوس ناراض۔\n11. تہٕ موسىٰ ووٚن خداوند سٕندِس سٍتـ̡ کیازِ چُھہ پنہٕ نِس خادمس سٍتـ̡ دِژمُت؟ تہٕ کیازِ چھُنہٕ مےٚ ژےٚ نظرِ منٛز احسان حٲصِل کوٚرمُت، زِ ژے چھُکھ یِمن سارِنٕے لوٗکَن ہُنٛد بار میٲنِس پٮ۪ٹھ تھوومُت۔\n12.\\tمیہ چھا یمن سارِنٕے لوکن ہند تصور کورمُت؟ کیا میہ چھہ تم زامتۍ، تہ ژیہ ونن میہ ونن، تم نِن پننہِ چھۅکہِ منز، یتھہ پاٹھۍ اکھ دودھ دِنہٕ وول مول چُھس شُر دِوان، تتھ زمینس کُن یُس ژے پننین مٲلن سیتۍ واٹھ دِوان چھُ؟\n13. میہ کتہِ گژھہِ یمن سارِنٕے لُکن دِنہٕ خٲطرٕ ماز آسُن؟ تِکیازِ تِم چھِ میانہِ نِش روان ونان زِ اسہِ دِیُن ماز تاکہ أسۍ کھٮ۪و۔\n14. بہٕ ہیوٚک نہٕ یِم سارِنٕے لُکھ کُنی زَن برداشت کٔرِتھ، تِکیازِ یہِ چھُ میانہِ خٲطرٕ واریاہ گۄب۔\n15. تہٕ اگر ژے میہ سٍتۍ یِتھ سلوک کٔرِو، مے مارُن، بہٕ چھُس ژے دُعا کٔرِتھ، اگر میہ چانہِ نظرِ منز احسان میلہِ۔ تہٕ مےٚ گژھ نہٕ پنٕنۍ بدبختی وُچھان۔\n16.\\tتہٕ خداوند ووٚن موسیٰ سٕندِس سٍتـ̡ اسرٲیلٕکۍ ستتھ نفر جمع کٔرِتھ، یِمن تہٕ تِمن ہٕندِس سٍتـ̡ تہٕ تِمن ہٕندِس سٍتـ̡ تہٕ أنِو تِم جماعت کِس خیمہ خانس مَنٛز، یُتھ تِم توے سٍتـ̡ کھڑا گژھن۔\n17.\\tتہٕ بہٕ یِہ بۄن تہٕ ژے سٍتـ̡ کتھ کرٕنـ̡ تہٕ بہٕ رٔٹِتھ یُس روح تہٕ یُس تۅہہِ پیٹھ چُھہ، تہٕ بہٕ کرٕ تِمن سٍتـ̡ تہٕ تِم تُلَن تُلِتھ لُکن ہُند بار تُلُن، یُس نہٕ تُہۍ کُنی پان تُلِتھ۔\n18.\\tتہٕ لُکن وَنُن، پَگہہ تام پان پاک کرُن، تہٕ ماز کھٮ۪و، کیازِ تۅہہ چُھہ خداوند سٕندِس کنن منز رووُن، یہِ ونان زِ اسہِ کُس دِیہِ ماز کھٮ۪نہٕ خٲطرٕ؟ تِکیازِ یہِ اوس مصرس مَنٛز اسہِ سٍتـ̡ رَژھان، تێمہِ مۄکھٕ دِیہِ خداوند ژےٚ ماز تہٕ تُہۍ کھٮ۪و۔\n19. تُہۍ گژھِ نہٕ اَکہِ دۅہہ، نہ زٕ دۅہہ، نہ پانژھ دۅہہ، نہ دَہ دۅہہ، نہ وُہن دۅہہٕ۔\n20. {مگر} پورٕ اکھ ریتھ، یوتام نہٕ یہٕ تُہنزِ نستہٕ نِش نیرِ، تہٕ یہٕ گژھہِ تۅہہِ خٲطرٕ نفرت: کیازِ تۅہہ چُھہ خداوند سٕنز حقارت کٔرمٕژ یُس پانس مَنٛز چُھ، تہٕ أمِس برونہہ کُن رووُن، یہِ وَنُن زِ أسۍ کیازِ آیہ مصرہٕ منزٕ نیبر۔ {پورٕ...: ہیب۔ دۅہن ہند ریتھ}\n21.\\tتہٕ موسىٰ ووٚن زِ یِمن لُکھ یِمن مَنٛز بہٕ {چُھ}، چھِ شیہ لچھ ساس پیدل ۔ تہٕ ژے چُھہ ووٚنمُت، بہٕ دِیہ تِمن ماز، یُتھ تِم پوٗرٕ ریتھ کھٮ۪ن۔\n22.\\tیِمن ہٕندِ خٲطرٕ یِنہٕ کٔرِتھ؟ یا سمندرٕکۍ سٲری گاڈٕ یِن یِمن ہٕندِ خٲطرٕ جمع کرنہٕ، تِمن ہٕندِ خٲطرٕ کٲفی؟\n23. تہٕ خداوند ووٚن موسیٰ سٕندِس اتھس سٍتـ̡ کیا چُھہ ژھوٚٹ؟ ژے گژھہِ وۅنۍ وُچھِتھ زِ میون کلام گژھہِ ژے تام واتہِ کِنہ نہ۔\n24.\\tتہٕ موسیٰ دراو نیبر، تہٕ لُکن ووٚن خداوند سٕندِ کلام، تہٕ لُکن ہٕندٮ۪ن بزرگن ہٕندِ ستتھ نفر جمع کٔرِتھ تہٕ کٔرٕن خیمہ خانس اندۍ پٔکھۍ۔\n25. تہٕ خداوند آو أکِس اوبرس مَنٛز، تہٕ أمِس سٍتـ̡ کتھ کٔرٕن، تہٕ رٔٹِن سُہ روح یُس أمِس پیٹھ اوس، تہٕ دیتُن ستتھ بزرگن تہٕ دِتُن سُہ سپُد، {یہ} سپُد، {یہ} ییلہِ روح تِمن پیٹھ آرام کوٚر، تِمو کٔر پیشن گوئی، تہٕ رُکُن نہٕ۔\n26.\\tمگر کیمپس منز ٲسۍ زٕ نفر رودۍ، أکِس سُند ناو اوس ایلداد تہٕ بییِس میداد سُند ناو: تہٕ روح اوس تِمن پیٹھ تھپھ۔ تہٕ تِمو ٲسۍ تِمو منزٕ یِم لیکھنہٕ آمٕتۍ ٲسۍ، مگر گٔیہِ نہٕ خیمہ خانس کُن نٮ۪بر تہٕ تِمو کٔر خٲمس مَنٛز پیشن گویی کرنہٕ۔\n27.\\tتہٕ اَکھ جوان ژوٚل تہٕ موسیٰ سٕندِس وونُن تہٕ ووٚنُن ایلداد تہٕ میداد چھِ خٲمس مَنٛز پیشن گویی کران۔\n28.\\tتہٕ موسیٰ سٕندِس نوکر سُند نیچو یشوع دیت جواب تہٕ وونُن، میانہِ آقا موسیٰ، تِمن منع کرُن۔\n29. تہٕ موسىٰ ووٚن أمِس زِ کیا ژٕ چُھہ میانہِ خٲطرٕ حسد کران؟ خدایہ کرِ خدایہ سٕندِ سارِنٕے لُکھ پیغمبر، {تہٕ} زِ خداوند کرِ تِمن پیٹھ پنُن روح تراوُن!\n30.\\tتہٕ موسىٰ دِژ أمِس خٲمس مَنٛز، سُہ تہٕ اسرٲیلٕکۍ بزرگ۔\n31.\\tتہٕ ووت رب سٕندِ طرفہٕ واو تہٕ أنِن سمندرٕ منزٕ بٹیر، تہٕ دِژن خٲمس نِش پٲٹھۍ، یِتھ کٔنۍ یہ اَتھ طرفہٕ اکھ دۅہُک سفر اوس، تہٕ یِتھ کٔنۍ زِ یہ اوس أکِس دۅہُک سفر یُس دوٚیمہِ طرفہٕ اوس خٲمس اندۍ تہٕ یِتھ کٔنۍ زٕ ہیوٚر تھوٚد زمینہِ پیٹھ۔ {یتھہ پاٹھۍ یہ اکھ دۅہہ...: ہیب۔ یِتھ کٔنۍ زِ یہِ اوس أکِس دۄہُک طریقہٕ}\n32.\\tتہٕ لُکھ ووٚتھ سٲرۍسٕے دۅہہ، تہٕ سٲرۍسٕے رٲژ تہٕ دوٚیمہِ دۅہہ، تہٕ تِمو کٔر بٹیر جمع کٔرِتھ، یُس کم از کم جمع کٔرِتھ کٔرِتھ دَہ ہومر جمع کٔرِتھ، تہٕ تِمو پھٔہلٲوِکھ پانس خٲطرٕ سارِنٕے مُلکن ہٕندِس خٲمس اندۍ پٔکھۍ۔\n33.\\tتہٕ ییلہ ماز تہندِس دندن درمیان اوس، یێلہِ یہِ چٮ۪نہٕ برونہہ، خداوند سُند قہر آو لُکن پیٹھ دِنہٕ، تہٕ خداوندَن دِژ لُکن سٍتـ̡ سٮ۪ٹھاہ بٔڈ وباہ۔\n34.\\tتہٕ تٔمۍ ووٚن اَمہِ جایہِ ہُند ناو کیبروتھاواہ: تکیازِ تتہِ ٲسۍ تِمو لُکھ دفن کٔرۍمٕتۍ یِم ہوس کٔرۍ۔ {کِبروہتَواہ: یعنی ہوس ہٕنزِ قبر}\n35. {تہٕ} لُکھ گٔیہِ کِبروتھٹاوا پٮ۪ٹھٕ ہزروتھ تام سفر۔ تہٕ ہزروتھس منٛز روزن۔ {رہائش گاہ: ہیب۔ تم ٲسۍ اندر}","1.\\tتہٕ مریم تہٕ ہارون کٔر موسیٰ سٕندِس خلاف کتھ ییمہِ سٍتـ̡ أمِس سٍتـ̡ خاندر کورمُت اوس، تکیازِ تٔمۍ اوس أکِس ایتھوپِی زنانہِ سٍتـ̡ خاندر کورمُت۔ {ایتھوپین: یا، کشیٹ} {خانٛدر: ہیب۔ نِنہٕ آمُت}\n2. تہٕ تِمو ووٚن، کیا خداوند چُھ پٔزۍ پٲٹھـ̡ صرف موسىٰ سٕندِ دٔسۍ کتھ کٔرمٕژ؟ کیا تٔمۍ چھُنہٕ اسہِ تہِ کتھ کٔرمٕژ؟ تہٕ خداوند بوز {یہ}۔\n3.\\t(وۅنۍ اوس موسیٰ سٍتـ̡ سارِنٕے انسانس سٍتـ̡ سٍتـ̡ یُس {زمینہِ پیٹھ} ٲسـ̡ سٍت\n4. تہٕ خداوند کٔر اچانک موسیٰ سٍتـ̡ تہٕ ہارونس تہٕ مریمس سٍتـ̡ کتھ کرنہٕ، یێلہِ ترٚے کٔرِو جماعت کِس خیمہ خانس مَنٛز۔ تہٕ تِم ترٛےٚ آیہِ نٮ۪بر۔\n5. تہٕ خداوند آو اوبرٕ کِس ستونس مَنٛز، تہٕ ووت خیمہ کِس دروازس منز، تہٕ بُلووُن ہارون تہٕ مریم، تہٕ تِم دۅشوے آیہِ برونہہ کُن۔\n6.\\tتہٕ ووٚن میٲنۍ کلام بوزو: اگر توے منزٕ کانہہ نبی آسہِ، {بہ} خداوند کرِ پانس خوابس منز أمِس سٍتـ̡ ظٲہر کرنہٕ، {تہٕ} کرِ خوابس مَنٛز أمِس سٍتـ̡ کتھ کرنہٕ۔\n7.\\tمیون خادم موسیٰ {چُھ} نہٕ یُس میانہِ سارِنٕے گرس مَنٛز وفادار چُھ۔\n8.\\tبہٕ کٔرٕ تس سٍتـ̡ ٲسٕنـ̡ کتھ کٔرِتھ، ظاہری طور تہِ، تہٕ سیاہ تقریرَن منز نہٕ۔ تہٕ خداوند سٕنز تشبیہٕ گژھہِ سُہ وُچھان: تیلہِ کیازِ ٲسکھ نہٕ میٲنِس بندس موسیٰ سٕندِس خلاف کتھ کرنہٕ نشہِ خوفزدہ گومُت؟\n9. تہٕ خداوند سُند غصہٕ گۆو تِمن سٍتـ̡ دِنہٕ۔ تہٕ سُہ دراو روانہٕ۔\n10. تہٕ اوبُر دراو خیمہ منزٕ نیرِ۔ تہٕ وُچھ، مریم {بنییہ} کوڑھ، {سفید} شینہٕ ہیو تہٕ ہارون وُچھ مریمس کُن، تہٕ وُچھ، {سُہ} ٲس کوڑھ۔\n11. تہٕ ہارونن ووٚن موسیٰ سٍتـ̡ ہاے اے خداوند، بہٕ چُھس ژے عرض کران زِ اسہِ پیٹھ گژھ نہٕ سُہ گۅناہ یُس اسہِ بیوقوفی سٍتـ̡ کورمُت چُھ، تہٕ یتھ مَنٛز أسـ̡ گۅناہ کورمُت چُھ۔\n12.\\tسۅ گژھہِ نہٕ أکِس مٔرِس ہٕندِس پٲٹھۍ، یٔمِس سُہ ماجہ ہٕندِ رحمہٕ منزٕ نیرِتھ نٮ۪صف ماز کھٮ۪نہٕ آسہِ۔\n13. تہٕ موسىٰ کٔر خداوند سٕندِس کُن فریاد تہٕ وونُن، اے خدایہ، بہٕ چُھس ژے گُزاران۔\n14. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ اگر تٔمۍ سٕندِس مٲلہِ سٕندِس پھیکس پیٹھ تھوکُن آسہِ، تێلہِ گژھہِ نہٕ سَتن دۅہن شرم گژھُن؟ سُہ گژھہِ سَتن دۅہن خٲمہٕ منزٕ بند کرنہٕ یُن، تہٕ تمہ پتہٕ یِن أمِس {دوبارٕ} رٔٹنہٕ۔\n15.\\tتہٕ مریم آو سَتن دۅہن خٲمہٕ منزٕ بند کرنہٕ، تہٕ لُکھ گٔیہِ نہٕ توٚت تام سفر یوٚت تام نہٕ مریم اَننہٕ آو۔\n16.\\tتہٕ امہ پتہ لُکھ ہزروتھ پیٹھٕ ژٔلِتھ پران کِس بیابانس مَنٛز۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. ژٕ سوز نفر تاکہ تِم گژھن کنعان کِس سرزمینس تلاش، یُس بہٕ بنی اسرٲیلِس دِوان چھُ، تہٕ تِمن ہٕندِس مٲلِس قبیلہٕ سٍتـ̡ سوٗزِو اکھ نفر، یُس پرٮ۪تھ کانہہ حُکُمران آسہِ۔\n3.\\tتہٕ موسیٰ سٕندِ حُکمس سٍتـ̡ سوز تِم پران بیابان پیٹھٕ: تِم سٲری لُکھ أسـ̡ بنی اِسرٲیلـ̡ ہٕندِس کلہٕ سٍتـ̡ ۔\n4.\\tتہٕ یِمن ہُند ناو: روبن سٕندِس قبیلس منز، شموع یُس زکورُن نیچو۔\n5.\\tشمعون سٕندِس قبیلس منز، ہوری سُند نیچو شفعت۔\n6.\\tیہوداہ قبیلہٕ سٍتـ̡ کالب، یپھونیہ سُند نیچو۔\n7. اِساکر سٕندِس قبیلس منز، یوسف سُند نیچو ایگل۔\n8.\\tافرائیم سٕندِس قبیلس منز، اوشیہ سُند نیچو۔ {اوشیع: یشوع تہِ ونان چھِ}\n9.\\tبنیامین سٕندِس قبیلس منز، پالتی یُس راپو سُند نیچو۔\n10.\\tزیبولون قبیلہٕ سُند نیچو گڈیل سودی سُند نیچو۔\n11.\\tیوسف سٕندِس قبیلس منز، یُس منسی سُند نیچو گدی اوس۔\n12.\\tدان قبیلہٕ سٍتـ̡ ، جمالی سُند نیچو امیل۔\n13. آشر سٕندِس قبیلس منز، سیتھر میکائیل سُند نیچو۔\n14.\\tنفتالی قبیلہٕ منز، وپھسی سُند نیچو۔\n15. گاڈ سٕندِس قبیلس منز، ماچی سُند نیچو۔\n16.\\tیِم چھِ تِمن نفرن ہٕندِ ناو یِم موسیٰ ہن زمینہِ ہٕنز جاسوسی کرنہٕ خٲطرٕ سوزمٕتۍ۔ تہٕ موسىٰ وون اوشیہ نون یہوشوا سُند نیچو۔ {اوشیا: یتھ جوشوا تہِ ونان چھِ} {یہوشوع: یا، یشوع}\n17. تہٕ موسىٰ سوٗزۍ تِم کنعان کِس سرزمینس پیٹھ جاسوسی کرنہٕ خٲطرٕ، تہٕ تِمن وونُن، تِمن ووٚنُن یَتھ وتہِ جنوبس کُن تہٕ پہاڑس کُن کھسُن:\n18.\\tتہٕ وُچھِو زمین، یہِ کیا چُھہ}۔ تہٕ یِم لوٗکھ اَتھ مَنٛز روزان چھِ، چاہے تِم مضبوط آسن یا کمزور، کم یا زیادٕ۔\n19.\\tتہِ کُس زمین چھہ یتھ منز تم روزان چھہِ، سہ چھہ اصل یا خراب۔ تہٕ کمہٕ شہرن منٛز روزان چِھ، خیمن منٛز، یا مضبوط گڑھن منٛز۔\n20. تہٕ زمین کیا چُھ، کیا چُھ موٹۍ یا دبل، اتھ منز چھا لٔکر آسہِ، کِنہ نہ۔ تہٕ رٔژ ہمت تھاوُن، تہٕ زمینُک پھل أنِو۔ وۅنۍ اوس وقت {اوس} گۅڈنچہ لٹہِ پۅختہٕ انگورن ہند وقت۔\n21.\\tیِتھٕ کٔرِتھ گٔیہِ تِمو ہیوٚر تہٕ لٔگِتھ زِن بیابان پیٹھٕ رِحاب تام زمینہٕ ژھانڈان، یِتھٕ پٲٹھۍ انسان ہمَتھ کُن یِوان چھِ۔\n22.\\tتہٕ تِم ووت جنوبس کُن تہٕ آیہ ہیبرون کُن۔ ییتہِ احمان، شیشایی تہٕ تلمایی ، انک سٕندۍ شُرۍ ٲسۍ۔ (وۄنۍ اوس ہیبرون مصرس منٛز زوان برونٹھ ستھ وری بناونہٕ آمت۔)\n23.\\tتہٕ تِم آیہِ ایشکول کِس نالہِ نِش، تہٕ تتہِ ژٹِکھ اَکھ لٔنٛجہِ یتھ سٍتـ̡ انگور ہُند اکھ جھرمٹ اوس، تہٕ تِمو ژٔٹِکھ أکِس لٔرِس پیٹھ دۄن درمِیان ۔ تہٕ {تِمو أنِتھ} انار تہٕ انجیر ہٕندِ۔ {بروک: یا، وادی}\n24.\\tاتھ جایہ اوس نالہٕ اشکول وننہٕ آمُت، تکیازِ اَتھ انگورن ہُند جھرمٹ یُس بنی اسرائیل تتہِ ژٹِتھ ژٹِتھ اوس۔ {بروک: یا، وادی} {ایشکول: یعنی انگورن ہند اکھ جھرمٹ}\n25.\\tتہٕ تِم آیہ ژتٲجی دۅہہٕ پتہٕ زمینہٕ ژھانڈنہٕ نِش واپس۔\n26. تہٕ تِم گٔیہِ موسیٰ نِش تہٕ ہارون نِش تہٕ بنی اِسرٲیلِچ سارِنٕے جمٲژ نِش، پران کِس بیابانَس مَنٛز، قادیش کُن۔ تہٕ دِتُن تِمن تہٕ سارِنٕے جمٲژ تام کتھ واپس، تہٕ ہٲوِن تِمن زمینُک پھل۔\n27.\\tتہٕ تِمو ووٚن أمِس تہٕ وونُن، أسۍ وٲتِتھ زمینہِ ییتہِ ژے اسہِ وُچھمٕژ چھِ، تہٕ یێلہِ چُھہ دۄد تہٕ ماچھ سٍتـ̡ وسان ۔ تہٕ یہٕ چُھ امیک پھل۔\n28.\\tبہر حال چھہِ لُکھ مضبوط، یُس زمینس منز روزان چھہِ، تہٕ شہرن چھہِ دیوار لٔگِتھ، تہٕ واریاہ بٔڈۍ: تہٕ وُچھ اسہِ تتہِ انک سٕندِ شُرۍ۔\n29.\\tامالیقی چھ جنوبٕچ زمینس مَنٛز روزان: تہٕ حتی، تہٕ یبوسی تہٕ اموری چھ پہاڑن مَنٛز روزان: تہٕ کنعانی چھ سمندرس نِش تہٕ اردن کِس بٹھس پیٹھ روزان۔\n30.\\tتہٕ کالبَن کٔر موسیٰ سٕندِس برونہہ کُن لُکھ رُکاونہٕ تہٕ وونُن، أسۍ گژھو یکدم ہیوٚر تہٕ اَتھ پیٹھ قبضہ کرُن۔ تکیازِ أسۍ چھہِ اتھ پیٹھ قابو پانے لایق۔\n31.\\tمگر أمِس سٍتـ̡ یِم نفر وٲتِتھ وۆن، أسـ̡ ہێکہِ ہێکہِ نہٕ لُکن ہٕندِس خٕلافس سٍتـ̡ ہێکہٕ ہێکان۔ تکیازِ تم چھہِ اسہِ کھوتہ زیادہ مضبوط۔\n32.\\tتہٕ تِمو دِژ اَتھ زمینہِ مُتعلِق اکھ بد خبر یُس تِمو بنی اسرٲیلِس نِش ژھانڈان اوس، یہِ وَنُن زِ سُہ سرزمین، یُس أسۍ ژھانڈنہٕ خٲطرٕ گٔژھمٕتۍ، سُہ چھُ سُہ زمین یُس اَتھ ہٕندِس بسکینس کھٮ۪وان چھُ۔ تہٕ سٲری لوکھ یم اسہِ اتھ منز وچھمت چھہِ تم چھہِ بٔڈ قد وٲلۍ۔ {مرد...: ہیب۔ قدس ہٕندۍ مرد}\n33.\\tتہٕ اَتہِ وُچھ اسہِ دیو، انک سٕندِ نیچوۍ، یِم دیون ہٕندِس نیچِھس منز، تہٕ أسۍ ٲسۍ پننِس نظرس منز ٹڈٕکۍ پٲٹھۍ، تہٕ یِتھے پٲٹھۍ ٲسۍ أسۍ تِمن ہٕندِس نظرس منز۔","1.\\tتہٕ سارِنٕے جمٲژ کٔر آواز تُلِتھ تہٕ وُپھ دِتھ۔ تہٕ لوکھ رودۍ تمہ رٲژ روو۔\n2. تہٕ سارِوٕے بنی اسرٲیلِیو کٔر موسیٰ سٕندِس تہٕ ہارونس سٍتـ̡ بڑبڑاوُن، تہٕ سارِوٕے جمٲژ وۆن تِمن زِ کاش أسـ̡ أسـ̡ مصرٕکِس سرزمینس مَنٛز مٔرِتھ! نتہ خدایہ ہا اسہِ یتھ بیابانس منز مرُن!\n3. تہٕ کیازِ چُھ خداوند اسہِ یتھ سرزمینس مَنٛز واتنوومُت، تلوار سٍتـ̡ وسنہٕ خٲطرٕ، یُتھ سانہِ زنانہٕ تہٕ شُرِ شِکار گژھن؟ کیا اسہِ خٲطرٕ اوسا نہٕ بہتر زِ مصر واپس یِن؟\n4.\\tتہٕ تِمو ووٚن اَکھ أکِس أکِس سٍتـ̡ ، أسۍ بناوو اکھ کپتان، تہٕ أسۍ گژھو مصرس منز واپس۔\n5. پَتہٕ پۯاوٕ موسیٰ تہٕ ہارون بنی اسرائیل ہٕنزِ جماعت ہٕندِس سارِنٕے مجلسس برونہہ کُن بُتھِس پیٹھ۔\n6. تہٕ یشوع نون سُند نیچو تہٕ کالب، یِمو زمینس تلاشی دِنہٕ والیو منز، تِمو کٔر تِمن ہٕندِ پلو پھٔٹِتھ:\n7. تہٕ تِمو ووٚن بنی اِسرٲیلِس سٍتـ̡ سارِنٕے صحبتس سٍتـ̡ وَنُن زِ سُہ زمین، یُس أسـ̡ ژھانڈنہٕ خٲطرٕ پٔکِھہ، سُہ چُھ سٮ۪ٹھاہ اصل زمین۔\n8. یێلہِ خداوند اسہِ سٍتـ̡ خوش گژھہِ، تێلہِ کرِ سُہ اسہِ یتھ سرزمینس مَنٛز انن، تہٕ دِیہِ اسہِ دِنہٕ۔ اکھ زمین یُس دۄدٕ تہٕ ماچھہِ سٍتۍ وسان چھُ۔\n9. صرف کرو نہٕ خداوند سٕنز بغاوت تہٕ نہ کرو زمینہٕ کین لوکن سٍتـ̡ خوف۔ تِکیازِ تِم چِھہ سانہِ خٲطرٕ روٹی: تِہُند دفاع چُھ تِمن نِش دوٗر گومُت، تہٕ خداوند چُھ اسہِ سٍتـ̡ سٍتـ̡ کھوژُن: تِمن ہُند خوف نہٕ کرُن. شیڈو}\n10.\\tمگر سارِوٕے جمٲژ دِژ تِمن کٔنہِ کٔنہِ سٍتـ̡ کٔنـ̡ دِنُک حُکم۔ تہٕ خداوند سُند جلال گۆو سارِنٕے بنی اسرٲیلِس برونہہ کُن جماعت کِس خیمہ خانس مَنٛز ظٲہر۔\n11. تہٕ خداوند ووٚن موسیٰ سٕندِس سٍتـ̡ یِم لُکھ کٲتِس کالس دِیہِ مے اِشارٕ دِنہٕ؟ تہٕ تِمن سارِنٕے نشانن پیٹھ یِم میہ تِمن منز ہٲومٕتۍ چھِ، تِمن ہٕندِس پٲٹھۍ، کوتاہ کال روزِ تِمن پیٹھ یقین کرنہٕ۔\n12. بہٕ کرٕ تِمن وبا سٍتـ̡ مارٕ تہٕ یِمن ہٕندِس وٲرِس سٍتـ̡ بێزار کٔرِتھ، تہٕ بَناوٕ ژے تِمن ہٕندِ کھۅتہٕ بۆڈ قوم تہٕ طاقتور ۔\n13. تہٕ موسىٰ ووٚن خداونس سٍتـ̡ ، تیلہِ گژھن مصری بوزُن، (تکیازِ ژے کٔر یہِ لُکھ پننہِ طاقتہٕ سٍتـ̡ تِمن منزٕ اننہٕ؛)\n14. تہٕ تِم وَنَن یَتھ زمینہٕ کِس بسکینَس {یہ} تِمو بوزمُت زِ تُہۍ چُھہ یِمن لُکن مَنٛز چُھہ، زِ تُہُند اوٚبر چُھہ تِمن پیٹھ کھڑا تہٕ تُہُند اوبُر چُھہ تِمن برونہہ کُن، دۅہلہٕ اوٚبرٕ کِس تھمس منز، تہٕ رٲژ نارٕ کِس تھمس منز۔\n15.\\tوۅنۍ یێلہِ ژے یِمن لُکن سارِنٕے أکِس انسانس سٍتـ̡ مارُن، تیلہِ یِمو قومہٕ تۅہہِ ہٕنز شہرت بوزمٕژ آسہِ، تِم کَرٕن کتھ کٔرِتھ ونُن،\n16.\\tکیازِ خداوند ہیوٚک نہٕ یِم لُکھ تِمن سٍتـ̡ تِمن سٍتـ̡ اَنِتھ مَنٛز أنِتھ ہیوٚک نہٕ، تێمہِ مۄکھٕ کٔرِن تِم بیابانن مَنٛز مارنہٕ۔\n17. تہٕ وُن، بہٕ چُھس ژے التجا کران زِ میانہِ رب سُند طاقت گژھہِ بٔڈ آسُن، یُتھ زن ژے کتھ کٔرمٕژ چھِ،\n18.\\tخداوند چُھہ زیچھر تہٕ سٮ۪ٹھاہ رحمت، گناہ تہٕ خطا معاف، تہٕ کُنہِ تہِ طریقہٕ سٍتـ̡ چُھہ {قصور} پاک کران، تہٕ چُھہ نہٕ مٲلن ہٕنزِ بدکاری ہٕندِس شُرین سٍتـ̡ تریمہِ تہٕ ژوٗرمہِ پُرِ تام دِوان۔\n19.\\tمعافی دِیُن، یێمہِ لُکہٕ سٕندِ دُعا سٍتـ̡ چُھہ پننہِ رحمتٕچ عظمت، تہٕ یِتھٕ پٲٹھـ̡ ژے یِمن لُکن ہٕندِس بُنیادس مُطٲبِق تہٕ یێمہِ لُکہٕ سٍتـ̡ چُھہ وُنیُک تام معافی دِژمٕژ۔ {تام...: یا، وُنیُک}\n20. تہٕ خداوند ووٚن، مے چُھہ چانہِ کلامہٕ مطٲبق معافی دِژمٕژ:\n21.\\tمگر {یێتھـ̡ پٔزۍ پٲٹھـ̡ بہٕ زندٕ چُھس، سٲرٕے زمینہٕ گژھہِ خداوند سٕندِ جلال سٍتـ̡ بٔرِتھ۔\n22.\\tکیازِ تِمو سارِوٕے لُکھ یِمو میٲنۍ عظمت تہٕ میٲنۍ معجزات وُچھمٕتۍ، یِم میہ مصرس تہٕ بیابانن مَنٛز کٔرۍمٕتۍ، تہٕ وُنہِ دَہہِ لٹہِ لالچ دِژمٕژ چھِ، تہٕ میانہِ آواز بوزمٕژ چھِ۔\n23.\\tیقینا تِم وُچھن نہٕ سُہ زمین یُس بہٕ پننین مٲلن سٍتـ̡ حلف دِوان چُھ، تہٕ نہ آسہِ تِمن منز کانہہ تہِ یُس میہ اشتعال دِوان اوس، سُہ وُچھِن: {یقینا...: ہیب۔ اگر تم زمین وچھن}\n24. مگر میون خادم کالب، کیازِ أمس سٍتـ̡ اوس بیاکھ روح تہٕ سُہ اوس پورٕ پٲٹھـ̡ میانہِ پتہٕ، بہٕ اَنـ̡ سُہ زمینس مَنٛز یێلہِ سُہ گۆو۔ تہٕ تٔمۍ سٕندِس بُلِس آسہِ یہِ حٲصِل۔\n25. (وۅنۍ ٲسۍ امالیکی تہٕ کنعانی وادی منز روزان۔) پگاہ ژیہ پھیُرِتھ تہٕ بحر احمر کِس وتہِ کِنۍ بیابانن منز واتناوُن۔\n26. تہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ کتھ کرنہٕ،\n27.\\tمیہ کوتاہ کالس یہ بد کار جماعت برداشت کرُن، یُس میہ خلاف گڑبڑ کران چھُ؟ مے چُھہ بنی اسرٲیلِچ بڑبڑاہ بوزمٕژ، یُس تِم میانہِ خلاف بڑبڑاوان چھِ۔\n28.\\tتِمن ونُن، {یێلہِ پٲٹھـ̡ بہٕ زندٕ چُھس، خداوند چُھ ونان یِتھٕ پٲٹھـ̡ چُھہ میانین کنن منز کتھ کٔرمٕژ، تِتھے کٔرِو بہٕ تہٕ ژے سٍتـ̡ کٔرِتھ:\n29.\\tتُہٕندِس لاشہٕ یَتھ بیابانَس مَنٛز پیٚیہِ۔ تہٕ تۅہہِ ہٕندِس پوٗرٕ تعدادس مطٲبق، وُہن ؤرین تہٕ امہِ کھۄتہٕ زیادٕ وٲنسہِ ہٕندِس حسابس منز، یِمو میہ خلاف گُزراونہٕ آمٕژ چھِ،\n30.\\tیُس بہٕ ژیہ ژیہ اَتھ مَنٛز روزُن قَسم کٔرِتھ، یێمہِ سٍتـ̡ یۅسہٕ یُس یِمن ہُند نیچو یُس کالب، یُس یشوع سُند نیچو بٔرِتھ روزُن، یێمہِ سٍتـ̡ یێلہ تُل میون اتھہٕ}\n31.\\tمگر تۅہہِ شکار، یُس ژیہ شکار، بہٕ أنِتھ تہٕ تِم گژھن تتھ زمینس زانان یتھ سٍتۍ تۅہہ حقارت کران چھِ۔\n32.\\tمگر تۅہہِ ہٕندِس لاشہٕ سٍتـ̡ گژھن یَتھ بیابانس مَنٛز پَسنہٕ۔\n33.\\tتہٕ تُہٕندِ شُرِ گژھن ژتٲجی ؤرین بیابانن مَنٛز نژان، تہٕ تُہند لاشہٕ بیابانن مَنٛز ضایع گژھن۔ {آوارہ: یا، فیڈ}\n34.\\tیِمن دۅہن منز ژیہ زمینہِ ہنز تلاش کٔرِتھ، ژتٲجی دۅہہ، پریتھ دۅہہ، ژتجی ؤری تہِ گژھہِ ژیہ پنُن گناہ برداش، تہٕ ژیہ گژھہِ میون وعدہ پھُٹراونُک پتہ۔ {خلاف ورزی ...: یا، میون مقصد بدلاو}\n35. میہ چُھہ خداوند ووٚنمُت زِ بہٕ کرٕ یِمن سارِنٕے بد کار جماعتس سٍتـ̡ یُس میانہِ خلاف جمع سپدان چُھ، یێلہِ یێلہِ بێیہِ تِم کھٮ۪نہٕ یِن، تہٕ تتہِ گژھن تِم مرن۔\n36. تہٕ یِم نفر موسیٰ ہن زمینہِ ژھانڈنہٕ خٲطرٕ سوزمٕتۍ، یِم واپس آو، تہٕ سارِنٕے جماعت کٔرِکھ أمِس خٕلاف بےٚ عزتی کٔرِتھ،\n37.\\tتِم نفر یِمو زمینہِ مُتلق بد خبر دِنہٕ آو، گٔیہِ خداوند سٕندِ برونہہ کُن طاعون سٍتـ̡ مٔرۍ۔\n38.\\tمگر یشوع یُس نون سُند نیچو تہٕ کالب، یُس زمینس ژھانڈنہِ گۆو تِمن نفرن منز ٲسۍ، زندٕ۔\n39.\\tتہٕ موسىٰ ہن ووٚن یِم اقوالہٕ سارِنٕے بنی اسرٲیلِس تہٕ لُکن کٔر سٮ۪ٹھاہ ماتم ۔\n40. تہٕ تِم ووٚتھ صُبحٲے تہٕ تِمن ہٕندِس بالہٕ کِس تینتٲلِس پیٹھ ووٚتھ، وَنُن زِ أسۍ {یتہِ}، تہٕ گژھو تتھ جایہِ تام یُس خداوند وعدٕ کورمُت چُھ، کیازِ أسۍ چُھ گۅناہ کورمُت۔\n41. تہٕ موسىٰ ووٚن زِ وۅنۍ کیازِ چھِو خداوند سٕندِس حکمس خلاف ورزی کران؟ مگر یہ گژھہِ نہ ترقی۔\n42. ہیوٚر نہٕ گژھُن، کیازِ خداوند چُھہ نہٕ توے منز۔ یُتھ زِ تُہۍ گژھِ نہٕ پننین دُشمنن برونہہ کُن مارنہٕ۔\n43.\\tتکیازِ عمالیقی تہٕ کنعانی چِھہ تۅہہِ برونہہ کُن، تہٕ تُہۍ گژھِو تلوار سٍتـ̡ پٔرِتھ: کیازِ تۅہہِ چُھہ خداوند نِش پتھ کُن آمُت، تێلہِ آسہِ نہٕ خداوند توے سٍتـ̡ ۔\n44.\\tمگر تِمو گٔیہِ بالہٕ تینتٲلِس تام کھسُن، بہر حال خداوند سٕندِ عہد تہٕ موسیٰ سٕندِ عہدُک صندوق دراو نہٕ خٲمہٕ منزٕ نیبر۔\n45.\\tامہ پتہ آیہ امالیکیو تہ کنعانی یُس اتھ بالس منز روزان اوس، تہ لٔگۍ تمن ہورمہ تام تہ دِژکھ تمن بے قرار۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. بنی اسرٲیلِس سٍتـ̡ کتھ کٔرِو تہٕ تِمن وَنُن، یێلہِ تُہۍ پَنٕنـ̡ بستی ہٕندِس سرزمینس مَنٛز یِن، یُس بہٕ چُھس دِوان چُھ،\n3. تہٕ کرِ خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ نذرانہ پیش کرنہٕ، یا نذر پورٕ کرنہٕ خٲطرٕ یا آزاد نذرانہ منز، یا پننہِ سنجیدہ دعوتس مَنٛز، خداوند سٕندِس خٲطرٕ، کھورِ ہٕندِس یا ریوڑس سٍتـ̡ مٔٹھۍ مٔزِتھ دِنہٕ۔ الگ کَرنہٕ آمُت}\n4.\\tیُس یُس خداوند سٕندِ خٲطرٕ پنُن نذرانہ پیش کرِ، سُہ کرِ دٔہِم حِصہٕ آٹُک ماز پیش یُس تیلُک ژوٗرِم حصہٕ سٍتـ̡ رلاونہٕ آمُت آسہِ۔\n5.\\tتہٕ ژوٗرِم حِصہٕ چُھہ شرابُک ژوٗرِم حصہٕ یُس تُہۍ أکِس دانٛدٕ سٕندِ خٲطرٕ دزنہٕ یا قربانی سٍتـ̡ تیار کرُن۔\n6.\\tیا کُنہِ کُنہِ ماز خٲطرٕ تیار کرُن یُس تیٖلُک ترییم {حصہ} سٍتۍ رلاونہٕ آمُت چھُ۔\n7.\\tتہٕ شرابٕچ نذرانہ خٲطرٕ گژھ ژے شرابُک تریم حصہٕ پیش کرُن، {تکیاز} خداوند سٕندِ خٲطرٕ اکھ مٔٹھۍ ذائقہٕ۔\n8. تہٕ ییلہ تہٕ ژے دزنہٕ خٲطرٕ یا عہد کرنہٕ خٲطرٕ یا خداہس خٲطرٕ صلح کرنٕچ قربانی خٲطرٕ تیار کٔرِو:\n9.\\tتیلہِ اَنُن سُہ أکِس بیلس سٍتـ̡ تریہ دٔہِم دٔہِم آٹُک ماز نذرانہٕ یُس نصف ہِن تیٖلس سٍتـ̡ رلاونہٕ آمُت آسہِ۔\n10.\\tتہٕ تُہۍ اَنِن نصف ہِن شراب، یُس نارٕ سٍتـ̡ دِنہٕ آمُت چُھ، یُس خداوند سٕندِ خٲطرٕ مٔٹھہِ مَزٕ چُھہ دِنہٕ آمُت۔\n11.\\tیِتھٕ پٲٹھۍ گژھہِ أکِس دانٛدس خٲطرٕ، یا أکِس کۅکرِ ہٕندِس خٲطرٕ، یا کۅکرِ ہٕندِس خٲطرٕ، یا أکِس بچہٕ سٕندِ خٲطرٕ کرنہٕ۔\n12. یُس تعداد تُہۍ تیار کرِو، تِتھے پٲٹھۍ کٔرِو پرٮ۪تھ أکِس تہندِ تعدادٕ مُطٲبق۔\n13. یُس سٲری ملکہٕ سٍتـ̡ پٲدٕ سپدان چُھ، سُہ گژھِ یِتھٕ پٲٹھـ̡ یِم کٲم کٔرِتھ، یُس نارٕ سٍتـ̡ دِنہٕ آمُت چُھ، یُس خداوند سٕندِ خٲطرٕ مٔٹھـ̡ مٔٹھـ̡ چُھہ پیش کرنہٕ یِوان۔\n14. تہٕ یێلہِ کانہہ اجنبی چُھہ تۅہہِ سٍتـ̡ روزِ، یا یێلہِ تہٕ یُتھ زن تۅہہ کران چھُو، تِتھے پٲٹھۍ کرِ سُہ تہِ۔\n15.\\tاَکھ فرمان {گژھہِ تۅہہِ ہٕندِ خٲطرٕ} تہٕ یُس اجنبی سٕندِ خٲطرٕ تہٕ یُس تُہٕندِس سٍتـ̡ روزان چُھہ، یُس تُہٕندِس زمانس مَنٛز ہمیشہٕ خٲطرٕ چُھہ اَکھ حکم: یِتھٕ پٲٹھـ̡ تُہۍ {چھِ}، تِتھے پٲٹھـ̡ گژھہِ اجنبی خداوند سٕندِ برونہہ کُن روزُن۔\n16. اَکھ قانون تہٕ اَکھ طٔریٖقہٕ آسہِ تۅہہِ سٕندِ خٲطرٕ، تہٕ یُس تۅہہِ سٍتـ̡ روزان آسہِ۔\n17.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ وۆن،\n18.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرو تہٕ تِمن ونُن، ییلہ تم تتھ زمینس مَنٛز وٲتِو ییتہِ بہٕ تۅہہِ اَننہٕ آمُت،\n19. تیلہِ گژھہِ یہِ زِ ییلہ تم زمینہِ ہٕنزِ روٹی کھیٚو، تہٕ یێلہِ کٔرِو خداوند سٕندِ خٲطرٕ اکھ نذرانہ پیش کرنہٕ۔\n20.\\tژیہ کٔرِو پننہِ گۅڈنچہ لٹہِ کۅکرِ ہُند کیک پیش کرنہٕ، یِتھے پٲٹھۍ کٔرِو ژۅکہٕ ہُند نذرانہ تہِ۔\n21. پنہٕ نِس گۄڈنِکِس آٹِس مَنٛز دِیُو تُہۍ پَنٕنـ̡ پَنٕنـ̡ پى۪ٹھ\n22. تہٕ یێلہِ تہٕ یێلہِ یِمن سارِنٕے حُکمن ہٕنز پاسداری کٔرِتھ یِم خداوند موسیٰ سٕندِ سٍتـ̡ کٔرۍمٕتۍ،\n23. {حتی} سُہ یُس خداوند موسیٰ سٕندِ اتھہٕ سٍتـ̡ حُکُم دِیُتمُت چُھ، ییمہِ دۅہہٕ پیٹھٕ خداوند موسىٰ سُند حُکُم دِیُتمُت چُھ، تہٕ تُہٕندِس پَتہٕ پۯاوٕنـ̡ پى۪ٹھ۔\n24.\\tتیلہِ گژھہِ یێلہِ جمٲژ ہٕندِس علمس ورٲے جہالت سٍتـ̡ کرنہٕ ییہِ، زالنہٕ خٲطرٕ گژھہِ سارِنٕے جمٲژ ہٕندِ خٲطرٕ اکھ بچہٕ دِنہٕ خٲطرٕ، خدایہِ سٕندِ خٲطرٕ مٔٹھۍ مٔٹھہِ ہٕندِس ذائقہٕ سٍتـ̡ تہٕ تٔمۍ سٕندِس شرابٕچ نذرانہ سٍتـ̡ تہٕ گۅنہٕ ہٕندِ نذرانہٕ خٲطرٕ اکھ بچہٕ دِنہٕ۔ {بغیر...: ہیب۔ اچھن منز} {طریق: یا، آرڈیننس}\n25. تہٕ پادٕرۍ کرِ بنی اِسرٲیلِچ سارِنٕے جماعتن ہُند کفارہٕ، تہٕ یِمن ہٕندِ خٲطرٕ یِیہِ معافی دِنہٕ۔ تِکیازِ یہِ چھُ جہالت: تہٕ تِم کرِ پنٕنۍ نذرانہ ، یُس نارٕ سٍتـ̡ خداوند سٕندِ خٲطرٕ دِنہٕ آمُت چھُ، تہٕ تِمن ہٕندِس گۅناہ ہٕندِس نذرانہ سٍتـ̡ خداوند سٕندِ برونہہ کُن دِنہٕ یِن، تہٕ تِمن ہٕنزِ جہالت کِنـ̡ ۔\n26. تہٕ یِمن منز روزُن وٲلِس سارِنٕے اِسرٲیلِس سٍتـ̡ تہٕ یُس اجنبی روزان چُھ، سُہ گژھہِ معاف۔ سارِنٕے لُکھ ٲسۍ جہالتَس مَنٛز وُچھان۔\n27.\\tتہٕ یێلہِ کانہہ جان جہالت سٍتـ̡ گۅناہ کٔرِتھ گۅناہ کٔرِتھ گۅنہٕ نِش گۅنہٕ کٔرِتھ۔\n28.\\tتہٕ پادٕرۍ کرِ تٔمِس روحس خٲطرٕ کفارہٕ یُس لاعلمی سٍتـ̡ گۅناہ کران چُھ، یێلہِ سُہ خداوند سٕندِس برونہہ کُن جہالت سٍتـ̡ گناہ کرِ، تٔمِس سٍتـ̡ کفارہ دِنہٕ۔ تہٕ أمِس یِیہِ معافی دِنہٕ۔\n29. یُس جہالت سٍتـ̡ گۅناہ کران چُھ، تُہٕندِ خٲطرٕ گژھہِ اَکھ شریعت یُس اسرٲیلِس مَنٛز زامُت چُھ، تہٕ یُس تِمن مَنٛز روزان چُھ۔ {گناہ: ہیب۔ ڈوتھ}\n30. مگر یُس روح گستاخی سان کرُن، {چاہے سُہ زمینس منز زامُت آسہِ، یا اجنبی آسہِ، سُہ چُھ خداوند سُند ملامت کران۔ تہٕ سُہ روح گژھہِ پننین لوکن منز ژٹنہٕ۔ {مفروضہ: ہیب۔ تھدِ اتھہٕ سٍتۍ}\n31.\\tکیازِ تٔمۍ چُھ خداوند سٕندِس کلامَس حقارت کٔرمٕژ، تہٕ پنُن حکم پھُٹرٲومُت، سُہ روح گژھہِ پوٗرٕ پٲٹھـ̡ ژٹنہٕ یُن۔ تٔمۍ سُند بدکار گژھہِ أمِس پیٹھ۔\n32.\\tییلہ بنی اسرائیل بیابانن منز ٲس، تمو وُچھ اکھ انسان یُس سبت کہ دۅہہ لورِ جمع کران اوس۔\n33.\\tتہٕ یِمو أمِس لورِ جمع کران وُچھنہٕ آمُت، تِمو أنۍ سُہ موسیٰ تہٕ ہارونس نِش تہٕ سارنٕے جماعتس نِش۔\n34.\\tتہٕ تِمو تھوو سُہ وارڈس منز، تکیازِ یہ اوس نہٕ اعلان کرنہٕ آمُت زِ أمِس کیا گژھہِ کرنہٕ۔\n35. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ یُس انسان یِیہِ یٔقیٖنی طور مارنہٕ یُن، سارِنٕے جماعت گژھن أمِس کٔنہِ سٍتـ̡ کٔنہِ سٍتـ̡ کٔنـ̡ کٔنہِ سٍتـ̡ کٔرِتھ۔\n36.\\tتہٕ سارِوٕے جماعت أنۍ أمِس خٲمہٕ ورٲے تہٕ کٔرِکھ کَنہِ کٔنہِ سٍتـ̡ تہٕ سُہ موٗد۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n37. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n38.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرٕنـ̡ تہٕ تِمن کٔرِو حکم زِ تِم بناوِ پنہٕ نـ̡ پٲٹھـ̡ پنہٕ نـ̡ پٲٹھ\n39.\\tتہٕ یہ گژھہِ تۅہہِ ہٕندِس کُنہِ تہٕ یہ زِ تُہۍ چھِو نہٕ پننِس دِلس تہٕ پننین أچھن ہٕنز تلاش کٔرِتھ، ییمہ پتہٕ تہٕ تُہۍ کُنہِ\n40. یُتھ تۅہہ یاد تھاوُن، تہٕ میٲنۍ سٲری حُکُم کٔرِو تہٕ پَنٕنِس خداہٕ سٕندِ خٲطرٕ پاک روزُن۔\n41. بہٕ چُھس خداوند تُہند خدا، یُس تُہُند خدا بنان چُھس، بہٕ چُھس خداوند تُہند خدا۔","1.\\tوۅنۍ کورہ، الیابس نیچو حضرت تہٕ ابیرام، الیابس نیچو تہٕ پیلتھ سُند نیچو، روبن سٕندِس نیچوِس آن، رٔٹِتھ {مرد}۔\n2. تہٕ تِم گٔیہِ موسىٰ سٕندِس برونہہ کُن، بنی اسرٲیلِس منز، مجلسہٕ ہٕندِس زٕ ہتھ پنژاہ شہزادن سٍتـ̡ یِم جمٲژ مَنٛز مشہوٗر۔\n3. تہٕ تِمو گٔیہِ موسیٰ سٕندِس تہٕ ہارونس خلاف جمع تہٕ تِمن وونُن، {تُہۍ چِھہ پانس سٍتـ̡ زیادٕ رٹان، یێلہِ سارِنٕے جماعت چِھہ پاک، تہٕ خداوند چُھہ تِمن مَنٛز: تێلہِ کیازِ چُھہ خداوند سٕنزِ جماعت ہٕندِس پیٹھٕ پانس تھوٚد کٔرِتھ؟ {یے نِیو...: ہیب۔ یہ چھہ تۅہہِ خاطرہ واریاہ کینہہ\n4.\\tتہٕ ییلہ موسیٰ ہن بوز، سُہ پیوٚو بُتھِس پیٹھ۔\n5. تہٕ تٔمۍ کوراہس تہٕ تٔمۍ سٕندِس سارِنٕے صحبتس سٍتـ̡ کتھ کٔرِتھ وونُن زِ پگہہ تام تہِ کرِ خداوند ہاوِ زِ کُس چُھ تٔمۍ سُند تہٕ کُس چُھہ پاک۔ تہٕ سُہ کرِ أمِس نزدیک: یُس تہِ أمِس چُھس ژٲرِمُت، سُہ تہِ کرِ أمِس نزدیک۔\n6. یہ کرُن؛ کورہ تہٕ تٔمۍ سٕنز سٲری صحبت۔\n7. تہٕ اَتھ مَنٛز نار تراوُن، تہٕ یِمن مَنٛز تراوُن پگہہ خداوند سٕندِ برونہہ کُن، تہٕ سُہ گژھہِ یُس انسان یُس خداوند ژٲرِ، سُہ گژھہِ پاک آسُن: اے لیوی سٕندِ فرزندو، یُس تہٕ یُس انسان چُھہ ژٲرِو۔\n8. تہٕ موسىٰ ووٚن کورہس زِ بوزو، اے لیوی سٕندِ فرزندو، بہٕ چُھس دُعا کٔرِتھ:\n9. {باسان چُھہ یہِ چُھہ تۅہہِ خٲطرٕ اکھ لۄکٕٹ کتھ زِ اسرٲیلٕکہِ خداہن چُھ تۅہہِ اسرٲیلِچ جماعت نِش الگ کورمُت، یُس تۅہہِ پانس نزدیک اننہٕ مۅکھہٕ خداوند سٕندِس خیمہ سٕنزِ خدمت کرنہٕ مۅکھہٕ تہٕ تِمن ہٕنز خدمت کرنہٕ خٲطرٕ چُھہ جماعت برونہہ کُن کھڑا سپدُن؟\n10.\\tتہٕ تۅہہِ نِش تہٕ تُہٕندِس سارِنٕے بٲے لیوی سٕندِ نیٚچوِس پانس سٍتـ̡ نِش أنِتھ، تہٕ تُہۍ چھِو پادٲری تہِ ژھاران؟\n11.\\tکمہِ وجہہ کِنۍ چُھہ تۅہہ تہٕ تُہٕنز سٲری جماعت خداوند سٕندِس خلاف جمع گٔمٕژ: تہٕ ہارون کیا چُھہ یُس تُہۍ أمِس خلاف بڑبڑاوان چھِو؟\n12.\\tتہٕ موسىٰ سوٗز الیاب سٕندِس نیچوۍ داتھن تہٕ ابیرامس بُلاونہٕ خٲطرٕ، یِمو ووٚن زِ أسۍ یِنہٕ نہٕ وٲتِتھ:\n13.\\tکیا یہ چھہ کانہہ لۅکٹ چیز یُس ژے اسہِ تتھ زمینہِ منزہ نیبر کڈان یُس دۄد تہٕ ماچھ سٍتۍ وسان چھُ، بیابانن منز مارنہٕ خٲطرٕ، مگر ژے بنوو اسہِ پیٹھ پنُن پان مکمل طور شہزادہٕ؟\n14. توے چُھہ نہٕ اسہِ تتھ زمینس مَنٛز انمُت یُس دۄد تہٕ ماچھ سٍتـ̡ وسان چُھ، یا چُھہ اسہِ کھہَن تہٕ انگورن ہٕنز وراثت دِژمٕژ: کیا ژٕ کٔرِکھ یِمن نفرن ہٕنزِ أچھ ژھیپہٕ؟ اسہِ گژھہِ نہ برونہہ کُن۔ {پُٹ...: ہیب۔ بور آؤٹ}\n15.\\tتہٕ موسیٰ گوٚو سٮ۪ٹھاہ شرارت، تہٕ ووٚنُن خداوندَس زِ تِہٕنزِ نذرانہ ہُند احترام کرُن نہٕ: مے چُھس نہٕ تِمن نِش اکھ گَرٕ تہٕ نہ چُھس یِمو منزٕ أکِس تہِ تکلیف دِژمٕژ۔\n16. تہٕ موسىٰ ووٚن کوراہس زِ تُہۍ تہٕ تِم تہٕ ہارونس برونہہ کُن روزُن تہٕ پگہہ گژھُن:\n17.\\tتہٕ پرٮ۪تھ أکِس شخصس نِش تٔمۍ سُند سنسر تہٕ تِمن مَنٛز ترٲوِو بخور تہٕ اَنُن پرٮ۪تھ أکِس شخصس سٍتـ̡ زٕ ہتھ پنژاہ باوُن۔ تۅہہ تہِ، تہٕ ہارون، پرٮ۪تھ کانہہ تٔمۍ سُند سنسر۔\n18.\\tتہٕ تِمو رٔٹِتھ پرٮ۪تھ أکِس شخصس سٍتـ̡ تٔمِس سٍتـ̡ نار تہٕ دِژُکھ اگربُت، تہٕ کھٔڑِکھ موسیٰ تہٕ ہارونس سٍتـ̡ جماعت کِس خیمہ کِس دروازس پیٹھ۔\n19. تہٕ کوراہن کٔر تِمن خلاف سارِنٕے جماعت جماعت ہٕندِس خیمہ کِس دروازس تام جمع تہٕ خداوند سُند جلال آو سارنٕے جماعتس برونہہ کُن ظٲہر۔\n20. تہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ کتھ ،\n21.\\tیَتھ جمٲژ نِش الگ گژھِو، یُتھ بہٕ یِم أکِس لمحس منز کھٮ۪تھ۔\n22.\\tتہٕ تِمو گٔیہِ بُتھِس پٲٹھۍ، تہٕ وونُن، اے خدا، سارِنٕے جسمن ہٕندِس روحن ہُند خدا، کیا اَکھ انسان گۅناہ کٔرِتھ، تہٕ کیا ژٕ گژھہٕ سارِنٕے جمٲژ سٍتـ̡ شرارت؟\n23.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن\n24.\\tجمٲژ سٍتـ̡ کٔرِو کتھ کرٕن، کورہ، داتھن تہٕ ابیرام کِس خیمہ خانہٕ پیٹھٕ تھوٚد کٔرِو۔\n25. تہٕ موسیٰ ووٚتھ تہٕ گوٚو داتھن تہٕ ابیرامس نِش۔ تہٕ اسرٲیلٕکۍ بزرگ گٔیہِ أمِس پتہٕ۔\n26.\\tتہٕ تٔمۍ ووٚن جماعتس سٍتـ̡ وونُن، بہٕ چُھس ژےٚ دُعا کٔرِتھ، یِمن بدکارن ہٕندِس خیمہ منزٕ نیرِو، تہٕ تِمن ہٕندِس خٲمہٕ منزٕ گژھِو نہٕ تِمن ہٕندِس سارِنٕے گۅناہ سٍتـ̡ ژٔلِتھ تہٕ یِمن ہٕندِس سارِنٕے گۅنہٕ سٍتـ̡ ژٔلِتھ گٔژھِو۔\n27.\\tیِتھٕ کٔنۍ گٔیہِ تِم کورہ، داتھن تہٕ ابیرام کِس خیمہ خانہٕ منزٕ پرٮ۪تھ طرفہٕ تہٕ دتھان تہٕ ابیرام درٛاو تہٕ کھٔیہِ پننین خیمن ہٕندِس دروازس پیٹھ، تہٕ تِہٕنزِ خانٛدارِن، تہٕ تِہندِ نیچوۍ تہٕ تِہندِ لۄکٹۍ شُرۍ۔\n28.\\tتہٕ موسىٰ ووٚن زِ اَتھ سٍتـ̡ گژھہِ ژیہ پتاہ زِ خداوند چُھہ میہ یِم سٲری کٲم کرنہٕ خٲطرٕ سوزمُت۔ تکیازِ {مے} چھہ نہ پننہِ ذہنس منز {کٔرۍمٕتۍ}۔\n29.\\tاگر یِم نفر سارِنٕے انسانن ہٕندِ عام موتُک مرُن، یا یِمن سارِنٕے انسانن ہٕندِ زیارت پتہٕ یِن کرنہٕ۔ {پتہٕ} خداوند چُھ نہٕ مے سوزمُت۔ {عام ...: ہیب۔ یتھ کٔنۍ زِ پرتھ انسان چُھ}\n30.\\tمگر یێلہِ خداوند نۆو چیز بناوِ، تہٕ زمینہِ چُھہ پنُن بوش کھولِتھ تہٕ تِمن سارِنٕے سٍتـ̡ نِگِلہِ تہٕ یێلہِ تِم جلدی کھۅڈس مَنٛز وسان چھِ۔ تیلہِ گژھہِ تۅہہ سمجھ زِ یمو نفرو چھہ رب سُند اشتعال دِژمُت۔ {بناوُن...: ہیب۔ اکھ مخلوق بناوُن}\n31.\\tتہ سپد یہ سپد ییلہ تمۍ یم سٲری لفظ بولنہ بند کرۍ متۍ چھہِ، زِ زمینہِ ہند کلاو پھٹتھ یُس تمن تلہ کنہِ اوس۔\n32.\\tتہٕ زمینہِ کھول پنن ٲس، تہٕ تِمن ہٕندِس گرس تہٕ تِمن سارِنٕے انسانن ہٕندِس نِش یِم کوراہس سٍتـ̡ وابستہٕ ٲسۍ، تہٕ تِمن ہٕندِس سارِنٕے سامانس نِش گِلہِ۔\n33.\\tتِم تہٕ یِمن سٍتـ̡ سارِنٕے سٍتـ̡ گٔیہِ زِندٕ گٔیہِ، تہٕ تِم گٔیہِ جمٲژ منزٕ بٔنِتھ گٔیہِ۔\n34.\\tتہٕ سارِوٕے اِسرٲیل، یُس تِمن اندۍ پٔکھۍ اوس، ژٔلِتھ ژٔلِتھ تِمن ہٕندِس فریاد سٍتـ̡ تکیازِ تِمو ووٚن زِ یێلہِ زٔمیٖن گِلہِ اسہِ تہِ۔\n35. تہٕ خداوند سٕندِ طرفہٕ نار دراو تہٕ زٕ ہتھ پنژاہ نفر کھٲلِتھ یِمو بخور پیش کٔرۍ۔\n36.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n37.\\tہارون سٕندِس نیچوِس الیعزرس سٍتـ̡ کتھ کرٕن، زِ سُہ تُلِن دزنہٕ منزٕ تہٕ یُس نار پھٔہلِتھ دِنہٕ۔ تکیازِ تم چھہِ ہالو۔\n38.\\tیِمن گۅنہگارن ہٕندِس پانس سٍتـ̡ بٔنِتھ یِم خداوند سٕندِس برونہہ کُن پیش کرنہٕ آمٕتۍ، تێمہِ کِنۍ چھِ یِم مقدس بناونہٕ آمٕتۍ، تہٕ یِم گژھن بنی اسرٲیلِن ہٕندِ خٲطرٕ نشانہٕ۔\n39.\\tتہٕ الیعازر پادٕرۍ رٔٹِتھ کٔرِتھ دِنہٕ آمٕژ تہٕ یِمو سٍتـ̡ دٔزِتھ دِنہٕ آمٕژ ٲس۔ تہٕ تم آیہ قربان گاہک کور خٲطرٕ وسیع {پلیٹہٕ} بناونہٕ:\n40. {یُس نہٕ اسرٲیِل سٕندِس بُلِس سٍتـ̡ آسہِ، یُس نہٕ ہارون سٕندِس نِش آسہِ، یُس نہٕ خداوند سٕندِس برونہہ کُن بخور پیش کرنہٕ خٲطرٕ یُس نہٕ کانہہ اجنبی آسہِ۔ زِ سُہ گژھہِ نہٕ کورہٕ سٕندِس سٍتـ̡ تہٕ تٔمۍ سٕندِس صحبتس سٍتـ̡ آسُن، یِتھ کٔنۍ خداوند أمِس موسیٰ سٕندِ اتھہٕ سٍتـ̡ ووٚنمُت۔\n41.\\tمگر دۅہہ کٔر بنی اسرٲیلِچ سارِنٕے جماعت موسیٰ سٕندِس تہٕ ہارونس خلاف گڑبڑ کٔرِتھ وَنُن زِ یێلہِ چُھہ خداوند سٕندِس لُکھ مٲرِتھ مٲرِتھ۔\n42. تہٕ سپُد یہِ سپدُن، یێلہِ جماعت موسیٰ ہس تہٕ ہارونس خلاف جمع گٔیہ، تِمو کٔر جماعت کِس خیمہ کُن نظر، تہٕ وُچھِتھ گۆو اوٚبرُن تہٕ خداوند سُند جلال آو ظٲہر۔\n43. تہٕ موسیٰ تہٕ ہارون آو جماعت کِس خیمہ برونہہ کُن۔\n44. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ کتھ ،\n45.\\tژیہ تُلِتھ تُلِتھ یُتھ بہٕ یِم أکِس لمحس منز کھٮ۪تھ۔ تہٕ تِم پیوٚو بُتھِس پیٹھ۔\n46. تہٕ موسىٰ ووٚن ہارونس زِ اکھ سنسر نِش تہٕ قربان گاہس پیٹھ نار تراوُن، تہٕ اگربتی تراوُن، تہٕ جلدی گژھ جماعتس نِش، تہٕ تِمن خٲطرٕ کفارہٕ کرُن، کیازِ خداوند سٕندِ طرفہٕ چُھ غضب نیران۔ طاعون چُھ شروع گومُت۔\n47. تہٕ ہارون روٚٹ موسیٰ سُند حُکُم، تہٕ ژوٚل جمٲژ ہٕندِس درمِس منز۔ تہٕ وُچھِتھ گۆو لُکن مَنٛز طاعون شروع: تہٕ تٔمۍ دِژ بخور تہٕ لُکن ہٕندِ خٲطرٕ کفارہٕ۔\n48. تہٕ سُہ اوس مُردٕ تہٕ زندن درمیان کھڑا ۔ تہٕ طاعون آو رُکاونہٕ۔\n49.\\tیِم یِم طاعون مَنٛز موٗدمٕتۍ، تِمن علاوٕ ٲسۍ ژۅداہ ساس ستھ ہتھ، یِم کورہ سٕندِس معاملس سٍتـ̡ مٔرۍ۔\n50. تہٕ ہارون آو موسیٰ ہس نِش جماعت کِس خیمہ کِس دروازس پیٹھ واپس۔ تہٕ آو طاعون رُکاونہٕ۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرٕن، تہٕ تِمن سارِنٕے شہزادن ہٕندِس گرس مُطٲبق رٔٹِو تہٕ تِہندِ سارِنٕے شہزادن ہٕندِس گرس مُطٲبق رٔٹِو باہ لٔرۍ۔\n3. تہٕ تُہۍ لیکھِو ہارون سُند ناو لیوی سٕندِس لورِس پیٹھ، یێلہِ یێلہِ تہندِس مٲلِس ہٕندِس گرس ہٕندِس سرس خٲطرٕ آسہِ۔\n4. تہٕ تہٕ ژے تھاو تِم گوٲہی برونہہ کُن جماعت کِس خیمہ خانس مَنٛز، یتہِ بہٕ ژے سٍتـ̡ مِلنہٕ۔\n5.\\tتہٕ یێمہِ سٍتـ̡ یێلہِ سٍتـ̡ یێلہِ بہٕ ژٲرِ، سُہ پھۄلہٕ پھۄلُن، تہٕ بہٕ کَرٕ پانس نِش بنی اسرٲیلـ̡ ہٕنزِ بڑبڑاہٕ کَرٕنـ̡ تہٕ یێمہِ سٍتـ̡ تِم تۅہہِ سٍتـ̡ گُزراونہٕ یِنـ̡ ۔\n6. تہٕ موسىٰ کٔر بنی اِسرٲیلِس سٍتـ̡ کتھ تہٕ تِہٕندِیو شہزادن دِژ پرٮ۪تھ أکِس شہزادس سٍتـ̡ تہندِس مٲلِس سٕندِ گرٕ مُطٲبق باہ لٔرۍ، تہٕ ہارون سٕنز لٔر ٲس تِہندِ لورِ منز۔ {اکھ راڈ...: ہیب۔ أکِس شہزادٕ سٕندِ خٲطرٕ اکھ لاٹھ، أکِس شہزادٕ سٕندِ خٲطرٕ اکھ لاٹھ}\n7. تہٕ موسیٰ کٔر گواہ سٕندِس خیمہ خانس مَنٛز لورِ خدایہِ سٕندِس برونہہ کُن۔\n8.\\tتہٕ سپُد یہ زِ پگہٕ دۅہہ آو موسیٰ گواہ سٕندِس خیمہ خانس مَنٛز۔ تہٕ وُچھِتھ آو ہارون سٕنز لٔر لیوی سٕندِ گرٕ خٲطرٕ کٔڈِتھ، تہٕ کٔرٕن کُلۍ تہٕ پھۄلٕن، تہٕ بادام دِنہٕ۔\n9. تہٕ موسیٰ کٔر خداوند سٕندِ برونہہ کُن سارِنٕے لٔرۍ، تہٕ تِمو وُچھِتھ پرٮ۪تھ أکِس انسانس سٕنز لٔر نِنہٕ۔\n10. تہٕ خداوند ووٚن موسیٰ سٕندِس گوٲہی برونہہ کُن ہارون سٕنز لٔر دُبارٕ أنِن، یُس باغین خلاف نشانہٕ خٲطرٕ تھاونہٕ یُن۔ تہٕ ژے کٔرِو تِہٕنزِ گڑبڑ میانہِ نِش تِمن ہٕنزِ گُرگویی ہٕندِس سٍتـ̡ یُس نہٕ مَرُن۔ {باغی: ہیب۔ بغاوتک بچے}\n11. تہٕ موسىٰ کٔر یِتھٕ پٲٹھۍ خداوند أمِس حُکُم دِیُت، تِتھۍ کٔرِن أمِس تہِ۔\n12. تہٕ بنی اسرائیلو ووٚن موسیٰ ہس سٍتـ̡ کتھ زِ وُچھو أسۍ مران تہٕ أسۍ چھِ ماران تہٕ أسۍ سارِوٕے ختم سپدان چھِ۔\n13. یُس تہِ خداوند سٕندِس خیمہ خانس نزدیک یِیہ، سُہ چُھ مَرُن: کیا أسـ̡ مرنہٕ سٍتـ̡ مٔرِتھ؟","1. تہٕ خداوند ووٚن ہارونس زِ تہٕ تُہٕندِس نیچوِس تہٕ تُہٕندِس مٲلہِ سُند گرٕ تہٕ تُہٕندِس مٲلِس سٍتـ̡ پَنٕنـ̡ پادٕرِ ہُند گُناہ تُلُن۔\n2. تہٕ تُہٕندِس مٲلہِ سٕندِس قبیلہٕ سٕندِس بٲے تہِ أنِو پانس سٍتـ̡ یُتھ تۅہہِ سٍتـ̡ رٔلِتھ تہٕ تۅہہِ سٍتـ̡ رٔلِتھ تہٕ تۅہہِ سٍتـ̡ خدمت کرنہٕ۔\n3. تہٕ تِم تھاون تُہند تہٕ سارِنٕے خیمہ خانہٕ ہٕندِس انبارس نِش یِنہٕ، یُتھ نہٕ تِم تہٕ تُہہِ تہِ مرُن۔\n4. تہٕ تِم گژھن تۅہہِ سٍتـ̡ رٔلِتھ تہٕ خیمہٕ چہِ سارِنٕے خدمتہٕ خٲطرٕ یِن جماعت ہٕندِس خیمہ ہٕندِس خٲمِس سٍتـ̡ رٔٹِتھ تہٕ کانہہ اجنبی گژھہِ نہٕ تۅہہِ نِش یِنہٕ۔\n5. تہٕ تُہۍ تھاوِو مقدس مقامُک تہٕ قربان گاہُک ذمہ دار، یُتھ زن نہٕ بنی اسرٲیلِس پیٹھ کانہہ قہر گژھہِ۔\n6. تہٕ وُچھمُت، بہٕ چُھس تُہٕندِس بٲے لاوی بنی اِسرٲیلِس مَنٛز نِمٕتۍ، تہٕ تِم چُھہ خداوند سٕندِ خٲطرٕ دِنہٕ آمُت، یُس جماعت ہٕندِس خیمہ سٕنزِ خدمت کرنہٕ خٲطرٕ دِنہٕ آمُت۔\n7. تێمہِ مۅکھہ تہٕ تۅہہِ سٍتـ̡ تہٕ تُہٕندِس نیچوِس سٍتـ̡ پَنٕنـ̡ پادٕرٕ سُند عہدٕ تھاوُن قربان گاہٕچ تہٕ پردٕ کِس پرٮ۪تھ چیزس مۅکھہٕ۔ تہٕ تُہۍ کٔرِو خدمت: مے چُھہ تُہند پادٕرۍ سُند عہدٕ دِژمُت تہٕ یُس اجنبی یُس نزدیک یِیہِ مارنہٕ۔\n8. تہٕ خداوند چُھ ہارونس سٍتـ̡ وَننہٕ آمُت، وُچھ، مے تہِ چُھہ ژے بنی اسرٲیلـ̡ ہٕندِس سارِنٕے مقدس چیزن ہٕنزِ نذرانہ ہُند ذمہٕ دِژمُت۔ میہ دِژ تِم مسح کرنہٕ کِنۍ تہٕ چانہِ نیچوین ہمیشہٕ خٲطرٕ اکہ حکمہٕ سٍتـ̡ دِژمٕژ۔\n9. یِہ آسہِ تۅہہِ سارِوٕے کھۄتہٕ مُقدس چیزو منز، یُس نارٕ نِش محفوٗظ آسہِ، تِہُند پرٮ۪تھ کانہہ ماز نذرانہ تہٕ تِہُند پرٮ۪تھ کانہہ گۅناہ نذرانہ تہٕ تِہُند پرٮ۪تھ کانہہ گناہ نذرانہ یُس تِم میانہِ خٲطرٕ پیش کرِ، تہٕ تُہندِ خٲطرٕ آسہِ تۅہہِ تہٕ تُہٕندٮ۪ن نیٚچوٮ۪ن ہٕندِ خٲطرٕ سارِوٕے کھۄتہٕ مقدس آسان۔\n10. مُقدس مقامس مَنٛز گژھ یہ کھیوٚن۔ پرٮ۪تھ کانہہ نر گژھہِ یہِ کھٮ۪ن: یہِ آسہِ تۅہہِ خٲطرٕ مُقدس۔\n11. تہٕ یہِ {چُھ} تُہُند؛ تِہٕندِس تحفٕچ نذرانہ سٍتـ̡ چُھہ بنی اسرٲیلـ̡ ہٕندِس سارِنٕے لہر سٍتـ̡ دِنہٕ آمُت: مے چُھہ تِم تہٕ تۅہہِ سٍتـ̡ تہندِس نیچوِس تہٕ تہنزِ کورِ ہمیشہٕ خٲطرٕ دِژمُت، یُس تہندِس گَرَس مَنٛز پاک آسہِ، سُہ گژھہِ اَمہ سٍتـ̡ کھٮ۪نہٕ۔\n12. تیلُک سارِوٕے بہتٔریٖن تہٕ شرابُک تہٕ کٕنُک سارِوٕے بہتٔریٖن مٮ۪وٕ یُس تِم خداوند سٕندِ خٲطرٕ دِنہٕ یِن، مے چُھہ ژے دِژمُت۔ {بہترین: ہیب۔ چربی}\n13. یُس تہٕ یُس تہٕ زمینس مَنٛز گۅڈٕ پۄختہٕ آسہِ، یُس تِم خداوند نِش انِن، سُہ آسہِ تُہُند ۔ یُس تہندس گرس منز صاف آسہِ سہ گژھہِ کھیوٚن۔\n14. اسرٲیلِس مَنٛز وقف کرنہٕ آمُت پرٮ۪تھ کانہہ چیز گژھہِ تُہُند آسُن۔\n15. پریتھ کانہہ چیز یُس سارِنٕے جسمس مَنٛز میٹرکس کھولان چُھ، یُس تِم خداوند سٕندِ نِش انان چُھ، {چاہے سُہ انسان آسہِ یا درندٕ، سُہ گژھہِ تُہُند آسُن: توتہِ گژھہِ انسان سُند گۅڈنیُک زُو تہٕ ناپاک درندن ہُند گۅڈنِچہِ اولاد تہٕ ژے کرِ نجات دِنہٕ۔\n16.\\tیُس ریتہ وٲنسہِ پیٹھٕ چھُکھ نجات دِنہٕ یِن، تِم گژھِ پننہِ اندازٕ مُطٲبق پانژھ شیکل پونسہٕ دِنہٕ یُن، یُس وُہ گیرہ چھُ۔\n17. مگر گاو ہُند گۅڈنچہ لٹہِ، یا کُنہِ کۅکرِ ہُند گۄڈنیُک، یا ژھاوُل سُند گۅڈنچہ اولاد، تہٕ ژیہ گژھِ نہٕ چھُنہٕ چھُ۔ تِم {چھِ} مُقدس: تہٕ تِہُند خوُن چُھکھ قربان گاہس پیٹھ، تہٕ تِہُند چربی زٲلِتھ چُھہ نارٕ سٍتـ̡ دِنہٕ آمٕژ نذرانہ خٲطرٕ، یُس خداوند سٕندِ خٲطرٕ مٔٹھۍ مٔٹھۍ۔\n18.\\tتہٕ تِمن ہُند ماز آسہِ تۅہہ، یِتھٕ پٲٹھۍ لہرِ ہُند سین تہٕ دٔچھُن پھیُر تہٕ دٔچھُن پھیُر آسہِ۔\n19. یِم مُقدس چیزن ہٕنزِ سارِنٕے نذرانہ یُس بنی اسرٲیلِس خداوند سٕندِ خٲطرٕ پیش کران چُھ، مے چُھہ ژے تہٕ تُہٕندِس نیچوِس تہٕ کورِ ہمیشہٕ خٲطرٕ أکِس قانونس سٍتـ̡ دِژمٕتۍ، یہِ چُھ خداوند سٕندِ برونہہ کُن تہٕ تُہٕندِس بُلِس سٍتـ̡ ہمیشہٕ خٲطرٕ نوٗنُک عہد ۔\n20. تہٕ خداوند چُھہ ہارونس سٍتـ̡ وَنُن زِ تِہٕندِس سرزمینس مَنٛز گژھِ نہٕ تُہُند کانہہ وَرث، تہٕ تِمن مَنٛز آسہِ نہٕ تُہُند کانہہ حصہٕ۔\n21. تہٕ وُچھِو مے لیوی سٕندِس شُرین اسرٲیلِس مَنٛز سارِوٕے دٔہِم وَرثہٕ خٲطرٕ، تِہٕنزِ خدمتہٕ خٲطرٕ، یێمہِ سٍتـ̡ تِم خدمت کران چھِ، {حتیٰ کہ} جماعت کِس خیمہ خانہٕ سٕنزِ خدمتہٕ خٲطرٕ۔\n22. نہ گژھِ بنی اسرائیل یِنہٕ پتہٕ جماعت ہٕندِس خیمہ خانس نزدیک یِن، یێلہِ گژھن تِم گۅناہ برداشت کٔرِتھ مرُن۔ {تہٕ مرُن: ہیب۔ مرُن}\n23. مگر لاوی گژھن جماعت ہٕندِس خیمہ خانہٕ سٕنز خدمت کرنہٕ، تہٕ تِم گژھن پنُن گناہ برداشت کرنہٕ۔ یہِ روزِ تُہنزن نسلن ہٕندِس سلسلس منز ہمیشہٕ خٲطرٕ اکھ قانون زِ بنی اسرٲیلِس مَنٛز چُھنہٕ تِمن ہُند کانہہ وراثت۔\n24. مگر بنی اسرائیلُک دہ، یُس تِم خداوند سٕندِ خٲطرٕ نذرانہ پیش کران چِھ، مے چُھس لاوِین وَرث دِنہٕ خٲطرٕ دِژمُت، تێمہِ مۄکھٕ چُھس مے تِمن وَنُن زِ بنی اِسرٲیلِس مَنٛز میلہِ نہٕ تِمن ہُند کانہہ وَرث۔\n25.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n26. یِتھٕ پٲٹھـ̡ کٔرِو لاوِین سٍتـ̡ کتھ تہٕ تِمن ونُن، یێلہِ تم بنی اسرٲیلـ̡ سٍتـ̡ تُہٕندِس وَرثہٕ سٍتـ̡ دِنہٕ آمُت چُھ، تێلہِ کٔرِو اَمہِ ہُند دٔہِم حِصہٕ خداوند سٕندِ خٲطرٕ پیش کرنہٕ۔\n27.\\tتہٕ {یہ} تُہٕندِ ہُند نذرانہ گژھہِ تۅہہِ سٍتـ̡ گنزراونہٕ، یِتھٕ پٲٹھۍ {یہ} چھُ ژٔٹِھہِ ہُند مَکُل تہٕ شرابُک پورٕ پٲٹھۍ۔\n28. یِتھٕ پٲٹھـ̡ کٔرِو تُہۍ پَنٕنـ̡ سارِنٕے دِہٕنـ̡ ہٕندِس خداوند سٕندِس سٍتـ̡ دِنہٕ یُس تۅہہِ بنی اِسرٲیلـ̡ نِش حٲصل سپدان چُھ۔ تہٕ تُہۍ کٔرِو اَمہِ سٍتـ̡ خداوند سٕندِ کُدٕرِ ہارونس نذرانہ دِنہٕ۔\n29. پنہٕ نِس سارِنٕے تحفو مَنٛز کٔرِو تُہۍ خداوند سٕندِ پرٮ۪تھ کُنہِ ہُند نذرانہ پیش کٔرِو، یێمہِ سٍتـ̡ سارِوٕے کھۄتہٕ بہترین، حتیٰ کہ اَمہ منزٕ پاک حصہٕ تہِ پیش کٔرِو۔ {بہترین: ہیب۔ چربی}\n30. تێمہِ کِنۍ چُھہ تِمن ونُن، یێلہِ تێلہِ یێلہِ تُہۍ اَمہ سٍتـ̡ بہتٔریٖن ہُند ہُرٮ۪ر کٔرِو، تێلہِ ییہِ یہِ لاوِین ہٕندِ خٲطرٕ گنزراونہٕ یُن۔ {بہترین: ہیب۔ چربی}\n31. تہٕ تُہۍ تہٕ پننین گرن ہٕندِس پرٮ۪تھ جایہِ کھٮ۪وُن، تکیازِ یہِ چُھہ تُہٕندِس عبادتس مَنٛز تُہُند انعام۔\n32. تہٕ یێلہِ تہٕ یێلہِ تہٕ اَمہ سٍتـ̡ چُھہ تُہۍ اَمہِ سٍتـ̡ کُنہِ تہِ گۅناہ کٔرِتھ، یێلہِ تہٕ یێلہِ تُہۍ اَمہِ سٍتـ̡ مُقدسَس سٍتـ̡ مٔرِو۔","1. تہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ کتھ ،\n2. یہِ چُھ شریعتُک حکم یُس خداوند دِیُتمُت چُھ، یُس زَن بنی اِسرٲیلِس سٍتـ̡ کتھ کرٕن، یێمہِ سٍتـ̡ تِم اَنـ̡ اکھ وۄزُل گٲو یێمِس مَنٛز نہٕ کانہہ داغ آسہِ، {تہٕ} یێمہِ سٍتـ̡ نہٕ زانہہ تہِ وُچھمُت چُھ:\n3. تہٕ تُہۍ دِیِو سُہ پادٕرۍ الیزارس نِش، یُتھ سُہ أمِس خٲمہٕ نیبر نیرِتھ، تہٕ سُہ کرِ أمِس بُتھِس برونہہ کُن مٲرِتھ۔\n4. تہٕ الیعزر پادٕرۍ نِیہِ تٔمۍ سُند خوُن پننہِ اونگجہِ سٍتـ̡ تہٕ سَتھ لٹہِ چُھکھ تٔمۍ سُند خوُن سٍتـ̡ سٍتـ̡ جماعت کِس خیمہ خانس برونہہ کُن چُھکُن:\n5.\\tتہٕ {اَکہِ} کرِ گاو أمِس نظرِ برونہہ کُن زالُن۔ تٔمۍ سُند ماز تہٕ تٔمۍ سُند خون، تٔمۍ سٕندِس گُرِ سٍتۍ، سُہ دزُن:\n6.\\tتہٕ پادٕرۍ نِیہِ دیودار لٔکر، تہٕ ہِسپ تہٕ سُرخ تہٕ دِیہِ گاوِ ہٕندِس زالنس منز۔\n7. پَنُن پَنُن پلو چھلُن، تہٕ سُہ کرِ پنُن ماز آبہٕ سٍتـ̡ سرانہٕ، تہٕ اَمہِ پتہٕ گژھہِ سُہ خٲمس مَنٛز، تہٕ پادٕرۍ گژھہِ ناپاک روزُن۔\n8.\\tیُس أمِس زٲلِتھ آسہِ سُہ پَنُن پلو آبہٕ سٍتـ̡ چھلناوُن، تہٕ سُہ گژھہِ آبہٕ سٍتـ̡ ناپاک روزُن۔\n9. تہٕ یێلہِ کُنہِ گۅنہٕ سُند سوٗر جمع کٔرِتھ، تہٕ یێلہِ کُنہِ خٲمہٕ ورٲے صاف جایہِ تھاونہٕ یُن، تہٕ یہِ گژھہِ بَے بنی اِسرٲیلِس ہٕندِس اجتماعہٕ خٲطرٕ تھاونہٕ یُن، یێلہِ چُھہ گۅنہٕ ہٕندِ خٲطرٕ پاکیزگی ۔\n10.\\tیُس گاوِ ہُند سوٗر جمع کرِ، سُہ گژھہِ پَنُن پلو چھلناوُن، تہٕ یُس تہٕ یُس تہِ روزان آسہِ، سُہ روزِ ہمیشہٕ خٲطرٕ أکِس قانونس خٲطرٕ۔\n11.\\tیُس کٲنسہِ شخصہٕ سٕندِس لاشس اتھہٕ لاگہِ، سُہ گژھہِ ستن دۅہن ناپاک روزُن۔ {مرد: ہیب۔ انسان سُند روح}\n12.\\tسُہ کرِ تریمہِ دۅہہ پان پاک تہٕ سٔتِمہِ دۅہہ گژھہِ سُہ پاک روزُن، مگر اگر سہ تریمہِ دۅہہ پان پاک کرِ، تیلہِ گژھہِ نہ سٔتِم دۅہہ پاک روزُن۔\n13. یُس تہِ کٲنسہِ تہِ مردہ انسان سٕندِس لاشس اتھہٕ لاگان چُھ، تہٕ پانس پاک کرُن چُھہ نہ، سُہ چُھ خداوند سٕندِس خیمے ناپاک کران۔ تہٕ سُہ روح گژھہِ اسرٲیلِس نِش ژٹنہٕ یُن: کیازِ جدایی ہُند آب آو نہٕ تس پیٹھ چھُکاونہٕ، سُہ گژھہِ ناپاک ۔ تٔمۍ سٕنز ناپاکی چھِ وُنہِ تہِ أمِس پیٹھ۔\n14.\\tیِہ شریعت چُھہ یێلہِ یێلہِ کانہہ شخص خیمہ مَنٛز مران چُھ: یُس تہٕ خیمس مَنٛز یُس {چُھ} چُھ، سُہ گژھہِ ستن دۅہن ناپاک روزُن۔\n15.\\tتہٕ پرٮ۪تھ کُنہِ کھُلہٕ بانہٕ یُس نہٕ کُنہِ تہِ پوشہٕ آسہِ، سُہ چُھ ناپاک۔\n16.\\tیُس تہِ یُس تلوار سٍتـ̡ مارنہٕ یِنہٕ وٲلِس کھہَس مَنٛز یا لاشہٕ سٍتـ̡ یا کُنہِ مردٕ سٕنزِ أڈجہِ یا قبرِ سٍتـ̡ اَتھٕ لاگہِ، سَتھ دۅہہٕ گژھہِ ناپاک روزُن۔\n17. تہٕ أکِس ناپاک شخصہٕ سٕندِ خٲطرٕ گژھن تِم گۅنہٕ خٲطرٕ پاکیزگی ہٕندِ دزمٕژ گۅپھ ہٕندِس سوٗر سٍتـ̡ نِنہٕ، تہٕ اَتھ مَنٛز ییہِ وسوُن آب أکِس بانس مَنٛز تراونہٕ: {Ashes: Heb. گرد} {دوڑ...: ہیب۔ زندٕ آب یِن دِنہٕ}\n18.\\tتہٕ پاک شخص گژھہِ ہیسپ نِتھ آبس منز ڈباونہٕ تہٕ خیمس پیٹھ، تہٕ سارنٕے بانن پیٹھ، تہٕ تِمن شخصن پیٹھ یُس أڈجہِ یا مارنہٕ آمُت، یا أکِس مردس یا قبرس پیٹھ چھُکُن دِیہِ۔\n19.\\tتہٕ صاف سُہ گژھِ تریمہِ دۅہہ تہٕ سٔتِمہِ دۅہہٕ ناپاکِس پیٹھ چھُکُن، تہٕ سٔتِمہِ دۅہہٕ گژھِ سُہ پان پاک کرُن، تہٕ پَنُن پلو چھلناوُن، تہٕ آبہٕ سٍتـ̡ سرٛان کرُن، تہٕ سٍتـ̡ گژھہِ صاف روزُن۔\n20. مگر یُس انسان ناپاک آسہِ، تہٕ پانس پاک کرِ نہٕ، سُہ روح گژھہِ جمٲژ منزٕ ژٹنہٕ، کیازِ تٔمۍ چُھ خداوند سٕندِس مقدس مقامس ناپاک کورمُت: جدایی ہُند آب چُھنہٕ تس پیٹھ چُھکاونہٕ آمُت۔ سُہ {چُھ} ناپاک۔\n21.\\tتہٕ یِمن ہٕندِ خٲطرٕ گژھہِ دٲیمی قانون زِ یُس جدایی ہُند آب چھُکُن چھُکھ سُہ پَنُن پلو چھلُن۔ تہٕ یُس جدایی ہٕندِس آبس اتھہٕ لاگہِ سُہ گژھِ ناپاک روزُن۔\n22.\\tتہٕ یُس تہِ ناپاک شخص اتھہٕ لاگہِ سُہ گژھہِ ناپاک آسہِ۔ تہٕ یُس روح اتھہٕ لاگان چُھ، سُہ گژھہِ ناپاک روزُن۔","1. تمہ پتہ آیہ بنی اسرائیل، {حتیٰ کہ} سورے جماعت گۅڈنکس ریتس منز زِن کِس صحراہس منز: تہٕ لوکھ رودۍ قادیشس مَنٛز بسان۔ تہٕ مریم گٔیہٕ تتہٕ دفن کرنہٕ۔\n2. تہٕ جمٲژ خٲطرٕ اوس نہٕ آب تہٕ تِمو گٔیہِ موسیٰ سٕندِس تہٕ ہارونس خلاف پان جمع ۔\n3. تہٕ لُکھ لُکھ موسیٰ سٕندِس سٍتـ̡ رٔلِتھ تہٕ وونُن زِ کاش أسـ̡ أسـ̡ مٔرِتھ ییلہ سانہِ بٲے خداوند سٕندِ برونہہ کُن مٔرۍ!\n4. تہٕ ژے کیازِ چُھہ خداوند سٕنزِ جماعت یتھ بیابانس مَنٛز اننہٕ یُتھ زِ أسۍ تہٕ سانہِ چاروٲے گژھن اتہِ مرُن؟\n5. تہٕ کیازِ چُھکھ اسہِ مصرہٕ منزٕ نیبر نیرنہٕ خٲطرٕ، اسہِ یتھ بدکار جایہِ تام اننہٕ خٲطرٕ؟ یہٕ چُھ نہٕ بیٲلۍ، یا انجیر ہٕنٛز، یا انگورن ہٕنٛز، یا انار ہٕنٛز جاۓ۔ نہ چنہٕ خٲطرٕ چُھ نہٕ کانہہ آب ۔\n6. تہٕ موسیٰ تہٕ ہارون گٔیہِ مجلسہٕ ہٕندِس حٲضِرِ پیٹھٕ جماعت کِس خیمہ کِس دروازس تام، تہٕ تِم گٔیہِ بُتھِس پیٹھ، تہٕ خداوند سُند جلال آو تِمن برونہہ کُن ظٲہر۔\n7. تہٕ خداوند ووٚن موسیٰ سٕندِس سٍتـ̡ کتھ\n8.\\tلٔر رٔٹِتھ تہٕ ژے تہٕ ہارون پنُن بٲے جمع کٔرِو تہٕ تِمن ہٕنزِ نظرن برونہہ کنہِ کٔنہِ کٔنہِ کٔرِتھ کتھ کٔرِو۔ تہٕ سُہ دِیہِ پنُن آب تہٕ تِمن کٔنہِ کٔنہِ آب دِنہٕ، یِتھٕ کٔنۍ دِیُکھ جمٲژ تہٕ تِہٕندِس درندَس چُھنہٕ۔\n9. تہٕ موسیٰ تُل خداوند سٕندِ برونہہ کُن لٔرِتھ یُس أمِس حُکُم اوس دِنہٕ۔\n10.\\tتہٕ موسیٰ تہٕ ہارون کٔر جماعت کنہِ کنہِ برونہہ کنہِ جمع تہٕ تٔمۍ ووٚن تِمن بوزو، اے باغو۔ اسہِ پزیا ژیہ اتھ کنہِ منز آب انن؟\n11. تہٕ موسىٰ تُل پنُن اتھہٕ، تہٕ لٔج پنٕنہِ لٔرِ سٍتـ̡ کٔنہِ دۄیہِ لٹہِ۔ تہٕ آب دراو واریاہ زیادٕ، تہٕ جمٲژ لوٚگ تہٕ تِہٕندِس جانور تہِ۔\n12. تہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ کتھ کرنہٕ، یێلہِ تہٕ یێلہِ تہٕ یێمہِ سٍتـ̡ یێلہِ تہٕ یێلہِ یێلہِ تہٕ\n13.\\tیہ چھہ مریبہ ہند آب۔ کیازِ بنی اسرٲیلیو کٔر خداوند سٍتـ̡ جدوجہد تہٕ سُہ گۆو تِمن مَنٛز پاک۔ {مریبہ: یعنی کشمکش}\n14.\\tتہٕ موسىٰ سوٗزۍ قادش پیٹھٕ ادوم کِس بادشاہس نِش قاصد۔ یِتھٕ پٲٹھۍ چُھہ تُہند بٲے اسرائیل، تہٕ ژے چھے سٲری مصیبت پتاہ یُس اسہِ سٍتـ̡ سپدیومُت چُھ: {bebeen...: Heb. لٔبِو اسہِ}\n15.\\tسانۍ مول کِتھہ پاٹھۍ گٔے مصرس مَنٛز تہٕ أسۍ رودۍ واریاہس کالس مصرس مَنٛز روزان۔ تہٕ مصریو کٔر اسہِ تہٕ سانین آباؤ اجدادن پریشان:\n16. تہٕ ییلہ أسۍ خداوند کُن فریاد کٔرۍ، تٔمۍ بوز سون آواز، تہٕ سوزُن اکھ فرشتہ، تہٕ کوٚرُن اسہِ مصرہٕ منزٕ نیبر کٔرِتھ، تہٕ وُچھِتھ أسۍ چھِ کادیشس مَنٛز، یُس تُہٕندِس سرحدس مَنٛز اکھ شہر:\n17. بہٕ چُھس ژےٚ دُعا کران زِ أسۍ پٔکِو نہٕ کھہَو مٔنٛزۍ، یا انگور کِنۍ نیرِو، تہٕ نہ أسۍ کۄرَن ہُند آب چیٚو: أسۍ پَکہٕ بادشاہ سٕنزِ وتہِ پیٹھ، أسۍ پٔکِو نہٕ دٔچھنِس کُن تہٕ نہ کھوورِ کُن، یوٚت تام أسۍ تُہٕندِ سرحد عبور کٔرِو۔\n18.\\tتہٕ اَدومَن ووٚن أمِس زِ ژٕ گژھِ نہٕ میہ نِش نیرُن، نتہٕ بہٕ گژھہٕ ژےٚ تلوار ہٮ۪تھ نٮ۪بر۔\n19.\\tتہٕ بنی اسرٲیلِیو ووٚن أمِس زِ أسۍ پَکہٕ وتہِ کِنہِ پَکُن، تہٕ یێلہِ بہٕ تہٕ میٲنۍ چارو چُھہ تُہُند آب، تێلہِ کٔرٕ بہٕ اَمیُک معاوضہٕ: بہٕ کُنہِ تہِ\n20. تہٕ تٔمۍ ووٚن، ژے گژھ نہٕ اژُن۔ تہٕ ایڈوم آو أمِس خٕلاف واریہن لُکن ہیتھ تہٕ مضبوٗط اتھہٕ سٍتۍ۔\n21. یتھہ پاٹھۍ کٔر ادومن اسرٲیلِس پننہِ سرحدہ کِنۍ وتھ دِنس انکار۔\n22.\\tتہٕ بنی اسرائیل سٍتـ̡ سارِوٕے جمٲژ سٍتـ̡ گٔیہِ کادیش پى۪ٹھہٕ سفر تہٕ آیہِ ہور کِس پہاڑس کُن۔\n23.\\tتہٕ خداوند کٔر موسیٰ تہٕ ہارونس سٍتـ̡ کُنہِ\n24.\\tہارون یِیہِ پننِس لُکہٕ سٍتـ̡ جمع کرنہٕ، تکیازِ سُہ گژھِ نہٕ تتھ زمینس مَنٛز اژُن یُس میہ بنی اسرٲیلِس دِژمُت چُھ، کیازِ تۅہہ کٔر میریبہ کِس آبس پیٹھ میانہِ کلامٕچ بغاوت کٔرمٕژ۔ {لفظ: ہیب۔ ٲس}\n25.\\tہارون تہٕ الیعازر نِش نیچو تہٕ أنِو تِم ہور کِس پہاڑس پیٹھ۔\n26. تہٕ ہارون تٔمۍ سٕندِس پلو کٔڈِتھ تہٕ تٔمۍ سٕندِس نیچوِس الیعزرس پیٹھ لاگُن، تہٕ ہارون یِیہِ پننِس لُکہٕ سٍتـ̡ جمع کرنہٕ، تہٕ یِیہِ اَتہِ مرُن۔\n27. تہٕ موسىٰ کٔر خداوند سُند حُکُم، تہٕ تِم گٔیہِ سارِنٕے جمٲژ ہٕندِس نظرس منز ہور کِس پہاڑس مَنٛز۔\n28.\\tتہٕ موسىٰ کٔر ہارونس پنہٕ نِس پلو تہٕ تھووُن پننِس نیچوِس الیعزرس پیٹھ۔ تہٕ ہارون موٗد تتہِ پہاڑ کِس تھزرس پیٹھ: تہٕ موسیٰ تہٕ الیعزر آو پہاڑ پیٹھٕ بۄن۔\n29.\\tییلہ سارِوٕے جمٲژ وُچھ ہارون چُھ موٗدمُت، تِمو کٔر ہارونُس ترہن دۅہن ماتم تہٕ سارِنٕے اِسرٲیلِس سٍتـ̡ ۔","1. تہٕ {ییلہ} بادشاہ اراد کنعانی، یُس جنوبس منز روزان اوس، بوز زِ اسرائیل آو جاسوسن ہٕندِ وتہِ سٍتـ̡ ۔ تمہ پتہ لوٚڈ تم اسرائیلس خلاف تہ یمن منز کٔرِن کینہہ قٲد۔\n2.\\tتہٕ اسرٲیلَن کٔر خداوند سٍتـ̡ عہد تہٕ وونُن، یێلہِ ژے یێلہِ پٔزۍ پٲٹھـ̡ یِم لُکھ میٲنِس اتھس مَنٛز دِیُو، بہٕ کٔرٕ تِہٕندِس شہر پوٗرٕ پٲٹھـ̡ تباہ کرنہٕ۔\n3. تہٕ خداوند بوٗز اسرٲیلٕچ آواز تہٕ کٔرٕن کنعانی حوالہٕ۔ تہٕ تِمو کٔر تِم تہٕ تِہٕندِس شہر پوٗرٕ پٲٹھۍ تباہ تہٕ تٔمۍ تھووُن اتھ جایہِ ہُند ناو۔ {ہورمہ: یعنی سراسر تباہی}\n4.\\tتہٕ تِمو گٔیہِ کوہ ہور کِس وتہِ کِنۍ ادوم کِس سرزمینس اندۍ پکھۍ گٔیہِ، تہٕ لوکن ہُند روح گۆو وتہِ سٍتـ̡ واریاہ حوصلہ شکنی کرنہٕ۔ {حوصلہ شُد: یا، غمگین: ہیب۔ ژھوٚٹ}\n5. تہٕ لُکھ کٔر خدایس خلاف تہٕ موسیٰ سٕندِس خلاف کتھ کرنہٕ، تہٕ کیازِ چُھکھ اسہِ مصرہٕ منزٕ بیابانن مَنٛز مرنہٕ خٲطرٕ اننہٕ؟ تکیازِ {اتہِ} چُھ نہٕ کانہہ روٹی تہٕ نہ چُھ {چُھ} آب۔ تہٕ سانہِ روح چُھ اتھ ہلکہٕ روٹی سۭتۍ نفرت۔\n6.\\tتہٕ خداوند سوٗزۍ لُکن مَنٛز نار ناگ تہٕ تِمو لُکن ہٕندِس لُکن ہٕندِس لُکن ہٕندِس دَس۔ تہٕ اسرائیلٕکۍ واریاہ لوٗکھ سپٕدۍ مارٕ۔\n7. تَمہِ کِنۍ آو لُکھ موسیٰ نِش تہٕ وونُن، أسۍ چُھ گۅناہ کورمُت، تِکیازِ أسۍ چُھ خداوند سٕندِس خلاف تہٕ تۅہہِ خلاف کتھ کٔرمٕژ۔ خداوند کٔرِو دُعا زِ سُہ نِش نِش ناگ نِش دُعا کٔرِتھ۔ تہٕ موسىٰ کٔر لُکن ہٕندِ خٲطرٕ دُعا۔\n8.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ ژے اکھ نار ناگ تہٕ تھووُن أکِس کھمبَس پیٹھ، تہٕ یێلہِ سُہ دِنہٕ ییہِ سُہ زِندٕ روزُن۔\n9.\\tتہٕ موسیٰ بنوو پیتلُک ناگ تہٕ تھووُن أکِس کھمبَس پیٹھ، تہٕ یہِ سپُد زِ اگر کٲنٛسہِ ناگ کٲنٛسہِ انسانس دِژمُت آسہِ، ییلہ تٔمۍ پیتلُک ناگ وُچھ، سُہ اوس زندٕ۔\n10. تہٕ بنی اسرائیل دراو برونہہ کُن تہٕ اوبوتس مَنٛز دِژٕ۔\n11.\\tتہٕ تِمو دِژ اوبوت پیٹھٕ سفر تہٕ دِژ اِجیباریم کُن، بیابانس مَنٛز یُس موآب برونہہ کُن چھُ، آفتاب کھسنہٕ کُن۔ {اجیباریم: یا، اباریم کِس انبار}\n12.\\tاتہِ پیٹھہ ژٔلِتھ ژٔلِتھ وادی زرید۔\n13.\\tتتہِ کٔرِتھ ژٔلِتھ تِمو آرنون کِس دوٚیمس طرفہٕ یُس بیابانس مَنٛز {چُھ} یُس امورین ہٕندِس ساحلس منزٕ نیران چُھ: آرنون چُھہ موآب تہٕ امورین درمیان موآبُک سرحد۔\n14.\\tاَمہِ مۅکھٕ چُھ یہِ وَننہٕ آمُت زِ خداوند سٕندِس جنگہٕ کِس کتابہِ مَنٛز کیا کوٚر تٔمۍ بحرِ احمرس مَنٛز، تہٕ آرنون کِس نالہِ مَنٛز، {کیا...: یا، واہب سُفاہَس مَنٛز}\n15. تہٕ نالہٕ کِس نالہٕ سٍتـ̡ یُس آرس کِس مکانس تام وسان چُھ، تہٕ موآب کِس سرحدس پیٹھ واقع چُھ۔ {لیتھ: ہیب۔ لینیتھ}\n16.\\tتہٕ تتہِ گٔیہِ تِم بیٖرس کُن: سُہ کُور یُس خداوند موسیٰ سٍتـ̡ کتھ کٔرِتھ، لُکھ جمع کٔرِو تہٕ بہٕ دِیہٕ تِمن آب دِنہٕ۔\n17.\\tتمہِ پتہ گۆو اسرایلن یہ بٲتھ سپرنگ اپ، اے ویل۔ اتھ پیٹھ گیو: {بہار...: ہیب۔ Ascend} {گیون: یا، جواب}\n18.\\tشہزادو کٔر کۅرٕ، لُکن ہٕندِیو رئیسَو کھٔنِتھ کٔر یہِ قونوٗن دِنہٕ وٲلِس سٕندِس ہدایتس سٍتۍ، پَنٕنہِ لورٕ سٍتـ̡ کھٔنِتھ۔ تہٕ بیابان پیٹھٕ {تِم گٔیہِ} متانہٕ کُن:\n19.\\tتہٕ متانہٕ پیٹھہ نہالیئل تام: تہٕ نہالیئل پیٹھہ باموتھس تام:\n20.\\tتہٕ باموتھ پیٹھہٕ وادی منز، یعنی موآب کِس ملکس منز، پسگاہ کِس تینتٲلس تام، یُس یشیمون کُن نظر چُھ تھاوان۔ {ملک: ہیب۔ میدان} {پسگاہ: یا، پہاڑ} {جیشیمون: یا، بیابان}\n21. تہٕ اسرٲیلَن سوٗزۍ امورِین ہٕندِس بادشاہ سِحونَس نِش قاصد ، یہِ وَنُن زِ\n22.\\tبہٕ گٔژھِو نہٕ چانہِ زمینہٕ مٔنزۍ نیرُن: أسۍ گژھو نہٕ کھہَن مَنٛز، یا انگورن مَنٛز۔ أسۍ چِھہ نہٕ کۅرُک آب چیوان: {مگر} أسۍ پکان بادشاہ سٕنزِ {تھد} وتہِ پیٹھ، یوٚت تام أسۍ چانہِ سرحد نیبر نیرِو۔\n23.\\tتہٕ سیہون دِژ نہٕ اسرٲیلِس پنہٕ نِس سرحدٕ کِنۍ نیرُن، مگر سِحون کٔر پَنٕنـ̡ سٲری لُکھ جمع تہٕ درٛاو اِسرٲیلِس خلاف بیابانن مَنٛز۔\n24.\\tتہٕ اسرٲیلَن لوٚگ أمِس تلوار ہٕندِ کُنہِ کُنہِ سٍتـ̡ تہٕ کوٚرُن آرنون پؠٹھٕ یبوکَس تام، حتیٰ کہ عمون سٕندِس بُلِس تام تہٕ عمون سٕندِس بُلِس تام تہِ قبضہٕ کٔرِتھ، تکیازِ عمون سٕندِس بُلِس ہُند سرحد اوس مضبوط۔\n25.\\tتہٕ اسرائیلن کٔر یِم سارِنٕے شہرن پیٹھ قبضہٕ، تہٕ اسرٲیلن کٔر امورین ہٕندِس سارنٕے شہرن، ہیشبونس مَنٛز تہٕ تِمن ہٕندِس سارِنٕے گامن مَنٛز بسان۔ {گام: ہیب۔ کورِ}\n26.\\tہیشبون اوس سیہون شہر، یُس موآب کِس سٲبقہٕ بادشاہس خلاف جنگ اوس کورمُت، تہٕ تٔمۍ سٕنز سورے زمین نِش نِش نِیومُت، حتیٰ کہ آرنونس تام۔\n27.\\tاَمہِ مۄکھٕ چھِ یِم امثال وَننہٕ آمٕتۍ چھِ، یِم یِم حِشبون مَنٛز آو، سِہون شہر گژھہِ بَناوُن تہٕ تیار کرنہٕ یُن:\n28.\\tتکیازِ ہیشبون منزٕ چُھ نار نیران، سِہون شہرٕ پیٹھٕ چُھہ نار دِنہٕ آمُت، یێمہِ سٍتـ̡ چُھہ موآب کِس آرس تہٕ آرنون کِس تھدِ مقامن ہٕندِس مٲلکَس زٲلِتھ دِژمُت۔\n29.\\tہاے موآب! اے کیموش کِس لوکو، تۅہہ چُھکھ ختم گومُت، تٔمۍ دِژ پنٕنۍ نیچوۍ یِم ژلمت ٲسۍ، تہٕ تٔمۍ سٕنزِ کورِ دِژ امورین ہٕندِس بادشاہس سِہون سٕندِس قٲدس منٛز۔\n30. اسہِ چُھ تمن پیٹھ گولہٕ چلٲومُت۔ ہیشبون چُھ دیبون تام تہِ ختم گومُت، تہٕ اسہِ چھِ تِم نوفاہَس تام تہِ ضایع کٔرۍمٕتۍ، یُس مدیباہس تام واتان چھُ۔\n31. یِتھٕ پٲٹھۍ اوس اسرٲیل امورین ہٕندِس سرزمینس مَنٛز بسان۔\n32.\\tتہٕ موسىٰ سوٗز جازر نِش جاسوسی کرنہٕ خٲطرٕ، تہٕ تِمو کٔرِکھ اَمہِ ہٕندِس گامس پیٹھ قبضہٕ، تہٕ کٔرِکھ امورِی یِم اَتہِ ٲسۍ۔\n33.\\tتہٕ تِم گٔیہِ بشان کِس وتہِ کِنۍ ہیوٚت، تہٕ اوگ بشانُک بادشاہ دراو تِمن خٕلاف، سُہ تہٕ تٔمۍ سٕندِس سارِنٕے لُکھ درٛاے کِس جنگس منز۔\n34. تہٕ خداوند ووٚن موسیٰ سٕندِس سٍتـ̡ خوفزدہ گژھ نہٕ، کیازِ مے چُھس سُہ تہٕ تٔمۍ سٕندِس سارِنٕے لُکہٕ تہٕ تٔمۍ سٕندِس سرزمینس تێہٕندِس اتھس مَنٛز دِژمُت۔ تہٕ تۅہہ کٔرِو أمِس سٍتـ̡ یُس امورین ہٕندِس بادشاہس سِہون سٍتـ̡ کورمُت اوس، یُس ہیشبونس مَنٛز روزان اوس۔\n35.\\tیِمو دِژ أمِس تہٕ تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس سارِنٕے لُکہٕ سٍتـ̡ مارٕ، یوٚت تام نہٕ أمِس زِندٕ روٗد تہٕ تِمن ہٕندِس زمینس پیٹھ قبضہ کرنہٕ۔","1.\\tتہٕ بنی اسرائیل دراو برونہہ کُن، تہٕ دراو موآب کِس مٲدانس مَنٛز یَتھ طرفہٕ اردن {by} یریحا۔\n2.\\tتہٕ زیپور سٕندِس نیچوِس بالک وُچھ سُہ سورُے یُس اسرایلن امورین سٍتـ̡ کورمُت۔\n3. تہٕ موآب اوس لُکن سٍتـ̡ کھوژان، تکیازِ تِم ٲسۍ واریاہ تہٕ موآب اوس بنی اسرٲیِل سٍتـ̡ پریشان۔\n4.\\tتہٕ موآبن ووٚن مدیان کین بزرگن زِ وۅنۍ کرِ یہ کمپنی اسہِ اندۍ پکھۍ سارِنٕے سارِنٕے سٍتـ̡ یِتھٕ پٲٹھۍ داند کھہہٕ کِس گاسہٕ ژٹان۔ تہٕ زیپور سُند نیچو بالک اوس تمہ وقتہٕ موآبین ہُند بادشاہ۔\n5.\\tتِمو سوُزُن بُعور سٕندِس نیچوِس بَلام نِش یُس تٔمۍ سٕندِس لُکہٕ کِس بُلکہٕ سٕندِس سرزمینس نِش دٔرِتھ بُلاونہٕ خٲطرٕ، یُس تٔمِس بُلاونہٕ خٲطرٕ وُچھِتھ وُچھِتھ چُھہ اَکھ لُکھ دِنہٕ آمُت، وُچھِو تِم چھِ زمینہِ ہٕندِس بُتھِس ؤلِتھ تہٕ تِم چھِ میانہِ خلاف روزان: {بُتھ: حب۔ أچھ}\n6. یێمہِ وِزِ یێلہِ بہٕ ژے دُعا کٔرِتھ دُعا کٔرِتھ یِمن لُکن ہٕندِس لُکَس سٍتـ̡ دُعا ک تکیازِ تِم چھِ میانہِ خٲطرٕ واریاہ طاقتور: شاید بہٕ کٔرِتھ بہٕ غالب، {یُتھ} أسۍ تِمن مارٕ دِتھ، تہٕ {یُتھ} بہٕ کٔرِتھ تِم زمینہٕ نِش کڈِتھ، کیازِ بہٕ چھُس یُس تہٕ یُس ژے دِوان چھُ، سُہ چھُ بُلطنت کرنہٕ آمُت۔\n7. تہٕ موآب ہٕکۍ بزرگ تہٕ مدیانٕکۍ بزرگ دراو خدائی ہٕندِس انعامس ہٕندِس اتھس منز ہٮ۪تھ۔ تہٕ تِم آیہِ بَلامَس نِش، تہٕ تٔمِس کٔرِکھ بَلکٕنۍ کَلام۔\n8.\\tتہٕ تٔمۍ ووٚن تِمَن زِ از رٲژ یَتہِ روزُن، تہٕ بہٕ اَنِہ ژےٚ دُبارٕ کَتھ، یِتھٕ کٔنۍ خداوند میانہِ سٍتـ̡ کتھ کرِ، تہٕ موآبٕکۍ شہزادٕ روزِ بَلعمَس سٍتـ̡ ۔\n9.\\tتہٕ خدا آو بَلامَس نِش تہٕ وونُن، یِم کُس انسان چھِو ژےٚ سٍتـ̡ ؟\n10. تہٕ بعلمن ووٚن خدایس زِپور سُند نیچو، موآبُک بادشاہ، چُھہ میہ نِش سوزمُت، {ونان}۔\n11.\\tوُچھِو اَکھ لُکھ یُس مِصرہٕ منزٕ نیران چُھ، یُس زمینہِ ہُند بُتھ ؤلِتھ چھُ، یُس وُنہِ تہِ یِمن ہٕندِس بُتھِس سٍتـ̡ ؤلِتھ چُھہ، یێمہِ سٍتـ̡ دِیُن دُعا دِنہٕ۔ شاید بہٕ ہیوٚک تمن پیٹھ قابو کٔرتھ، تہٕ تمن کٔڑتھ کٔرتھ۔ {بہٕ کرُن...: ہیب۔ بہٕ روزٕ تس خلاف لڑایہِ منز غالب}\n12. تہٕ خداین ووٚن بَلامَس زِ ژٕ گژھ نہٕ تِمن سٍتـ̡ نیرُن۔ تُہۍ کٔرِو نہٕ لُکن بد دُعا کٔرِتھ، تِکیازِ تِم چھِ بابرکت ۔\n13. تہٕ بلعام ووٚتھ صبحٲے تہٕ ووٚنُن بلک کِس شہزادن تہٕ وونُن پنہٕ نِس زمینس منز، کیازِ خداوند چُھ مےٚ پانس سٍتـ̡ گژھنٕچ اجازت دِنہٕ نِش انکار کران۔\n14.\\tتہٕ موآبٕکۍ شہزادٕ ووٚتھ، تہٕ تِم گٔیہِ بلکس کُن تہٕ وونُن، بلعام چُھ اسہِ سٍتـ̡ یِنہٕ نِش انکار۔\n15.\\tتہٕ بالاک سوٗزۍ بییہِ اکہِ لٹہِ شہزادہٕ، یِمو کھۅتہٕ زیادٕ تہٕ عزتدار۔\n16.\\tتہٕ تِم آیہِ بَلامس نِش، تہٕ وونُن زِپور سُند نیچو بالک، یِتھٕ پٲٹھۍ چُھس زِپور سُند نیچو بلک ونان، بہٕ چُھس ژے رُکٲوِتھ میانہِ نِش یِنہٕ نِش: {پۯاو...: ہیب۔ تۅہہ گژھ نہ رُکاوٹ وغیرہ۔\n17.\\tکیازِ بہٕ کٔرٕ ژے واریاہ عزت، تہٕ بہٕ کٔرٕ یُس تہٕ ژے مےٚ وَنُن تہٕ بہٕ کٔرٕ یُس تہٕ ژے مےٚ ؤنِتھ تہٕ بہٕ کٔرٕ یِمن لوکن پیٹھ لعنت۔\n18.\\tتہٕ بَلعمن دِیُت جواب تہٕ وونُن بالاک سٕندِس خادمن یێلہِ بہٕ یێلہِ بہٕ ہیوٚک نہٕ خدایہ سٕندِس کلامَس سٍتـ̡ کم یا زیادٕ کٔرِتھ۔\n19. تێمہِ کِنۍ چُھس بہٕ ژے دُعا کران زِ ژے تہِ یێلہِ رٲژ تہِ روزُن، یُتھ بہٕ زانہٕ زِ خداوند کیا کرِ میہ بییہ تہِ۔\n20.\\tتہٕ خدا آو رٲژ بَلامس نِش، تہٕ وونُن أمِس زِ اگر یِم نفر تۅہہِ بُلاونہٕ یِن، تھوٚد تھوٚد تہٕ تِمن سٍتـ̡ گژھُن۔ مگر توتہِ یُس لفظ بہٕ ژے وَنُن، سُہ کرِ ژے کرُن۔\n21.\\tتہٕ بلعام ووٚتھ صبحٲے تہٕ لوٚگ موآب کِس شہزادن سٍتـ̡ ۔\n22. تہٕ خدایہِ سُند غصہٕ گۆو تِکیازِ سُہ گۆو تہٕ خداوند سُند فرشتہ اوس أمِس خٕلاف أکِس مُخٲلِفس سٕندِس وتہِ رُکاوٹ۔ وۅنۍ اوس سہ پننہِ کھورِ پیٹھ سوار تہ تسندۍ زہ نوکر ٲسۍ أمس سیتۍ آسان۔\n23. تہٕ گَرٕ وُچھ خداوند سُند فرشتہ وتہِ منز کھڑا تہٕ تٔمۍ سٕنز تلوار ٲس اتھس منز کٔڈِتھ، تہٕ گَرٕ پھیُر وتہٕ نِش تہٕ گٔیہِ کھاہس منز۔\n24. مگر خداوند سُند فرشتہ اوس انگورن ہٕنزِ وتہِ پیٹھ کھڑا، اَتھ طرفہٕ اکھ دیوار تہٕ اَتھ طرفہٕ اکھ دیوار۔\n25.\\tتہٕ ییلہ گَرِ خداوند سُند فرشتہ وُچھ، تٔمۍ لوٚگ دیوارس کُن تہٕ لوٚگُن بلام سُند کھوٚر دیوارس سٍتـ̡ تہٕ دِژُن أمِس دُبارٕ مار۔\n26.\\tتہٕ خداوند سُند فرشتہ ووت برونہہ کُن، تہٕ کھڑا أکِس تنگ جایہ، ییتہِ نہٕ دٔچھنِس اتھس کُن تہٕ کھوورِ کُن پھیرنٕچ کانہہ وتھ ٲس۔\n27.\\tتہٕ ییلہ گَرَن خداوند سُند فرشتہٕ وُچھ، سۅ پیوٚو بَلامَس تَل تہٕ بَلام سُند شَرارتہٕ دِژُن تہٕ تٔمۍ دِژ گَرٕ سٕندِس لٔرِس سٍتـ̡ لٔگِتھ۔\n28.\\tتہٕ خداوند کٔر گَرٕ سُند بوش تہٕ تٔمۍ ووٚن بَلامَس زِ مے کیا چُھس ژے کٔرِتھ یِم تریہ لٹہِ مارٕ دِژمٕتۍ۔\n29.\\tتہٕ بَعلمن ووٚن گَرَس زِ تِکیازِ ژے چُھس طنز کٔرِمُت: کاش ہا میٲنِس اتھس منز تلوار آسہِ، تکیازِ وُنۍ کٔرٕ بہٕ ژے مٲرِتھ۔\n30.\\tتہٕ گَرَن ووٚن بَلامَس زِ {بہ} چھُس نہٕ تُہٕندِس گَرَس سٍتـ̡ یَتھ پیٹھ ژے از تام سوارِ ٲسمٕژ۔ بہٕ اوسُس نہٕ ژےٚ کُنہِ تہِ یۅہے کٔرِتھ؟ تہٕ تٔمۍ ووٚن، نہٕ۔ {on...: Heb. کُس چُھ میہ پیٹھ سوار گومُت} {تنہٕ پیٹھ...: یا، تنہٕ پیٹھہٕ چُھ ژے واسٹ وغیرہ}\n31. اَمہِ پَتہٕ کٔر خداوند سٕنزِ أچھ تہٕ وُچھ خداوند سُند فرشتہٕ وتہِ وتہِ کھڑا تہٕ تٔمۍ سٕنز تلوار ٲس اتھس مَنٛز لٔگِتھ، تہٕ تٔمۍ کٔر کلہٕ بۄن تہٕ پیوٚو بُتھِس پیٹھ۔ {پیوٚو...: یا، کٔر پان نمُن}\n32.\\tتہٕ خداوند سٕندِ فرشتن ووٚن أمِس زِ ژے کیازِ دِژ یِم تریہ لٹہِ پنہٕ نِس گٔرِس مارٕ؟ وچھ بہٕ دراو ژے مقابلہٕ کرنہٕ خٲطرٕ، کیازِ {تُہٕن} وتھ چِھ میانہِ برونہہ کُن گڑبڑ: {to...: Heb. تۅہہِ ہُند مُخٲلِف بَنُن}\n33.\\tتہٕ گَرَن وُچھ میہ نِش یِم تریہ لٹہِ پھیُر: یوٚت تام نہ سۅ میہ نِش پھیُرِ، یٔژ وۅنۍ تہِ میہ ژے مٲرِتھ تہٕ بچٲومٕژ سۅ زِندٕ۔\n34. تہٕ بعلمن ووٚن خداوند سٕندِس فرشتس سٍتـ̡ ، مے چُھہ گۅنہہ کورمُت۔ تکیازِ میہ ٲس نہ پتاہ زِ ژیہ چھکھ میانہِ خلاف وتہِ منز کھڑا گژھان: لہذا اگر یہ ژیہ ناراض آسہِ، بہٕ واپس۔ {ناپسندید...: ہیب۔ پننہ نظرن منز گژھ بد کار}\n35.\\tتہٕ خداوند سٕندِ فرشتن ووٚن بَلامَس زِ گژھ انسانَن سٍتـ̡ گژھُن، مگر صرف سُہ کلام یُس بہٕ ژے سٍتـ̡ کتھ کرِ، یُس ژے کتھ کرِ۔ تَوَے گٔیہِ بَلام بالاک کِس شہزادن سٍتـ̡ ۔\n36.\\tتہٕ ییلہ بلکن بوٗز زِ بلعام آو آمُت، سُہ دراو أمِس مِلنہٕ خٲطرٕ موآب کِس أکِس شہرس منز، یُس ارنون کِس سرحدس پیٹھ چھُ، یُس بٔٹھِس بٹھس پیٹھ چھُ۔\n37.\\tتہٕ بلکن ووٚن بَلامَس زِ میہ اوسُکھ نہٕ ژےٚ بُلاونہٕ خٲطرٕ سوزمُت؟ ژیہ کیازِ آو نہٕ میہ نِش؟ کیا بہٕ چھُس نہٕ پٔزۍ پٲٹھۍ ژےٚ عزت دِنس قٲبل؟\n38.\\tتہٕ بعلمن ووٚن بلکَس زِ بہٕ چُھس ژے نِش آمُت، کیا بہٕ چُھس وۅنۍ کانہہ تہِ کتھ وننُک کانہہ اختیار تھاوان؟ سُہ لفظ یُس خدایہ میٲنس ٲسس منز تراوان چُھ، سُہ چُھس بہٕ بولان۔\n39.\\tتہٕ بلعام گوٚو بلکس سٍتۍ، تہٕ تِم آیہ کرجاتھوزوت کُن۔ {کرجاتھوزوتھ: یا، سڑکن ہند شہر}\n40.\\tتہٕ بلکن کٔر بیل تہٕ کۅکر پیش تہٕ سوٗزُن بلعام تہٕ تِمن شہزادن نِش یِم أمِس سٍتـ̡ ٲسۍ۔\n41.\\tتہٕ پَگہہ سپُد یہِ زِ بلکن نِش بعل کِس تھزرس پیٹھ تہٕ أنِن سُہ بعل کِس تھزرس مَنٛز، یُتھ تتہِ سُہ لُکن ہُند سارِوٕے کھۄتہٕ زیادٕ حصہٕ وُچھِ۔","1. تہٕ بعلمن ووٚن بالکَس یَتہِ سَتھ قربان گاہ بناوُن، تہٕ مےٚ کٔرِن یَتہِ سَتھ بیل تہٕ سَتھ مینڈٕ تیار۔\n2.\\tتہٕ بلکن کٔر یُتھ بعلمن کتھ کٔرمٕژ۔ تہٕ بلک تہٕ بلعام کٔر پرٮ۪تھ کُنہِ قربان گاہس پیٹھ اکھ بیل تہٕ اکھ مینڈٕ پیش۔\n3. تہٕ بَعلمن ووٚن بلکَس زِ پنہٕ نِس زٲلِتھ نذرانہ سٍتـ̡ کھڑا روزُن، تہٕ بہٕ گژھہٕ بہٕ نیرُن: شاید خداوند ییہِ میہ سمکھنہٕ خٲطرٕ، تہٕ یُس تہِ سُہ مےٚ ہٲوِتھ تہٕ بہٕ وَنُن بہٕ ژے وَنُن۔ تہٕ سُہ گوٚو أکِس تھدِ جایہِ پیٹھ۔ {کُنہِ کُنہِ...: یا، کُنہِ}\n4.\\tتہٕ خدایہ سمکھیوو بلام: تہٕ تٔمۍ ووٚن أمِس زِ مے چھِ ستھ قربان گاہ تیار کٔرمٕژ، تہٕ مے چُھس پرٮ۪تھ أکِس قربان گاہس پیٹھ اکھ بیل تہٕ اکھ مینڈٕ پیش کورمُت۔\n5.\\tتہٕ خداوند تھوو بلعام سٕندِس ٲسس منز اکھ لفظ، تہٕ وونُن، بالکس کُن واپس، تہٕ یِتھٕ پٲٹھـ̡ کٔرِو کتھ کرنہٕ۔\n6.\\tتہٕ سُہ آو أمِس نِش واپس، تہٕ سُہ اوس سُہ تہٕ موآب کین سارِنٕے شہزادن ہٕندِس دزنہٕ آمٕژ قربانی سٍتـ̡ کھڑا ۔\n7.\\tتہٕ تٔمۍ تُل پنُن تمثیل تہٕ وونُن، موآبُک بادشاہ بالک چُھ مے مشرق کِس پہاڑو منزٕ آرام پیٹھٕ أنِمُت، {وونُن}، یعقوب کٔرِو مےٚ لعنت، تہٕ آ اسرٲیلِچ مخالفت کرُن۔\n8. بہٕ کِتھ کٔنۍ کرٕ بد دعا یٔمِس نہٕ خداین دِژمُت آسہِ۔ نتہٕ بہٕ کِتھ کٔنۍ کٔرٕ انکار کٔرِتھ، {یٔمِس} خداوند چُھ نہٕ نافرمانی کٔرمٕژ؟\n9.\\tکیازِ پتھرِ پیٹھٕ چُھس بہٕ سُہ وُچھان، تہٕ بالو پیٹھٕ چُھس بہٕ سُہ وُچھان: لوکھ روزن کُنی زُن، تہٕ قومن مَنٛز گژھِ نہٕ شمار کرنہٕ۔\n10.\\tیعقوب سٕنزِ گردِ تہٕ اسرٲیلِکِس ژوٗرِمِس حصُک تعداد کُس ہیکہِ گٔنزِتھ؟ میہ گژھہِ نیک سُند مرُن، تہٕ میون ٲخری انجام گژھہِ تمۍ سٕندِ پٲٹھۍ! {میں: ہیب۔ میون روح، یا میٲنۍ زندگی}\n11.\\tتہٕ بلکن ووٚن بلامس زِ ژے کیا کوٚر میہ سٍتۍ؟ میہ نیوو ژے پننین دشمنن پیٹھ لعنت، تہٕ وچھ ژے کٔر تمن سراسر برکت۔\n12. تہٕ تٔمۍ دیُت جواب تہٕ وونُن، یُس خداوند میٲنس ٲسس منٛز تھوومُت چُھ، کیا بہٕ پزٕ نہٕ یہٕ کتھ کرنہٕ خٲطرٕ توجہ دِنہٕ؟\n13.\\tتہٕ بلکن ووٚن أمِس زِ آو، بہٕ چُھس ژے پانس سٍتـ̡ بییِس جایہ دُعا کٔرِتھ، یێلہِ تہٕ تِم وُچھِو نہٕ تِمن سارِنٕے وُچھن، تہٕ تتہِ کٔرِکھ میہ تِمن ہُند لعنت۔\n14.\\tتہٕ سُہ أنِن زوفیم کِس کھاہس منز، پسگاہ کِس تینتٲلس پیٹھ، تہٕ بنٲوِن سَتھ قربان گاہ، تہٕ دِتُن پرٮ۪تھ أکِس قربان گاہس پیٹھ اکھ بیل تہٕ اکھ مینڈٕ پیش۔ {پِسگاہ: یا، بال}\n15.\\tتہٕ تٔمۍ ووٚن بالاکَس زِ یێلہِ روزُس پننہِ دزنہٕ نذرانہ سٍتـ̡ کھڑا روزُن، یێلہِ بہٕ {خدا} سٍتـ̡ مِلان۔\n16.\\tتہٕ خداوند سمکھیوو بَلامَس مُتلِق تہٕ تھووُن أمِس ٲسِس مَنٛز اکھ لفظ تہٕ وونُن، دُبارٕ گژھ بالکَس نِش، تہٕ وَنُن یِتھٕ پٲٹھۍ۔\n17.\\tتہٕ ییلہ سُہ أمِس نِش آو، وُچھ سُہ پنہٕ نِس زٲلِتھ نذرانہ تہٕ موآبٕکۍ شہزادٕ أمِس سٍتـ̡ کھڑا ۔ تہٕ بلکن ووٚن أمِس زِ خداوند کیا چُھ کتھ کٔرمٕژ۔\n18.\\tتہٕ تٔمۍ تُل پنُن تمثیل تہٕ وونُن، ووٚتھ، بالک، تہٕ بوزو۔ میہ بوز زِپور سُند نیچو:\n19. خدا چُھ نہٕ انسان ، زِ سُہ گژھہِ اپُز۔ نہ انسان سُند نیچو، زِ سُہ پزِ توبہ کرُن: کیا تٔمۍ ووٚنمُت، تہٕ کیا سُہ کرُن نہٕ؟ یا کیا تٔمۍ کٔر بول، تہٕ کیا سُہ کرٕ نہٕ اصل؟\n20.\\tوُچھو، مے چُھہ برکت دِنُک {حکم} حٲصل گومُت: تہٕ تٔمۍ چُھ برکت دِژمٕژ۔ تہٕ بہٕ ہیوٚک نہٕ یہِ واپس کٔرِتھ۔\n21. تٔمۍ وُچھ نہٕ یعقوبس مَنٛز بدکاری وُچھمٕژ، تہٕ نہ چُھ تٔمِس سٍتـ̡ اسرٲیلِس مَنٛز بدکاری وُچھمٕژ: خداوند تٔمِس سٍتـ̡ چُھہ تٔمِس سٍتـ̡ تہٕ یێمِس مَنٛز چُھہ بادشاہ سُند کرٛٮ۪کہٕ تہٕ چُھہ یێمِس مَنٛز چُھہ کُنہِ بادشاہ سُند کرٛٮ۪کہٕ وُچھمُت۔\n22. خداین کٔر تِم مصرہٕ منزٕ نیبر۔ أمِس چھُ یِتھٕ پٲٹھۍ زِ یہِ چھُ أکِس یونیکورن ہٕنٛز طاقت۔\n23.\\tیعقوب سٍتـ̡ چُھہ نہٕ کانہہ جادو تہٕ نہ چُھہ اسرٲیلِس سٍتـ̡ کُنہِ تہِ خدایہِ سٍتـ̡ وَننہٕ آمُت، یێمہِ وقتہٕ یعقوب تہٕ اسرٲیلِس مُتلق ییہِ وننہٕ یُن، خداین کیا چُھ کورمُت! {خلاف: یا، منز}\n24.\\tوُچھِو لُکھ بٔڈِس سٕہہ سٕندِ پٲٹھۍ، تہٕ پَنُن پان تُلِتھ یُس نہٕ شِکارس کھٮ۪نہٕ تہٕ مارنہٕ آمُت سُند خوُن چیٚنہٕ۔\n25.\\tتہٕ بلکن ووٚن بَلامَس زِ تِمن کٔرِن نہٕ یِمن بد دعا تہٕ نہ کرُن تِمن دُعا دِنہٕ۔\n26.\\tمگر بعلمن دیُت جواب تہٕ وونُن بالکَس زِ میہ ووٚن نہٕ ژے یُس خداوند کتھ کران چُھ، یُس میہ کرُن پزِ کرُن؟\n27.\\tتہٕ بلکن ووٚن بَلامَس یِن، یِمو تہٕ بہٕ چھُس ژےٚ دُعا کٔرِتھ تہٕ بہٕ اَننہٕ ژےٚ بییِس جایہ۔ شاید یہ خدایہ خوش کرِ زِ ژے کرِ میہ تتہِ پیٹھہ تمن پیٹھ لعنت۔\n28.\\tتہٕ بلق اوٚن بلعام پیور کِس تھزرس پیٹھ، یُس یشیمونس کُن وچھان چھُ۔\n29.\\tتہٕ بعلمن ووٚن بلکَس یَتہِ سَتھ قربان گاہ بناوُن، تہٕ یَتہِ کٔرِکھ سَتھ بیل تہٕ سَتھ مینڈٕ تیار۔\n30.\\tتہٕ بلکن کٔر یُتھ بلعام ووٚنمُت اوس تہٕ دِتُن پرٮ۪تھ کُنہِ قربان گاہس پیٹھ اکھ بیل تہٕ اکھ مینڈٕ پیش۔","1. تہٕ ییلہ بعلمن وُچھ زِ خداوند چُھ اسرٲیلِس برکت دِنہٕ خٲطرٕ خۅش گژھان، سُہ گۆو نہٕ باقٕے وقتن ہٕندۍ پٲٹھۍسُہ جادو ژھارنہٕ خٲطرٕ، مگر تٔمۍ کٔر پَنُن بُتھ بیابانس کُن۔ {ژھانڈنہٕ خٲطرٕ...: ہیب۔ میٹنگہِ منز}\n2.\\tتہٕ بعلمن کٔر أچھ تُل، تہٕ وُچھ اسرٲیلِس تہندِس قبیلہٕ مطٲبق روزان۔ تہٕ خدایہ سُند روح آو تس پیٹھ۔\n3.\\tتہٕ تٔمۍ تُل پنُن تمثیل تہٕ وونُن، بؤر سٕندِ نیچو بلعام چُھ ووٚنمُت، تہٕ یٔمۍ سٕنزِ أچھ یلہٕ چھِ، تٔمۍ ووٚن: {کُس...: حب۔ ییٚمۍ سٕنٛز أچھ ٲس بنٛد کٔرمٕژ، مگر وۄنۍ ٲس کھولمٕژ}\n4.\\tتٔمۍ چُھ ووٚنمُت، یُس خدایہ سُند کلام بوزمُت، یُس قادر مطلق سُند وژن وُچھمُت، مگر أچھ یلہٕ کٔرِتھ:\n5.\\tاے یعقوب، اے اسرائیل، چانہِ خیمہ کوتاہ اصل چُھہ!\n6.\\tیِتھٕ پٲٹھـ̡ وادی چِھہ پھٔہلِتھ، دریاو کِس بٔٹھِس سٍتـ̡ باغن ہٕندۍ پٲٹھۍ، یِمن ہٕندِس کُلـ̡ ہٕندِس کُلـ̡ ہٕندِس پٲٹھـ̡ یِم خداوند ہن لگٲومٕتۍ، {تہٕ} آبس سٍتـ̡ دیودار کُلـ̡ پٲٹھۍ۔\n7.\\tسُہ گژھہِ پنہٕ نِس بالٹیو منزٕ آب تراوُن، تہٕ تٔمۍ سُند بادشاہ گژھہِ آگگس کھۅتہٕ تھوٚد تہٕ تٔمۍ سٕنز سلطنت گژھہِ تھزر۔\n8.\\tخدا کٔر سُہ مصرہٕ منزٕ نیبر۔ أمِس چُھ أکِس یونیکورن سٕنز طاقت ہٕندۍ پٲٹھۍ: سُہ کھیٚیہِ قومن پنٕنۍ دُشمن، تہٕ تِہٕنزِ أڈجہِ پھُٹراوِ، تہٕ تِمن ہٕندِس تیرو سٍتۍ ژٔٹِتھ ژٔٹِتھ۔\n9.\\tسُہ لوٚگ سٕہہ سٕندِس پٲٹھۍ، تہٕ بٔڈِس شیرس سٍتـ̡ کُس کرِ ہلچل دِنہٕ۔ سُہ چُھ سُہ یُس تۅہہِ برکت دِوان چُھ، تہٕ سُہ چُھ لعنت دِنہٕ آمُت۔\n10.\\tتہٕ بلک سُند شَرارتہٕ دِژ بَلامَس سٍتـ̡ تہٕ تٔمۍ کٔر اَتھٕ رٔلِتھ تہٕ بَلکن ووٚن بَلامَس زِ مے چُھس ژے پننین دُشمن بد دُعا دِنہٕ خٲطرٕ بُلاونہٕ آمُت، تہٕ وُچھِو ژے یِمن تریہ لٹہِ برکت دِژمٕژ۔\n11.\\tتێلہِ ژٔلِتھ مگر، خداوند چُھ ژے عزتہٕ نِش پتھ تھوومُت۔\n12. تہٕ بَلَمن ووٚن بَلَکَس زِ مے کٔر نہٕ تُہٕندٮ۪ن رسولن سٍتـ̡ تہِ یِم ژے مے سوزمٕژ چھِ،\n13. یێلہِ بَلَق پَنُن گرٕ رۄپہٕ تہٕ سۄنہٕ سٍتـ̡ بٔرِتھ دِیہِ، بہٕ ہیوٚک نہٕ خداوند سٕندِس حُکمس نیبر گژھِتھ، تہٕ کُنہِ تہِ کٔرِتھ تہٕ کُنہِ تہِ کٔرِتھ پننہِ ذہنس سٍتـ̡ خیر یا بُرٕ کٔرِتھ۔ {مگر}خداوند کیا چُھ ونان، یُس بہٕ کَرٕ کَرٕن؟\n14. تہٕ وُچھ، بہٕ چُھس پننین لوکن نِش گژھان: یِمو {لہذا، تہٕ} بہٕ کٔرٕ ژے یہ اعلان زِ یہِ لوٗکھ کیا کرِ پتمین دۅہن منز تہندین لوکن سٍتـ̡ کرنہٕ۔\n15.\\tتہٕ تٔمۍ تُل پنُن تمثیل تہٕ وونُن، بیٖر سٕندِ نیچو بلعام چُھ ووٚنمُت، تہٕ یٔمۍ سٕنزِ أچھ یلہٕ چِھ، تٔمۍ ووٚن :\n16.\\tتٔمۍ چُھ ووٚنمُت، یُس خدایہ سُند کلام بوزمُت چُھ، تہٕ خدایہ سُند علم زانان چُھ، {یُس} خدایہ سُند وژن وُچھمُت، یُس وُچھمُت چُھ، مگر تٔمۍ سٕنزِ أچھ یلہٕ کٔرِتھ:\n17. بہٕ وُچھمُت سُہ مگر وُنہِ نہٕ: بہٕ وُچھِتھ سُہ مگر نزدیک نہٕ: یعقوب سٕندِ سٍتـ̡ یێلہِ یعقوب سٍتـ̡ اکھ تارٕ نیرِ، تہٕ اسرٲیلـ̡ منزٕ نیرِ اکھ عصمت تہٕ موآب کِس کونس پیٹھ مارہِ تہٕ شیث سٕندِس سارِنٕے بُرِ تباہ کرِ۔ {smite...: یا، مارو شہزادن ہٕندِ}\n18.\\tتہٕ ادوم آسہِ اکھ قبضہ، سیر تہِ آسہِ پننین دشمنن ہٕندِ خٲطرٕ قبضہ۔ تہٕ اسرٲیل کرِ بہادری سٍتـ̡ ۔\n19.\\tیعقوب سٍتـ̡ یُس بادشاہی آسہِ، تہٕ یُس شہرس منز باقی، سُہ کرِ تباہ کرنہٕ۔\n20.\\tییلہ أمِس عمالیقس کُن نظر دِژ، تٔمۍ تُل پنُن تمثیل، تہٕ وونُن، عمالیق اوس قومہٕ مَنٛز گۄڈنیُک۔ مگر تٔمۍ سُند ٲخری انجام گژھہِ یہ زِ سُہ گژھہِ ہمیشہٕ خٲطرٕ فنا سپدُن۔ {قومن: تم قومن یمو اسرائیلس خلاف جنگ کٔر} {یہ...: یا تباہی تام تہِ}\n21.\\tتہٕ تٔمۍ کٔر کینیٹس کُن نظر، تہٕ تُلُن پنُن تمثیل، تہٕ وونُن، تُہند روزن جاے چھُ مضبوط، تہٕ ژے تھووُن پنُن گرٕ أکِس کَنہِ پتھرس منٛز۔\n22.\\tبہر حال گژھہِ کینِٹ ضایع سپدُن، یوٚت تام نہ آشور ژیہ قٲد کرِ۔ {کینائٹ: ہیب۔ کاین} {یوتام ...: یا، کیاہ تام روزِ آشور ژے قٲد کٔرِتھ}\n23.\\tتہٕ تٔمۍ تُل پنُن تمثیل تہٕ وونُن، ہا، یێلہِ خدایہ یہِ کرِ تیلہِ کُس زِندٕ روزِ!\n24. تہٕ جہازٕ یِن چِٹِم کِس بٹھہٕ پیٹھٕ یِن، تہٕ اشورس مُتٲثِر کرِ، تہٕ سُہ تہِ گژھہِ ہمیشہٕ خٲطرٕ مارنہٕ۔\n25.\\tتہٕ بَلام ووٚتھ تہٕ گٔیہِ پَنٕنہِ جایہِ واپس۔","1.\\tتہٕ اسرٲیلَن بٔرِتھ شِتِمَس مَنٛز روزُن، تہٕ لُکھ لُکھ موآب سٕنزِ کورِ سٍتـ̡ بدکاری کرٕنـ̡ ۔\n2. تہٕ تِمو بُلٲوۍ لُکن پننین دیوتاہن ہٕنزِ قربانی خٲطرٕ، تہٕ لوکو کھیوٚو تہٕ کٔرٕکھ پننین دیوتاہن برونہہ کُن نمُن۔\n3. تہٕ اسرٲیلِس رٔلِتھ بعلپیورس سٍتـ̡ تہٕ خداوند سُند غصہٕ گۆو اسرٲیلِس سٍتـ̡ دِنہٕ۔\n4. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ لُکن ہٕندِس سارِنٕے کلہٕ نِتھ تہٕ یِم رٔٹِو خداوند سٕندِس برونہہ کُن آفتابس سٍتـ̡ پھٲنسـ̡ یُتھ خداوند سُند شدید غضب ییہِ اسرٲیلِس نِش پھیرنہٕ۔\n5. تہٕ موسىٰ ووٚن اسرٲیلِکۍ قاضن زِ تٔمۍ سٕندِس سارِنٕے نفرس مارِو یُس بعلپیورس سٍتـ̡ رٔلِتھ اوس۔\n6.\\tتہٕ وُچھِتھ آو اِسرٲیلِیو منزٕ اَکھ بٲے تہٕ موسیٰ سٕندِس نظرس منز تہٕ بنی اسرٲیلِچ سارِنٕے جمٲژ ہٕندِس نظرس مَنٛز، یِم جمٲژ ہٕندِس خیمہ کِس دروازس برونہہ کُن روان ٲسۍ۔\n7. تہٕ ییلہ ہارون پادٕرۍ سٕندِس نیچوِس الیعازر سٕندِس نیچوِس فینہاسن وُچھ، سُہ ووٚتھ جمٲژ منزٕ تہٕ رٔٹِتھ رٔٹِتھ اکھ نیزہ اتھس منز۔\n8.\\tتہٕ سُہ ووت اسرٲیلِس مردس پَتہٕ خیمہ مَنٛز، تہٕ دِژُن دۄشوٕے اِسرٲیلِیُک مرد تہٕ زنانہِ ہٕندِس یٔڈ سٍتـ̡ دِنہٕ۔ چنانچہ آو یہ طاعون بنی اسرائیل نِش رُکاونہٕ۔\n9.\\tتہٕ یِم طاعون منز مٔرۍ، تِم ٲسۍ وُہ ژۅۅن ساس۔\n10. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n11.\\tہارون کاہنہِ سُند نیچو الیعزر سُند نیچو فینہاسن ہیوٚت میٲنۍ قہر بنی اسرٲیلِس نِش ہٹٲومُت، ییلہ زن سُہ میانہِ خاطرہ میانہِ خاطرہ جوش اوس، زِ میہ کٔر نہٕ پننِس حسدس منز بنی اسرائیل کھیوان۔ {for...: ہیب۔ میانہِ جوشس سٍتۍ}\n12. وَنُن وُچھِو، بہٕ چُھس أمِس پنُن امنُک عہد دِوان:\n13. تہٕ أمِس میلہِ یہِ تہٕ أمِس پَتہٕ تٔمۍ سُند اولاد، یێلہِ تہِ آسہِ ہمیشہٕ پادٕرۍ آسنُک معاہدٕ۔ تکیازِ سُہ اوس پننِس خدایہ سٕندِ خٲطرٕ جوش، تہٕ بنووُن بنی اسرٲیلِس خٲطرٕ کفارہٕ۔\n14.\\tوۅنۍ اوس اسرٲیلِس سُند ناو یُس مدیانی زنانہِ سٍتـ̡ مارنہٕ آو، {اوس} زیمری، یُس سمولو سُند نیچو اوس، یُس سمیونین مَنٛز أکِس اہم خاندانُک شہزادہ اوس۔ {چیف...: ہیب۔ اکھ مٲل سُند گھر}\n15.\\tتہٕ مدیانی زنانہِ ہُند ناو یُس قتل کرنہٕ آمُت اوس، اوس زورٕچ کور۔ سُہ اوس أکِس لُکن ہُند سربراہ، {تہٕ} مدیانس مَنٛز أکِس اہم گرس سٍتـ̡ ۔\n16.\\tتہٕ خداوند کٔر موسیٰ سٍتـ̡ کتھ کٔرِتھ،\n17.\\tمدیانین ہٕندِس مُتعلِق تہٕ دِیُن دِیُن:\n18.\\tتِکیازِ تِمو چُھ تۅہہِ پَنٕنِس چالو سٍتـ̡ تُہٕندِس معاملس مَنٛز تہٕ مَدیان کِس أکِس شہزادٕ سٕنزِ کورِ کوزبی سٕندِس معاملس مَنٛز، یۄس پیور سٕندِ خٲطرٕ طاعون ہٕندِس دۅہہٕ مارنہٕ آمٕژ ٲس۔","1. تہٕ وُپھ پَتہٕ سپُد یہِ زِ خداوند کٔر موسیٰ تہٕ ہارون سٕندِس نیچوِس الیزارس سٍتـ̡ کتھ ،\n2. وُہُہ وُہُر وُہُر وٲنسہِ پیٹھٕ تہٕ اَمہِ کھۄتہٕ زیادٕ وٲنسہِ ہٕندِس سارِنٕے جمٲژ ہُند مجموعہ نِیُن یُس اسرٲیلِس مَنٛز جنگس منز گژھنس لایق چھُ۔\n3.\\tتہٕ موسیٰ تہٕ الیعزر پادٕرۍ کٔر یریحہ کِس نزدیک، موآب کِس مٲدانس مَنٛز یِمن سٍتـ̡ کتھ باتھ کٔرِتھ وونُن،\n4.\\t{لوکن ہُند رقم}، وُہن وُہُر وٲنسہِ پیٹھٕ تہٕ امہِ کھوتہٕ زیادٕ۔ یِتھٕ کٔنۍ خداوند دِیُت موسیٰ تہٕ بنی اسرٲیلِس حُکُم، یُس مصر کِس سرزمینہٕ منزٕ نیبر نیرِ۔\n5. روبن، اسرٲیلُک بوٚڈ نیچو: روبن سٕندِ شُرۍ۔ ہنوچ، {یمن منٛز چُھ} ہنوچیٹس ہُنٛد خاندان: پالوُک، پالویٹس ہُنٛد خاندان:\n6. ہیزرون سُند خاندان: کارمی سُند خاندان، کارمائٹس ہُند خاندان۔\n7.\\tیِم چھِ روبینن ہٕندِ خاندانہٕ: تہٕ یِمن ہُند تعداد اوس تِمن ہُند تعداد ترتٲجی تہٕ ترہ ساس تہٕ ستھ ہتھ ترٕہ۔\n8.\\tتہٕ پلو سٕندِ نیچوۍ۔ الیاب۔\n9.\\tتہٕ الیاب سٕندِ نیچو۔ نیموئیل، تہٕ داتھن، تہٕ ابیرام۔ یہِ چُھہ سُہ داتھن تہٕ ابیرام، یِم جمٲژ مَنٛز مشہوٗر، یِمو موسیٰ سٕندِس تہٕ ہارونس خلاف کورہ سٕندِس صحبتس منز جدوجہد کٔر، ییلہِ تِمو خداوند سٕندِس خلاف جدوجہد کٔر:\n10.\\tتہٕ زمینہِ کٔر پنن بوش تہٕ کورہس سٍتـ̡ گِلہِ، ییلہ سُہ صحبت، کمہِ وِزِ نارن زٕ ہتھ پنژاہ نفر کھِلۍ، تہٕ تِم بنییہِ اکھ نشانہٕ۔\n11.\\tباوجوٗد تہِ گٔیہِ نہٕ کورہ سٕندِ شُرۍ مٔرۍ۔\n12.\\tشمعون سٕندِ نیچوۍ تہندِس عیالس پتہٕ: نیموئیلُک خاندان: یامین سُند خاندان: یامین سُند خاندان: جاچین سُند خاندان: {نیموئیل: یموئیل تہِ ونان چھِ} {یَخن: یَتھ تہِ وَننہٕ یِوان چھُ}\n13.\\tزرہِ سُند خاندان: شاؤل سُند خاندان۔ {زرہ: تہِ ونان چھہِ، زوہر}\n14.\\tیِم چھہِ شمعون سٕندِ خاندان، وُہُہ زٕ ساس زٕ ہتھ۔\n15.\\tگاد سٕندِ شُرۍ: زیفونُک خاندان: ہاگی سُند، ہیگِٹَن ہُند خاندان: شونی سُند، شُونِین ہُند خاندان: {زیفون: زیفیون تہِ ونان چھِ}\n16.\\tاوزنیُک خاندان: ایری ہُند، ایریٹس ہُند خاندان: {اوزنی: یتھ ایزبون تہِ ونان چھِ}\n17. ارودی سُند خاندان: اریلی ہُند خاندان، آریلیٹن ہُند خاندان۔ {آروڈ: یتھ ارودی تہِ ونان چھِ}\n18.\\tیِم چھِ گاد سٕندٮ۪ن شُرین ہٕندِ خاندانہٕ مُطٲبق یِمن ہُند تعداد ژتٲجی ساس تہٕ پانژھ ہتھ اوس۔\n19.\\tیہوداہ سٕندِ نیچوۍ ایر تہٕ اونان: تہٕ ایر تہٕ اونان گٔیہِ کنعان کِس سرزمینس مَنٛز۔\n20. تہٕ یہوداہ سٕندِ نیچو تہندِس عیالس پتہٕ۔ شیلاہن ہُند خاندان: فرازُک خاندان، فرعی سُند خاندان: زرہُک خاندان، زرہین ہُند خاندان۔\n21.\\tتہٕ فریض سٕندِ نیچوۍ ٲسۍ۔ ہیزرون سُند خاندان: ہمولُک ، ہمولن ہُند خاندان۔\n22. یِم چھِ یہوداہٕکۍ خاندان یِمن ہُند تعداد تریہ تہٕ شُراہ ساس پانژھ ہتھ ۔\n23.\\tاِساکر سٕندِس خاندانس پَتہٕ یِمن ہٕندِس عیالس سٍتـ̡ {of} تولا، تولیٹس ہُند خاندان: پُوا ہُند خاندان: {پوا: یا، پھووا}\n24.\\tیشوبُک خاندان، یشوبن ہُند خاندان: شمرون سُند، شِمرونین ہُند خاندان۔ {جاشوب: یا، ایوب}\n25.\\tیِم چھِ اِساکرٕکۍ خاندان یِمن ہُند تعداد تریہ تہٕ ژور ساس تریہ ہتھ اوس۔\n26.\\tزیبولون سٕندِ نیچوۍ تہندِس عیالس پتہٕ: سیرید، ساردیتن ہُند خاندان: ایلون سُند، ایلونین ہُند خاندان: جاہلیل سُند، جہلیلن ہُند خاندان۔\n27.\\tیِم چھہِ زبولونین ہٕندِ خاندانہٕ مُطٲبق یِمن ہُند تعداد تریہ ساس تہٕ پانژھ ہتھ اوس۔\n28.\\tیوسف سٕندِس عیالس سٍتـ̡ نیچو ٲسۍ منسی تہٕ افرائیم۔\n29.\\tمَنسِہ سٕندِس نیچوِس منز: مَخیٖر سٕندِس عیالس سٍتـ̡ تہٕ مٔچِر گۆو گلعاد سٕندِس عیالس سٍتـ̡ گُلعادُک عیال۔\n30.\\tیِم {چھِ} جلعاد سٕندِ نیچوۍ: {of} جیزر، جیزرین ہُند خاندان: ہیلیکُک خاندان: {جیزر: یتھ ابیزر تہِ ونان چھِ}\n31. تہٕ {of} اسریئل، اسریلائٹن ہُند خاندان: تہٕ {of} شیکیم، شیکیمیٹن ہُند خاندان:\n32.\\tتہٕ شیمیڈا، شیمیدائٹن ہُند خاندان: تہٕ {of} ہیفر، ہیفریتس ہُند خاندان۔\n33.\\tتہٕ ہیفر سٕندِس نیچوِس زیلوفہدس اوس نہٕ کانہہ نیچو، مگر کورِ: تہٕ زیلوفہد سٕنزِ کورِ ہُند ناو اوس مہلہ تہٕ نوح، ہوگلہ، ملکہ تہٕ ترزاہ۔\n34.\\tیِم چھِ مَنسِہ سٕندِ خاندانہٕ تہٕ یِمن ہُند تعداد پنژاہ زٕ ساس ستھ ہتھ اوس۔\n35.\\tیِم چھہِ افرایم سٕندِ خاندانہٕ پتہٕ: شُتھلہ سُند خاندان: بیچرُک، بکرِیَن ہُند خاندان: تہانُک خاندان، تہانُک خاندان۔ {بیچر: بیرڈ تہِ ونان چھِ}\n36.\\tتہٕ یِم چھِ شُتھلہ سٕندِ نیچِوۍ: ایران سٕندِس خاندانس سٍتـ̡ ۔\n37.\\tیِم چھہِ افرایم سٕندٮ۪ن نیچوین ہٕندِ خاندانہٕ مُطٲبق یِمن ہُند تعداد ترہ زٕ ساس پانژھ ہتھ اوس۔ یِم چھِ یوسف سٕندِ عیالس پَتہٕ نیچو۔\n38.\\tبنیامین سٕندِ نیچوۍ یِمن ہٕندِس عیالس پتہٕ: بیلا سُند، بیلیتس ہُند خاندان: احیرامُک خاندان: احیرامُک خاندان: {احیرم: یتھ تہِ ونان چھِ، ایہی، یا، اہراہ}\n39.\\tشوفامُک خاندان: ہُفامُک خاندان، ہُفامُک خاندان۔ {شوپھم... ہُپھم: مُپِم تہٕ ہپِم تہِ ونان چھِ}\n40.\\tتہٕ بیلہ سٕندِ نیچوۍ ٲسۍ ارد تہٕ نعمان: {اردُک}، اردِس سُند خاندان: {تہٕ} نعمان سُند خاندان۔ {ارد: تہٕ چُھ ونان، ادار}\n41.\\tیِم چھہِ بنیامین سٕندِ نیچوۍ تہٕ یِمن ہُند تعداد اوس ژتٲجی تہٕ پانژتٲجی ساس شیہ ہتھ۔\n42.\\tیم چھہِ دان سٕندِ نیچوۍ تہندِس عیالس منز: شوہام سٕندِس خاندانس منز۔ یم {چِھ} ڈین سٕندِ خاندانہٕ پتہٕ تہندِس عیالس پتہٕ۔ {شوہم: یا، ہشیم}\n43.\\tشوہامین ہٕندِس سارِنٕے خاندانن ہٕندِ مطٲبق ٲسۍ تریہ تہٕ ژور ساس ژور ہتھ۔\n44. آشر سٕندِ شُرۍ تہندِس عیالس پتہٕ: جمناہُک، جِمنیٹَن ہُند خاندان: یسوعی سُند خاندان: بیریاہُک خاندان۔\n45. بیریاہ سٕندِس نیچوِس منز: ہیبرُک خاندان: مالکیل سُند، مالکیلیٹن ہُند خاندان۔\n46. تہٕ عاشر سٕنزِ کورِ ہُند ناو اوس سارہ۔\n47.\\tیِم چھہِ آشر سٕندٮ۪ن نیچوین ہٕندِ خاندانہٕ مُطٲبق یِمن ہُند شمار اوس کرنہٕ آمُت۔ {یِم ٲسۍ} پنژاہ تریہ ساس تہٕ ژور ہتھ۔\n48.\\tنفتالی سٕندِس نیچوِس تہندِس عیالس پتہٕ: جہزیلُک خاندان: گُنی سُند خاندان:\n49.\\tجیزرُک خاندان: شِلمُک خاندان، شِلِمُک خاندان۔ {شِلم: تہِ وَننہٕ آمُت شَلوم}\n50.\\tیِم چھِ نفتالی ہٕندِ خاندانہٕ مُطٲبق تہٕ یِمن ہُند تعداد اوس ژتٲجی تہٕ پانژتٲجی ساس ژور ہتھ۔\n51.\\tیِم أسـ̡ بنی اسرائیلـ̡ ہُند تعداد شیہ لچھ تہٕ ستھ ہتھ ترٕہ۔\n52. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n53.\\tیمن منز گژھہِ زمین وراثت خٲطرٕ تقسیم کرنہٕ یُن۔\n54.\\tواریاہن لوکن دِیُن زیادٕ وراثت، تہٕ کم وراثت دِیُن پرٮ۪تھ کٲنسہِ ہٕندِس وَرثس مُطٲبق یِم أمِس گنزراونہٕ آمٕتۍ چھِ۔ {مزید دِیو...: ہیب۔ تٔمۍ سُند وراثت ضرب کرُن} {کم دِیُن...: ہیب۔ پنن وراثت کم کرُن}\n55.\\tبہر حال زمین گژھہِ قرعہ اندازی سٍتۍ بٲگراونہٕ: تِمن ہٕندِس مٲلِس سٕندِس قبیلن ہٕندِ ناوٕ مُطٲبِق یِن تِمن ہٕندِس مٲلِس سٍتـ̡ وَرثس مُطٲبِق۔\n56.\\tلاٹ مطٲبق گژھہِ امیک قبضہ واریاہن تہٕ کم لوکن منز تقسیم کرنہٕ یُن۔\n57.\\tتہٕ یِم چھِ تِم یِمن ہٕندِس عیالس نِش لیوی سٕندِ خاندانہٕ سٍتـ̡ شمار کرنہٕ آمٕتۍ: گرشون سُند، گرشونیَن ہُند خاندان: کوہتھُک خاندان، کوہاتی ہُند خاندان: میراری ہُند خاندان۔\n58.\\tیِم چھہِ لاوِین ہُند خاندان: لبنین ہُند خاندان، ہیبرونیٹس ہُند خاندان، مہلیتن ہُند خاندان، موشیتن ہُند خاندان، کوراتھین ہُند خاندان۔ تہٕ کوہاتھ زاو امرام۔\n59.\\tتہٕ امرام سٕنزِ زنانہِ ہُند ناو اوس لیوی سٕنز کورِ، یُس [تسٕنزِ ماجہِ} مصرس مَنٛز لیوی سٕندِس نِش زاے اوس، تہٕ سۅ زاے امرام، ہارون تہٕ موسیٰ تہٕ مریمس تہٕ تِہنز بینہِ۔\n60.\\tتہٕ ہارونس زاے نادب، تہٕ ابیہو، الیعازر تہٕ اِتھمار۔\n61.\\tتہٕ نداب تہٕ ابیہو گٔیہِ مٔرۍ، یێلہِ تِمو خداوند سٕندِ برونہہ کُن عجیب نار پیش کٔر۔\n62.\\tتہٕ یِمن ہُند تعداد اوس وُہ تریہ ساس، سارِنٕے مرد ٲسۍ اَکہِ رٮ۪تہٕ پیٹھٕ تہٕ اَمہِ کھۄتہٕ زیادٕ وٲنسہِ، تِکیازِ تِم ٲسۍ نہٕ بنی اِسرٲیلِس مَنٛز شمار کرنہٕ آمٕتۍ، تِکیازِ تِمن اوس نہٕ بنی اِسرٲیلِس مَنٛز کانہہ وَراثت دِنہٕ آمُت۔\n63.\\tیِم چِھہ تِم یِمن موسیٰ تہٕ الیعزر پادٕرین گنزراونہٕ آمٕتۍ، یِمو اردن کِس میدانس مَنٛز موآب کِس مٲدانس مَنٛز بنی اسرائیل گنزراونہٕ آمٕتۍ۔\n64.\\tمگر یِمو مَنٛز اوس نہٕ کانہہ تہِ نفر یُس موسیٰ تہٕ ہارون پادٕرۍ گٔنزراوان اوس، یێلہِ تِمو سینا کِس بیابانس مَنٛز بنی اسرٲیلِچ گنزراونہٕ آمٕژ ٲس۔\n65.\\tکیازِ خداوند اوس تِمن متعلق ووٚنمُت، یِم گژھن یٔقیٖنی طور بیابانن مَنٛز مرٕنۍ۔ تہٕ یِمو منزٕ اوس نہٕ کانہہ نفر باقی، یۅپھُن سُند نیچو کالب، تہٕ راہب سُند نیچو یشوع سٕندِس نیچوس علاوٕ۔","1. اَمہِ پَتہٕ آیہِ زیلوفہد سٕنزِ کورِ، یُس ہیفر سُند نیچو، جلعاد سُند نیچو، مَچِر سُند نیچو، مانسیہ سُند نیچو، یوسف سُند نیچو مناسہ سٕندِس خاندانس منز، تہٕ یِم چھِ تٔمۍ سٕنزِ کورِ ہٕندِ ناو۔ محلہ، نوح تہٕ ہوگلہ تہٕ ملکہ تہٕ ترزہ۔\n2. تہٕ تِم گٔیہِ موسیٰ سٕندِس برونہہ کُن، تہٕ پادٕرۍ الیعزر تہٕ سارِنٕے جمٲژ برونہہ کُن، تہٕ وونُن زِ\n3.\\tسون مول موٗد بیابانس مَنٛز، تہٕ سُہ اوس نہٕ تِمن ہٕندِس صحبتس مَنٛز یِمو کورہ سٕندِس صحبتس مَنٛز خداوند سٕندِس خلاف جمع گٔیہِ۔ مگر پننِس گۅنہٕ سٍتـ̡ موٗد تہٕ تٔمِس اوس نہٕ کانہہ نیٚچُو۔\n4.\\tسٲنِس مٲلہِ سُند ناو کیازِ گژھہِ تٔمِس عیالس مَنٛز دوٗر کرنہٕ یُن، کیازِ أمِس چُھ نہٕ کانہہ نیچو۔ اَمہِ مۄکھٕ دِیُن اسہِ مٲلہِ سٕندِس بٲے سٕندِس بٲے سٍتـ̡ اکھ جایداد ۔ {کٔرۍ...: ہیب۔ کم گومُت}\n5. تہٕ موسىٰ ووت تِہُند مقصد خداوند برونہہ کُن۔\n6. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n7.\\tزیلوفہد سٕنزِ کورِ چھے صحیح: تۅہہ دِیُن یِمن مٲلہِ سٕندِس بٲے سٕندِس باین مَنٛز وراثتُک قبضہ۔ تہٕ تُہۍ کٔرِو تِہنٛدِس مٲلہِ سٕنٛز وراثت تِمن نِش واتناوٕنۍ۔\n8. تہٕ تُہۍ کٔرِو بنی اِسرٲیلِس سٍتـ̡ کتھ کرنہٕ، یێلہِ یێلہِ کانہہ مرد مٔرِتھ تہٕ نیچو آسہِ نہٕ، تێلہِ گژھِو تٔمۍ سٕندِس کورِ ہٕندِس وَرِثس مَنٛز واتناوُن۔\n9. یێلہِ نہٕ أمِس کانہہ کوٗر آسہِ، تێلہِ دِیُو تٔمۍ سٕنز وٲرِث تٔمۍ سٕندِس بٲے سٍتـ̡ دِنہٕ۔\n10. تہٕ یێلہِ نہٕ أمِس بٲے آسہِ، تێلہِ دِیُو تٔمۍ سٕندِس مٲلہِ سٕندِس بٲے سٕندِس وَرثس دِنہٕ۔\n11. تہٕ یێلہِ نہٕ تٔمۍ سٕندِس مٲلِس کانہہ بٲے آسہِ، تێلہِ گژھِو تٔمۍ سٕندِس عیالس سٍتـ̡ تٔمِس سٕندِس رشتہٕ دارس وَرث دِنہٕ، تہٕ یێلہِ خداوند موسىٰ سُند حُکُم دِیُتمُت چھُ۔\n12. تہٕ خداوند ووٚن موسیٰ سٕندِس یتھ پہاڑس پیٹھ کھسُن، تہٕ وُچھِو سُہ زمین یُس مے بنی اسرٲیلِس دِژمُت چھُ۔\n13. تہٕ ییلہ یہ وُچھو، تہٕ یِتھ کٔنۍ ہارون تُہند بٲے آو جمع کرنہٕ۔\n14.\\tکیازِ تۅہہ کٔر زِن صحراہس مَنٛز، جماعت ہٕندِس کشمکشس مَنٛز، تہنزِ نظرن برونہہ کنہِ آبس مَنٛز میہ پاکیزگی کرنہٕ خٲطرٕ میانہِ حُکمس خلاف بغاوت کٔرمٕژ: یعنی زِن کِس بیابانس مَنٛز قادیشس مَنٛز مریبہ ہُند آب۔\n15.\\tتہٕ موسیٰ کٔر خداوند سٍتـ̡ وَنُن زِ\n16.\\tخداوند یُس سارِنٕے جسمن ہٕندِس روحن ہُند خدا، یُس أکِس انسانس اجتماعس پیٹھ مقرر کرُن،\n17.\\tیُس تِمن برونہہ کُن نیرِتھ، تہٕ یُس تِمن برونہہ کُن گژھِ، تہٕ یُس تِمن نِش نیرِتھ، تہٕ یُس تِمن اندر انِتھ۔ زِ خداوند سٕنز جماعت گژھہِ نہٕ کۅکرِ ہٕندۍ پٲٹھۍ۔\n18. تہٕ خداوند ووٚن موسیٰ سٕندِس نیچو یشوع یُس نُن سُند نیچو چُھ، یُس انسان چُھہ یٔمِس مَنٛز روح چُھ، تہٕ تھووُن پَنُن اتھہٕ أمِس پیٹھ۔\n19. تہٕ تھووُن سُہ پادٕرۍ الیعزر تہٕ سارِنٕے جمٲژ برونہہ کُن۔ تہٕ تِمن ہٕندِس نظرِ منز دِیُن أمِس اکھ چارج۔\n20.\\tتہٕ پَنُن عزتُک کُنہِ حِصہٕ تھاوُن یُتھ بنی اسرٲیلٕچ سارِنٕے جماعت گژھن فرمانبردار۔\n21. تہٕ سُہ گژھہِ پادٕرۍ الیعزر سٕندِس برونہہ کُن، یُس خداوند سٕندِس کُنہِ سٍتـ̡ یُس أمِس سٍتـ̡ نیرِ، تہٕ تٔمۍ سٕندِس کلامس سٍتـ̡ گژھن تِم اژُن، تہٕ تٔمۍ سٕندِس کلامس سٍتـ̡ گژھن تِم اژنہٕ، سُہ تہٕ سارِنٕے بنی اسرائیل تہٕ سارِنٕے جماعتن تہِ۔\n22. تہٕ موسىٰ کٔر خداوند سُند حُکُم یُس أمِس حُکُم کٔرِتھ، تہٕ تٔمۍ رٔٹ یشوع تہٕ تھووُن سُہ کُدٕنِس کُدٕنِس کُنہِ\n23. تہٕ تٔمۍ تھووُن أمِس پیٹھ اتھہٕ، تہٕ دیتُن أمِس حکم دِنہٕ، یِتھ کٔنۍ خداوند موسیٰ سٕندِ اتھہٕ سٍتـ̡ حکم دِژمُت۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. بنی اسرٲیلِس حُکُم کٔرِو تہٕ تِمن ونُن، میٲنۍ نذرانہ تہٕ میٲنۍ روٹی یُس نارٕ سٍتـ̡ دِنہٕ آمُت چُھ، {یێلہِ} میانہِ خٲطرٕ اکھ مٔٹھُر مَزٕ چُھہ، تہٕ تِمن ہٕندِس وقتس پیٹھ کٔرِو میہ پیش کرنہٕ۔ {اکھ مٔٹھۍ...: ہیب۔ میانہِ آرام ہُند ذائقہ}\n3. تہٕ تُہۍ وَنُن تِمَن زِ یہِ چُھہ نارٕ سٍتـ̡ دِنہٕ آمُت نذرانہ یُس تُہۍ خداوند سٍتـ̡ پیش کرُن۔ گۅڈنچہ ؤرۍ یکۍ زٕ کٹہٕ بچہٕ دۅہہ دۅہہ دۅہہ، {امہ مۅکھہٕ} چُھ مسلسل زالنہٕ آمُت۔ {دۄہ پتہٕ دۄہ: ہیب۔ أکِس دۄہَس منٛز}\n4.\\tاکھ کۅکرِ بچہٕ چُھہ صبحٲے پیش کرُن، تہٕ بییِم کۅکرِ دِیُن تہٕ بییِس کۅکرِ سٍتـ̡ تہِ دِیُن۔ {حتیٰ کہ: ہیب۔ دۄن شامن درمیان}\n5.\\tتہٕ مازٕچ نذرانہ خٲطرٕ آٹُک دٔہِم حصہٕ، یُس ژوٗرِمِس تیٖلس سٍتۍ رلاونہٕ آمُت چھُ۔\n6. {یہِ} چُھ اکھ مسلسل دزنہٕ آمُت قربانی، یُس کوہ سیناہس مَنٛز مٔٹھۍ مَزٕ خٲطرٕ مقرر کرنہٕ آمُت اوس، یُس نارٕ سٍتـ̡ خداوند سٕندِ خٲطرٕ دِنہٕ آمُت چھُ۔\n7. تہٕ اَمہ سٍتـ̡ چُھہ شرابُک ژوٗرِم حصہٕ یُس أکِس کۅکرِ سٕندِ خٲطرٕ آسہِ: مُقدس مقامس مَنٛز گژھِو تُہٕندِس مُقدسَس سٍتـ̡ شرابُک نذرانہ دِنہٕ خٲطرٕ۔\n8.\\tتہٕ دوٚیِم کۅکرٕ دِیُن صبحُک ماز تہٕ امہِ سٍتـ̡ شرابٕچ نذرانہ پٲٹھۍ، یُس نارٕ سٍتـ̡ دِنہٕ آمُت چُھ، یُس خداوند سٕندِ خٲطرٕ مٔٹھُر مَزٕ چُھہ دِنہٕ یُن۔\n9. تہٕ سبت دۅہہٕ گۅڈنچہ ؤریکۍ زٕ کٹہٕ بچہٕ تہٕ دٔہمہِ دٔہمہِ ماز خٲطرٕ، تیٖلس سٍتـ̡ رلاونہٕ آمُت، تہٕ اَمہ سٍتـ̡ چُھہ شرابُک نذرانہ پیش کرنہٕ۔\n10. {یہِ} چُھہ پرٮ۪تھ سبت سٍتـ̡ دزنہٕ یِنہٕ واجنہِ قربانی تہٕ تٔمۍ سٕندِس شرابٕچ نذرانہ سٍتـ̡ دِنہٕ آمُت۔\n11. تہٕ پَنٕنـ̡ ریٚتن ہٕندِس آغازس مَنٛز کٔرِو تُہۍ خداوند سٕندِ خٲطرٕ زٲلِتھ قربان کرنہٕ۔ زٕ جوان بیل، تہٕ اکھ ریم، گۄڑنکہٕ ؤرۍ یٕکۍ ستھ کٹہٕ بچہٕ بغٲر داغ۔\n12.\\tتہٕ أکِس بیلس خٲطرٕ ماز نذرانہٕ خٲطرٕ تریہ دٔہِم سودا تہٕ آٹُک زٕ دٔہِم سودا {خٲطرٕ} اکھ ماز نذر، یُس تیٖلس سٍتۍ رلاونہٕ آمُت چھُ، أکِس کُنہِ کُنہِ کُنہِ رنٛگہٕ خٲطرٕ؛\n13.\\tتہٕ دٔہِم دٔہِم آٹُک سٍتـ̡ تیٖلس سٍتـ̡ رلاونہٕ آمُت {یێلہِ} چُھہ أکِس دانٛدس ماز نذرانہ سٍتـ̡ دِنہٕ آمُت۔ {تکیازِ} اکھ مٔٹھۍ ذائقہٕ سٕنز دزنہٕ آمٕژ قربانی، یُس نارٕ سٍتـ̡ خداوند سٍتـ̡ دِنہٕ آمُت چھُ۔\n14.\\tتہٕ تِہُند شرابُک نذرانہٕ گژھہِ أکِس داندس خٲطرٕ نصف ہِن، تہٕ ہِنُک تریم حصہٕ آسہِ أکِس کۅکرس خٲطرٕ، تہٕ ژوٗرِم حصہٕ آسہِ أکِس داندس خٲطرٕ، یِہ چُھ ؤری کِس ریتس منز پرٮ۪تھ ریتہٕ سٍتـ̡ دزنہٕ یِوان۔\n15.\\tتہٕ گۅناہ ہٕندِ قربانی خٲطرٕ یِیہِ ژھاوُن ہُند اکھ بچہٕ یُس خداوند سٕندِ خٲطرٕ دِنہٕ یُن، تہٕ تٔمۍ سٕندِس شرابٕچ نذرانہ سٍتـ̡ ییہِ پیش کرنہٕ۔\n16. تہٕ گۅڈنِکِس ژۄدٲہِمِس دۅہس مَنٛز چُھ خداوند سُند فسح ۔\n17. تہٕ ییٚمہِ رٮ۪تہٕ کِس پنٛدٲہِمہِ دۅہہٕ چُھ دعوت: سَتھ دۅہہٕ یِن خمیر روٚس روٹی کھٮ۪نہٕ۔\n18.\\tگۅڈنِکِس دۅہس مَنٛز گژھہِ اکھ مقدس کانووکیشن۔ تۅہہ گژھِ نہٕ کانہہ تہِ غلامی کٲم کٔرِتھ:\n19. مگر تُہۍ کرو نارٕ سٍتـ̡ دِنہٕ آمٕژ قربانی یُس خداوند سٍتـ̡ دِنہٕ آمُت چھُ۔ زٕ بچہٕ بیل تہٕ اکھ کۅکرِ تہٕ گۅڈنچہ ؤریس منز ستھ کٹہٕ: تِم گژھن توے خٲطرٕ بے عیب آسن۔\n20.\\tتہٕ تِہُند ماز آسہِ تیٖلس سٍتـ̡ رلاونہٕ آمُت: تریہ دٔہِم سودا کٔرِو أکِس بیلس تہٕ دٔہِم دٔہِم سودا۔\n21. سَتَن دانٛدن ہٕندِس خٲطرٕ کٔرِو دٔہِم دٔہِم سودا ۔\n22. تہٕ اکھ ژھاوٕل {خٲطرٕ} گۅناہ ہٕندِس نذرانہ خٲطرٕ، یُس تۅہہِ خٲطرٕ کفارہ دِنہٕ خٲطرٕ۔\n23.\\tیِم دِیِو صُبحَس سٍتـ̡ دزنہٕ نذرانہ سٍتـ̡ پیش کرنہٕ، یُس {چُھ} مسلسل دزنہٕ خٲطرٕ پیش کرنہٕ یُن۔\n24.\\tیِتھٕ پٲٹھـ̡ یێلہِ سٍتـ̡ سَتَن دۅہن سٍتـ̡ دِنہٕ آمُت قربانی ہُند ماز یُس خداوند سٕندِ خٲطرٕ مٔٹھـ̡ مٔٹھـ̡ چُھہ دِنہٕ یُن، یێلہِ سٍتـ̡ یێلہِ سٍتـ̡ دِنہٕ یِنہٕ وٲلِس نذرانہ سٍتـ̡ پیش کرنہٕ یُن۔\n25. تہٕ سٔتِمہِ دۅہہٕ گژھہِ تُہُند مقدس اجتماع۔ تۅہہ گژھِ نہٕ کانہہ غلامی کٲم کٔرِتھ۔\n26.\\tگۅڈنچہ پھلہٕ دۅہہٕ ییلہ تہٕ یێلہِ تُہۍ خداوند سٕندِ خٲطرٕ نۆو ماز پیش کران چھِو، ہفتہٕ پَتہٕ گژھہِ تۅہہِ ہُند مقدس اجتماع۔ تُہۍ کرِ نہٕ کانہہ غلامی کامہِ:\n27. مگر تُہۍ کٔرِو خداوند سٕندِ خٲطرٕ مٔٹھۍ مٔزِتھ دِنہٕ یِنہٕ خٲطرٕ دِنہٕ۔ زٕ جوان بیل، اکھ کۅکر، گۅڈنچہ ؤریس منز ستھ دانٛد۔\n28.\\tتہٕ تِہُند ماز چُھ تیٖلس سٍتـ̡ رلاونہٕ آمُت، تریہ دٔہِم دٔہِم أکِس دانٛدس سٍتـ̡ تہٕ دٔہِم دٔہِم دٔہلہٕ أکِس دانٛدس سٍتـ̡\n29.\\tسَتَن کۅکرَن ہٕندِس سٍتـ̡ دٔہمہِ ہُند سودا چُھہ أکِس کۅکرس سٍتـ̡ دٔہلِتھ\n30. {تہٕ} ژھاوُل ہُند اکھ شُر، تۅہہِ خٲطرٕ کفارہ دِنہٕ خٲطرٕ۔\n31.\\tتُہۍ کٔرِو تِمن سٍتـ̡ مسلسل دزنہٕ یِنہٕ واجنہِ نذرانہ تہٕ تٔمۍ سٕندِس مازٕچ نذرانہ تہٕ تِمن ہٕندِس شرابٕچ نذرانہ پیش کرنہٕ۔","1. تہٕ سٔتِمہِ رٮ۪تہٕ کِس گۄڈنِکِس دۅہہٕ گژھِ تُہُند مُقدس اجتماع کرنہٕ۔ تۅہہ گژھِ نہٕ کانہہ غلامی کٔرِتھ: یہ چُھ ژےٚ خٲطرٕ بۄر واونُک دۄہ۔\n2. تہٕ تُہۍ کٔرِو خداوند سٕندِ خٲطرٕ مٔٹھۍ مَزٕ خٲطرٕ زٲلِتھ نذرانہ پیش کرنہٕ۔ اکھ جوان بیل، اکھ کۅکر، {تہٕ} گۅڈنچہ ؤریس منز ستھ دانٛد بچہٕ۔\n3.\\tتہٕ تِہُند ماز آسہِ تیٖلس سٍتۍ رلاونہٕ آمُت، أکِس بیلس خٲطرٕ تریہ دٔہِم سودا، {تہٕ} زٕ دٔہِم سودا،\n4.\\tتہٕ سَتَن کۅکرِ ہٕندِس دٔہِمِس سٍتـ̡\n5.\\tتہٕ ژھاوُن ہُند اکھ شُر، یُس تۅہہِ خٲطرٕ کفارہ دِنہٕ خٲطرٕ:\n6.\\tریتُک زٲلِتھ نذرانہ تہٕ تٔمۍ سٕندِس مازٕچ نذرانہ تہٕ تٔمۍ سٕندِس مازٕچ نذرانہ تہٕ تِہٕندِ طٔریٖقہٕ مُطٲبِق چُھہ مٔٹھہِ مَزٕ خٲطرٕ، یُس خداوند سٕندِ خٲطرٕ نارٕ سٍتـ̡ دِنہٕ آمُت چھُ۔\n7. تہٕ یێمہِ سٔتِمہِ رٮ۪تہٕ کِس دٔہمہِ دۅہہٕ گژھہِ اکھ مُقدس اجتماع۔ تہٕ تُہۍ کٔرِو پننین روحن تکلیف: تہٕ تُہۍ کرو نہٕ کانٛہہ تہِ کٲم {اَتھ منٛز}۔\n8. مگر تُہۍ کٔرِو خداوند سٕندِ خٲطرٕ اکھ زٲلِتھ نذرانہ پیش کرنہٕ۔ اکھ جوان بیل، اکھ کۅکر، {تہٕ} گۅڈنچہ ؤریس منز ستھ دانٛد۔ تِم گژھن تۅہہِ خٲطرٕ بے عیب آسن:\n9.\\tتہٕ تِہُند ماز آسہِ تیٖلس سٍتـ̡ رلاونہٕ آمُت، تریہ دٔہِم سودا أکِس دانٛدس سٍتـ̡ {تہٕ} زٕ دٔہِم سودا،\n10.\\tستن کۅکرِ ہٕندِس خٲطرٕ واریاہ دٔہِم سودا:\n11.\\tژھاوُن ہُند اکھ بچہٕ {for} گۅناہ ہُند قربانی۔ کفارہٕ چہِ گۅنہٕ نذرانہ علاوٕ، تہٕ مسلسل زالنہٕ یِنہٕ واجنہِ نذرانہ تہٕ تِہٕندِ شرابٕچ نذرانہ علاوٕ۔\n12. تہٕ سٔتِمہِ رٮ۪تہٕ کِس پنٛدٲہِمہِ دۅہہٕ گژھِ تُہُند مُقدس اجتماع۔ تُہۍ کٔرِو نہٕ کانہہ غلامی کامہِ، تہٕ سَتن دۅہن گژھِ خداوند سٕندِ خٲطرٕ دعوت مناون:\n13. تہٕ تُہۍ کٔرِو خداوند سٕندِ خٲطرٕ اکھ مٔٹھۍ مٔزِتھ دِنہٕ آمٕژ نذرانہٕ، نارٕ سٍتـ̡ دِنہٕ آمٕژ قربانی ۔ ترہ جوان بیل، زٕ مینڈ، {تہٕ} گۄڑنِکہٕ ؤرۍ یٕکۍ ژۄداہ دانٛد بچہٕ۔ تِم گژھن بے داغ آسن:\n14.\\tتہٕ تِہُند ماز گژھہِ تیٖلس سٍتـ̡ رلاونہٕ آمُت، ترٚواہ بیلن ہٕندِس پرٮ۪تھ أکِس بیلس تریہ دٔہِم دٔہِم دِنہٕ یُن، دۅن دامن ہٕندِس پرٮ۪تھ کُنہِ کُنہِ دانٛدس سٍتـ̡ دٔہِم دٔہِم دِنہٕ یُن۔\n15.\\tژۅداہ کۅکرِ منزٕ پرٮ۪تھ کُنہِ\n16.\\tتہٕ ژھاوُن ہُند اکھ بچہٕ {خٲطرٕ} گۅنہٕ نذرانہٕ خٲطرٕ۔ لگاتار دزنہٕ آمٕژ نذرانہ علاوٕ، تٔمۍ سٕندِ مازٕچ نذرانہ تہٕ تٔمۍ سٕندِ شرابٕچ نذرانہ علاوٕ۔\n17.\\tتہٕ دۆیمہِ دۅہہ کٔرِو باہ بچہٕ دانٛد، زٕ کۅکر، ژۅداہ کۅکرِ بچہٕ بغٲر داغ۔\n18.\\tتہٕ تِہُند ماز تہٕ تِہُند شرابُک نذرانہ تہٕ تِہُند شرابُک نذرانہٕ دِنہٕ یُن، یِمن ہٕندِس تعدادس مُطٲبق آسہِ۔\n19.\\tتہٕ ژھاوُن ہُند اکھ شُر {یُس گۅنہٕ ہُند قربانی دِنہٕ خٲطرٕ﴾۔ مُسلسل دزنہٕ آمٕژ نذرانہ تہٕ تِمن ہٕندِس ماز نذرانہ سٍتـ̡ تہٕ تِہٕندِس شرابٕچ نذرانہٕ علاوٕ۔\n20.\\tتہٕ تریمہِ دۅہہ کٔرِتھ کاہ بیل، زٕ کۅکر، ژۅداہ کۅکرِ بچہٕ گۅڈنچہ ؤری کُنہِ کُنہِ داغ۔\n21.\\tتہٕ تِہُند ماز تہٕ تِہُند شرابُک نذرانہ تہٕ تِہُند شرابُک نذرانہ تہٕ تِہٕندِ تعدادٕ مُطٲبِق، یِتھٕ پٲٹھۍ:\n22. تہٕ اکھ ژھاوُل {یُس گۅناہ ہُند قربانی دِنہٕ خٲطرٕ﴾۔ لگاتار دزنہٕ آمٕژ نذرانہ تہٕ تٔمۍ سٕندِ مازٕچ نذرانہ تہٕ تٔمۍ سٕندِ شرابٕچ نذرانہ علاوٕ۔\n23.\\tتہٕ ژورمہِ دۅہہ دۅہہ دہہ داہ بیل، زٕ کۅکرِ تہٕ ژۅداہ کۅکرِ بچہٕ یِم بے داغ ٲسۍ۔\n24.\\tتِہُند ماز تہٕ شرابُک نذرانہ تہٕ تِہُند شرابُک نذرانہ یِمن ہٕندِ تعدادٕ مُطٲبق یِنہٕ یِنہٕ پٲٹھۍ:\n25.\\tتہٕ ژھاوُن ہُند اکھ بچہٕ {یُس گۅنہٕ کِس نذرانہ سٍتـ̡ دِنہٕ خٲطرٕ؛ لگاتار دزنہٕ آمٕژ نذرانہ علاوٕ، تٔمۍ سٕندِ مازٕچ نذرانہ تہٕ تٔمۍ سٕندِ شرابٕچ نذرانہ علاوٕ۔\n26. تہٕ پوٗنٛژمہِ دۅہہٕ نَو دانٛد، زٕ کٔرِتھ، {تہٕ} گۅڈنِکِس ؤرۍ یِکۍ ژۄداہ کٹہٕ بچہٕ۔\n27.\\tتہٕ تِہُند ماز تہٕ شرابُک نذرانہ تہٕ تِہُند شرابُک نذرانہ تہٕ یِمن ہٕندِس تعدادس مُطٲبق آسہِ۔\n28. تہٕ اکھ ژھاوٕل {خٲطرٕ} گۅنہٕ نذرانہٕ خٲطرٕ؛ لگاتار دزنہٕ آمٕژ نذرانہ تہٕ تٔمۍ سٕندِ مازٕچ نذرانہ تہٕ تٔمۍ سٕندِ شرابٕچ نذرانہ علاوٕ۔\n29. تہٕ شیٚیمہِ دۅہہٕ ٲٹھ دانٛد، زٕ کۅکرِ تہٕ ژۅداہ کۅکرِ بچہٕ یِمن ہُند بے عیب چھُ۔\n30.\\tتہٕ تِہُند ماز تہٕ شرابٕچ نذرانہ تہٕ تِہٕندِ شرابٕچ نذرانہ یِمن ہٕندِ تعدادٕ مُطٲبق آسہِ۔\n31. تہٕ اکھ ژھاوٕل {خٲطرٕ} گۅنہٕ نذرانہٕ خٲطرٕ؛ لگاتار دزنہٕ آمٕژ نذرانہ علاوٕ، تٔمۍ سٕندِ مازٕچ نذرانہ تہٕ تٔمۍ سٕندِ شرابٕچ نذرانہ علاوٕ۔\n32.\\tتہٕ سٔتِمہِ دۅہہٕ سَتھ دانٛد، زٕ مینڈٕ، {تہٕ} گۅڈنِکِس ؤریس ہٕندِ ژۅداہ کۅکرِ بچہٕ۔\n33.\\tتہٕ تِہُند ماز نذرانہ تہٕ تِہُند شرابُک نذرانہ تہٕ دامن ہٕندِ خٲطرٕ، تہٕ دامن ہٕندِ خٲطرٕ، یِمن ہٕندِ تعدادٕ مُطٲبق، یِتھٕ پٲٹھۍ:\n34.\\tتہٕ اکھ ژھاوُل {یُس گۅناہ ہُند قربانی دِنہٕ خٲطرٕ﴾۔ لگاتار دزنہٕ آمٕژ نذرانہ علاوٕ، تٔمۍ سٕندِ مازٕچ نذرانہ تہٕ تٔمۍ سٕندِ شرابٕچ نذرانہ علاوٕ۔\n35. ٲٹھمہِ دۅہہ گژھہِ تۅہہ اکھ سنجیدہ مجلس: تۅہہ گژھِ نہٕ کانہہ غلامی کٲم کٔرِتھ:\n36. مگر تُہۍ کٔرِو اکھ زٲلِتھ نذرانہ پیش کرنہٕ، یُس نارٕ سٍتـ̡ دِنہٕ آمُت چُھ، یُس مٔٹھۍ مَزٕ چُھہ خداوند سٕندِ خٲطرٕ دِنہٕ یِوان: اَکھ دانٛد، اَکھ کۅکر، گۅڈنِکِس ؤریس ہٕندِس سَتھ دانٛدٕ بچہٕ۔\n37.\\tتِہُند ماز نذرانہ تہٕ تِہُند شرابُک نذرانہ تہٕ دانٛدٕ خٲطرٕ، تہٕ دانٛدن ہٕندِ خٲطرٕ، یِمن ہٕندِ تعدادٕ مُطٲبق آسہِ۔\n38.\\tتہٕ اکھ ژھاوٕل {یُس گۅناہ ہُند قربانی دِنہٕ خٲطرٕ﴾۔ لگاتار دزنہٕ آمٕژ نذرانہ تہٕ تٔمۍ سٕندِ مازٕچ نذرانہ تہٕ تٔمۍ سٕندِ شرابٕچ نذرانہ علاوٕ۔\n39.\\tیِم چیز یِم تُہۍ خداوند سٕندِس مُقرر کِس دعوتس مَنٛز، پنٕنٮ۪ن نذرَن تہٕ پننہِ مرضی ہٕندِس نذرَس مَنٛز، تہٕ پننہِ ماز ہٕندِس نذرانہ باپتھ، تہٕ پننہِ شرابٕچ نذرانہٕ خٲطرٕ، تہٕ پننہِ امن ہٕندِ نذرانہٕ خٲطرٕ کٔرِو۔ {کرُن: یا، پیشکش}\n40. تہٕ موسىٰ ہن ووٚن بنی اسرٲیلِس تِمن سارِنٕے مُطٲبِق یُس خداوند موسیٰ سُند حُکُم دِیُتمُت چھُ۔","1. تہٕ موسىٰ کٔر قبیلن ہٕندِس سرن سٍتـ̡ بنی اسرائیل کِس بارس مُتعلِق کتھ کرنہٕ، یہِ چُھ سُہ چیز یُس خداوند چُھ حُکُم دِژمُت۔\n2. اگر کانہہ انسان خداوند سٍتـ̡ عہد کٔرِتھ، یا پَنُن روح بندھنُک حلف کٔرِتھ۔ سُہ کرِ نہٕ پنُن کلام پھُٹراوُن، سُہ کرِ تِمن سارِنٕے مُطٲبِق یُس پننہِ ٲسہِ منزٕ نیرِ۔ {بریک: ہیب۔ ناپسندیدہ}\n3.\\tاگر کانہہ زنانہ تہِ خداوند سٍتـ̡ عہد کرِ، تہٕ پننِس مٲلہِ سٕندِس گَرَس مَنٛز روزِ، یێلہِ سٍتـ̡ پننِس مٲلہِ سٕندِس گَرَس مَنٛز روزِ۔\n4. تہٕ تٔمۍ سُند مول بوزان تٔمۍ سُند عہد تہٕ تٔمۍ سُند روٝحہٕ بٔنِتھ تہٕ تٔمۍ سُند مول روزِ أمِس سٍتـ̡ تسٕندِس سٍتـ̡ سٍتـ̡ تسٕندِس سٍتـ̡ پَنُن عہد تہٕ یێمہِ سٍتـ̡ تٔمِس سٍتـ̡ تٔمِس سٍتـ̡ رٔٹِتھ روزِ۔\n5. مگر اگر تٔمۍ سُند مول أمِس دۅہہ بوزنُک اجازت دِیہِ۔ تٔمۍ سُند کانہہ تہِ وعدٕ، یا تٔمۍ سٕندِس بندھن سٍتـ̡ یێمہِ سٍتـ̡ تٔمۍ سُند روح بٔنِتھ چُھ، تہٕ خداوند کرِ أمِس معاف، کیازِ تٔمۍ سٕندِس مٲلہِ سٍتـ̡ چُھ أمِس نامنظور۔\n6. تہٕ اگر أمِس کانہہ خانٛدار آسہِ، ییلہ أمِس نِش وعدٕ کٔرِتھ، یا چُھس وُٹھہٕ سٍتـ̡ پَنُن روح بٔنِتھ دِنہٕ آمُت۔ {تٔمۍ کوٚر وعدٕ: ہیب۔ تٔمۍ سُند عہد اوس أمس پیٹھ}\n7.\\tتہٕ تٔمۍ سٕندِس خاوندس بوز تہٕ تٔمۍ سٕندِس دۅہس سٍتـ̡ سٍتـ̡ تسٕندِس سٍتـ̡ سٍتـ�\n8. مگر اگر تٔمۍ سٕندِس خانٛدارس تمہِ دۅہہ ییمہِ دۅہہ تٔمِس بوزنہٕ آمُت آسہِ۔ تیلہِ کرِ سُہ تٔمِس عہد یُس تٔمۍ سُند وعدٕ کورمُت اوس، تہٕ یُس تٔمۍ پننِس چپنہٕ سٍتـ̡ وُچھمُت اوس، ییمہ سٍتـ̡ تٔمۍ پنُن روح بٔنِتھ اوس، سُہ کرِ نہٕ کانہہ اثر: تہٕ خداوند کرِ أمِس معاف۔\n9.\\tمگر بیواہ سُند تہٕ طلاق دِنہٕ آمُت سُند پرٮ۪تھ وعدٕ گژھہِ أمِس خلاف کھڑا روزُن۔\n10. تہٕ اگر سُہ پننِس خانٛدار سٕندِس گرس مَنٛز عہد کٔرِتھ، یا پنُن روح کُنہِ قسمس سٍتـ̡ بند۔\n11.\\tتہٕ تٔمۍ سٕندِس خاوندس بوز تہٕ رٔٹِتھ رٔٹِتھ تہٕ دِژُن نہٕ أمِس نِش اِجازت: تیلہٕ گژھن تٔمۍ سٕندِس سارِنٕے عہد قٲیِم، تہٕ پرٮ۪تھ کانہہ بندٕ یُس أمِس سٍتـ̡ تٔمِس سٍتـ̡ رٔٹِتھ روزُن۔\n12.\\tمگر یێلہِ تٔمۍ سٕندِس خاوندس سٍتـ̡ یێلہِ یێلہِ سٍتـ̡ تٔمۍ سٕندِس عہدس مُتلق یُس تہٕ یُس تہٕ تٔمۍ سٕندِس نذرس مُتلق نیرِ، سُہ گژھہِ نہٕ تٔمِس سٍتـ̡ بٔنِتھ تہٕ یێلہِ تہٕ تٔمۍ سٕندِس خاوندس سٍتـ̡ یێلہِ تہٕ یێلہِ تہٕ تٔمۍ سٕندِس نَرس مُتعلِق یێلہِ تہٕ یێلہِ تہٕ تٔمۍ سٕندِس خاندارس سٍتـ̡ یێ تہٕ خداوند کرِ أمِس معاف۔\n13.\\tپریتھ عہد تہ پریتھ عہد تہ پریتھ عہد ہیکہِ تسند خاوند یہ قایم کرِتھ یا خاوند کرِ یہ کالعدم قرار دِتھ۔\n14.\\tمگر اگر تٔمۍ سُند خاوند دۅہدٕ دۅہہٕ أمِس سٍتـ̡ خاموش روزِ۔ امہ پتہ چھہ سہ تسند سٲری عہد قایم کران، یا تسند سٲری بند، یم تمس پیٹھ چھہِ: سہ چھہ تمن ہنز تصدیق کران، تکیازِ تمہِ دۅہہ ییلہ سہ بوزان اوس، سہ اوس تمس سیتۍ امن تھاوان۔\n15.\\tمگر اگر سُہ کُنہِ تہِ طریقہٕ سٍتـ̡ تِمن بوزنـ̡ بێکار کرِ۔ تیلہ کرِ سُہ تٔمۍ سٕنز بدکاری برداشت کرنہٕ۔\n16. یِم چھِ تِم قونوٗن، یِم خداوند موسىٰ سٕندِس مردس تہٕ زنانہِ درمِیان ، مٲلِس تہٕ کورِ درمِیان حُکُم دِژمٕتۍ۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. مدیانین ہٕندِس بنی اسرائیل سُند انتقام کرُن: تمہ پتہ گژھ تم پننین لوکن مَنٛز جمع کرنہٕ۔\n3.\\tتہٕ موسىٰ وۆن لُکن سٍتـ̡ وونُن زِ پانس سٍتـ̡ کٔرِو جنگہٕ خٲطرٕ ہتھیار تہٕ تِم گژھن مدیانن خلاف تہٕ مدیانُک رب سُند انتقام۔\n4. پریتھ قبیلہٕ منزٕ ساس ساس سٍتـ̡ {آف...: ہیب۔ قبیلک اکھ ساس، قبیلک اکھ ساس}\n5.\\tیێوَے سپٕز ساسہٕ بٔدۍ اِسرٲیلِیو منزٕ بێیہِ ساس تہٕ باہ ساس جنگہٕ خٲطرٕ ہتھیار بٔنِتھ۔\n6. تہٕ موسىٰ سوٗزۍ تِم جنگس مَنٛز، ساس قٔبیٖلہٕ، تِم تہٕ فینیحاس، یُس پادٕرۍ الیعزر سُند نیچو اوس، جنگس مَنٛز، مقدس سازٕ ہٮ۪تھ، تہٕ بُرٕ وُپھاونہٕ خٲطرٕ۔\n7. تہٕ تِمو کٔر مدیانن سٍتـ̡ جنگ، یێلہِ خداوند موسىٰ سُند حُکُم دِیُت۔ تہٕ تمو مارۍ سٲری مرد۔\n8.\\tتہٕ تِمو مٲرِتھ مدیانٕکۍ بادشاہ تہٕ باقٕے مارنہٕ آمٕتۍ۔ {یعنی}، ایوی تہٕ ریکیم، تہٕ زور، تہٕ حُر، تہٕ ربا، مدیانٕکۍ پانٛژ بادشاہ: بلعام تہِ اوس بیور سُند نیچو تہِ یِمو تلوار سٍتۍ مار۔\n9.\\tتہٕ بنی اسرائیلو رٔٹِتھ مدیانٕچ زنانہٕ تہٕ تِہٕندِس لۄکٹِس شُرۍ، تہٕ تِہٕندِس سارِنٕے چارواین تہٕ سارِنٕے چاروٕے تہٕ تِہُند سارِوٕے مال نِیُن۔\n10. تہٕ تِمو زٲلۍ پنٕنۍ تمام شہر یِمن منٛز تم روزان ٲسۍ، تہٕ پنٕنۍ تمام اصل قلعہٕ نارٕ سٍتۍ۔\n11. تہٕ تِمو نِش سارِوٕے غُنیمت تہٕ سارِنٕے شِکار، انسانن تہٕ درندن ہٕندِس سارِنٕے شِکار۔\n12. تہٕ تِمو أنۍ قٲد، تہٕ شِکار، تہٕ غنیمت موسیٰ تہٕ الیعزر کادٕن، تہٕ بنی اسرٲیلِچ جماعت نِش، موآب کِس مٲدانس مَنٛز خٲمس منز، یُس اردن {نزدیک} یریحا کِس خٲمس مَنٛز۔\n13. تہٕ موسیٰ تہٕ پادٕرۍ الیعازر تہٕ جمٲژ ہٕندۍ سٲری شہزادٕ دراو تِمن سٍتـ̡ مُلاقات کرنہٕ خٲطرٕ۔\n14.\\tتہٕ موسیٰ گۆو لشکر کین افسرن سٍتـ̡ شرارت، ساسہٕ بٔدۍ سٍتـ̡ کپتانن سٍتـ̡ تہٕ ہتہٕ بٔدۍ سٍتـ̡ کپتان، یُس جنگہٕ سٍتـ̡ آو۔ {جنگ: ہیب۔ میزبان}\n15.\\tتہٕ موسىٰ ووٚن تِمن زِ کیا ژیہ سارِنٕے زنانہٕ زندٕ بچٲومٕژ؟\n16. وُچھِو یِمو سٍتـ̡ بُلع سٕندِس مشورس سٍتـ̡ خداوند سٕندِس معاملس مَنٛز گُزٲر کرنہٕ آمُت، تہٕ خداوند سٕنزِ جماعتس مَنٛز گۆو وُپھ۔\n17. تێمہِ مۅکھہ مارُن پرٮ۪تھ کانہہ مرد یُس مردس سٍتـ̡ زانان آسہِ۔ {ام: ہیب۔ اکھ مرد}\n18.\\tمگر سارِنٕے زنانہٕ شُرۍ، یِمو نہٕ أمِس سٍتـ̡ أکِس مردس سٍتـ̡ زانان آسہِ، تِم تھٲوِو پانس خٲطرٕ زندٕ۔\n19. تہٕ یُس تہِ کٲنسہِ شخصس قتل کرُن، تہٕ یُس کٲنسہ تہِ مارُن آسہِ، تہٕ یُس تہِ کٲنسہِ مارنہٕ آمُت آسہِ، سٍتـ̡ کرُن پانس تہٕ سٔتِمہِ دۅہہٕ پاک کرُن۔\n20. تہٕ پَنٕنـ̡ سارِنٕے پَلَو، تہٕ سارِنٕے کامہِ سٍتـ̡ کٔرِو تہٕ سارِنٕے لٔکرِ ہٕندِس سٍتـ̡ صاف کٔرِو۔ {یہ...: ہیب۔ آلہٕ، یا، کھالن ہُند برتن}\n21. تہٕ الیعزر پادٕرۍ ووٚن جنگہٕ کین نفرن یُس جنگس منز گٔیہ، یہِ چُھ شریعت ہُند حکم یُس خداوند موسیٰ سُند حکم دِیُتمُت اوس۔\n22. صرف سۄن، تہٕ رۄپھ، پیتل، ششتٕر، ٹن تہٕ سیسہٕ،\n23.\\tپریتھ کانہہ چیز یُس نارس منز روزِ، تہٕ یہ گژھہِ نارس منز نیرُن، تہٕ یہ گژھہِ صاف روزُن، توتہِ گژھہِ یہ جدایی کِس آبس سٍتۍ پاک کرنہٕ۔\n24. تہٕ سٔتِمہِ دۅہہٕ گژھِو پَنٕنۍ پَنٕن، تہٕ پَتہٕ گژھِو خٲمَس مَنٛز۔\n25.\\tتہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n26.\\tیُس شِکارُک مجموعہ نِنہٕ آمُت چُھ، {انسانہٕ تہٕ درندٕ سٕندِس دۅشوے، تہٕ الیعازر پادٕر، تہٕ جماعتٕکۍ بٔڈۍ بابہٕ: {یہ...: حب۔ قید کٔرِتھ}\n27. تہٕ شِکارس کٔرِو دۄن حصن مَنٛز تقسیٖم۔ تِمن درمِیان یِمو تِمن پیٹھ جنگ کٔر، یِم جنگہٕ خٲطرٕ درٛاو، تہٕ سارنٕے جمٲژ درمِیان :\n28.\\tتہٕ جنگہٕ کِس مالہٕ سٕندِس خداہس خراج تحسین دِیُن: پانژَن ہتن ہُند اکھ روح، {دونوی} نفرن ہٕندِس تہٕ گَرَن ہٕندِس تہٕ گَرَن ہٕندِس تہٕ کۅکرَن ہُند اکھ روح۔\n29.\\tتِہٕندِس نصفہٕ سٍتـ̡ رٔٹِو تہٕ دِیُن پادٕرِ الیعزارس کُنـ̡ یێلہِ خداوند سٕندِ سٍتـ̡ نذرانہ سٍتـ̡ ۔\n30.\\tتہٕ بنی اسرٲیلـ̡ ہٕندِس نصف سٍتـ̡ چُھہ پنژاہ ہُند اکھ حصہٕ نِن، گاوُن، گُرِ ہُند تہٕ پرٮ۪تھ قٕسمٕکۍ درندَن ہُند، تہٕ دِیُن لاوِین یُس خداوند سٕندِس خیمہ سٍتـ̡ رٔٹِتھ تھاوان چُھ۔ {ریوڑ: یا، ژھاوٕل}\n31.\\tتہٕ موسیٰ تہٕ پادٕرۍ الیعزارن کٔر خداوند موسیٰ سُند حُکُم۔\n32.\\tتہٕ باقٕے شِکار یُس جنگی مردو رٔٹمُت اوس، سُہ اوس شیہ لچھ ساس ستتھ ساس تہٕ پانژھ ساس کۅکر،\n33.\\tتہٕ تریہ تہٕ باہ ساس بیف،\n34.\\tتہٕ تریہ ساس تہٕ اکھ ساس گَر،\n35.\\tتہٕ سارِوٕے ترٕہ ساس زنانہٕ یِمو نہٕ أمِس سٍتـ̡ مردس سٍتـ̡ زانان آسہِ۔\n36.\\tتہٕ یُس نصف حصہ یُس جنگس منز نیران اوس، اوس تریہ لچھ ساس تہٕ ترہ ساس تہٕ پانژھ ہتھ کۅکر۔\n37. تہٕ خداوند سُند خراج اوس شیہ ہتھ تریہ تہٕ پنداہ۔\n38.\\tتہٕ گۅپھ ٲسۍ ترہ شیہ ساس۔ یتھ منز رب سُند خراج تحسین {اوس} تریہ تہٕ باہ۔\n39. تہٕ گَرٕ ٲسۍ ترہ ساس پانژھ ہتھ۔ یتھ منز رب سُند خراج {اوس} تریہ تہٕ اکھ۔\n40. تہٕ شُراہ ساس۔ یمن منز رب سُند خراج {اوس} ترہ تہٕ زٕ نفر۔\n41. تہٕ موسىٰ دِیُت خراج ، یُس خداوند سُند کُدُن نذرانہ اوس، یُس خداوند موسیٰ سُند حکم اوس دِتمُت۔\n42.\\tتہٕ بنی اسرٲیلـ̡ ہٕندِس نصف سٍتـ̡ یُس موسىٰ ین جنگ کرن والین نفرن نِش تقسیم کورمُت،\n43.\\t(وۅنۍ اوس نصف جماعت تریہ لچھ تہٕ ترہ ساس تہٕ پانژھ ہتھ کۅکر،\n44.\\tتہٕ ترہ تہٕ شیہ ساس گاو،\n45. تہٕ ترٕہ ساس گَرٕ تہٕ پانژھ ہتھ\n46. تہٕ شُراہ ساس شخص؛)\n47.\\tبنی اسرٲیلـ̡ ہٕندِس نصف منزٕ تہِ نِیوُن موسیٰ پنژاہ ہُند اکھ حصہٕ، انسان تہٕ جانور سُند، تہٕ دیتُن لاوِین نِش، یِمو خداوند سٕندِس خیمہ ہُند ذمہ دار تھوو۔ یِتھ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت۔\n48.\\tتہٕ یِم افسر یِم ساسہٕ بٔدۍ لشکر، ساسہٕ بٔدۍ تہٕ ہتہٕ بٔدۍ کپتان، وٲتۍ موسیٰ سٕندِس نزدیک۔\n49.\\tتہٕ تِمو ووٚن موسیٰ سٍتـ̡ تہٕ چُھہ چُھہ تُہٕندِس خدمتگارن ہُند سُہ رقم رٔٹمُت یُس سٲنـ̡ سٍتـ̡ چُھہ، تہٕ اسہِ مَنٛز چُھہ نہٕ اکھ تہِ نفر کٔمی۔ {چارج: ہیب۔ اتھہٕ}\n50. تێمہِ کِنۍ چُھہ أسـ̡ خداوند سٕندِ خٲطرٕ اکھ قربانی، یُس پرٮ۪تھ أکِس انسانس سٍتـ̡ سۄنہٕ سٕندِس جواہرات، زنجیرن تہٕ کٔرِن، وٲج تہٕ گولہٕ سٍتـ̡ حٲصل سپدِ، یُس خداوند سٕندِ برونہہ کنہِ سانہِ روحن ہُند کفارہ دِنہٕ ییہِ۔ {گوٹن: ہیب۔ لٔب}\n51.\\tتہٕ موسیٰ تہٕ پادٕرۍ الیعزارن نِیوو تِمن ہُند سۄنہٕ، {حتیٰ کہ} سٲری بٔنِتھ جوٲہر۔\n52.\\tتہٕ یُس نذرانہ یُس تِمو خداوند سٕندِس خٲطرٕ پیش کٔر، ساسن ہٕندِس کپتانن تہٕ ہتن ہٕندِس کپتانن ہٕندِس سٍتـ̡ اوس شُراہ ساس ستھ ہتھ شیکل۔ {پیشکش: ہیب۔ ہیو پیشکش}\n53. ({تکیازِ} جنگی نفرو اوس غنیمت روٚٹمُت، پرٮ۪تھ کانہہ نفر اوس پانس خٲطرٕ۔)\n54.\\tتہٕ موسیٰ تہٕ الیعزار پادٕرۍ نیو ساسہٕ بٔدۍ تہٕ ہتن ہٕندِس کپتانن ہُند سون تہٕ أنِن جماعت کِس خیمہ خانس مَنٛز، یُس خداوند سٕندِس برونہہ کُن بنی اسرٲیلـ̡ خٲطرٕ یادگار اوس۔","1.\\tوُنہِ روبن سٕندِس شُرین تہٕ گاد سٕندِس شُرین نِش ٲس سٮ۪ٹھاہ بٔڈ چاروٲے تہٕ ییلہ یِمو یَزر سٕنز زمین تہٕ جلعادُک سرزمینہٕ وُچھ، سُہ جاے ٲس چارواین ہٕنز جاے ۔\n2.\\tگاد سٕندِ شُرۍ تہٕ روبن سٕندِ شُرۍ آیہِ تہٕ موسیٰ سٕندِس تہٕ پادٕرۍ الیعزر تہٕ جمٲژ ہٕندِس شہزادن سٍتـ̡ کتھ باتھ کٔرِتھ وونُن،\n3. عطاروتھ، تہٕ دیبون، تہٕ یزر، تہٕ نمرا، تہٕ ہیشبون، تہٕ الیلیہ، تہٕ شیبام، تہٕ نیبو، تہٕ بیون، {نمرا: تہِ وَننہٕ یِوان، بیتھنیمرا} {شیبام: تہِ وَننہٕ یِوان، شبمہ} {بیون: تہِ وَننہٕ یِوان، بعلمیون}\n4. {حتیٰ کہ} سُہ ملک یُس خداوند اسرٲیلِچ جماعت برونہہ کُن دِژمُت، {چُھ} چُھہ چارواین خٲطرٕ زمین، تہٕ چُھہ تہندِس خادمَن ہٕندِس چاروٲے سٍتـ̡\n5. اَمہِ مۄکھہٕ ووٚن تِمو زِ یێلہِ أسـ̡ تُہٕندِس نظرس مَنٛز فضل میلہِ، یێلہِ تُہٕندِس خدمتگارن دِنہٕ ییہِ، {تہٕ} اسہِ ہٕندِس اردنس پٲٹھـ̡ دِنہٕ۔\n6. تہٕ موسىٰ ووٚن گاد سٕندِس اولادس تہٕ روبن سٕندِس اولادس زِ کیا تُہٕندِ بٲے گژھن جنگس مَنٛز، تہٕ کیا تُہۍ یتہِ بِہِتھ؟\n7. تہٕ کیازِ چُھکھ بنی اسرٲیلِس دِل تتھ زمینس مَنٛز گژھنہٕ نِش رُکٲوِتھ یُس خداوند تِمن دِژمُت چُھ؟ {حوصلہ شکن: ہیب۔ بریک}\n8.\\tیِتھے پٲٹھۍ کوٚر تُہند مٲل ییلہ میہ تِم کدیشبرنیا پٮ۪ٹھٕ زمین وچھنہٕ خٲطرٕ سوٗزۍ۔\n9. یێلہِ تِم وادی اشکول کِس وادی تام وٲتِتھ زمین وُچھ، تِمو کٔر بنی اسرٲیلِک دِل حوصلہٕ شُدٕ، زِ تِم گژھن نہٕ تتھ زمینس مَنٛز گژُھن، یُس خداوند تمن دِژمُت اوس۔\n10. تہٕ خداوند سُند غصہٕ گۆو اَمی ساتہٕ، تہٕ سُہ وونُن قسم،\n11.\\tیُس وُہن وُہُن وُہُر وٲنسہِ پیٹھٕ یُس میہ ابراہیم، اسحاق تہٕ یعقوب سٍتـ̡ قسمہ دِوان چُھ، تِمن منز ہێکہِ نہٕ کانہہ تہِ زمین وُچھِتھ یُس بہٕ ابراہیم، اسحاق تہٕ یعقوبس سٍتـ̡ قسم دِوان چھُ۔ تکیازِ تِمو چُھ نہٕ پورٕ پٲٹھۍمیہ پیروی کٔرمٕژ: {پورٕ...: ہیب۔ میہ پتہٕ پورٕ}\n12.\\tیپھُنہٕ سُند نیچو کالب، تہٕ یشوع سُند نیچو بچٲوِو، کیازِ تِمو چُھ پوٗرٕ پٲٹھـ̡ خداوند سٕنز پیروی کٔرمٕژ۔\n13. تہٕ خداوند سُند غصہٕ گۆو اسرٲیلِس سٍتـ̡ دِنہٕ، تہٕ تٔمۍ کٔرٕن تِم ژتٲجی ؤرین بیابانن مَنٛز نژان، یوتام سُہ سارِوٕے نسل، یُس خداوند سٕندِس نظرس منز بد کار اوس کٔرمُت، ختم گٔیہِ۔\n14. تہٕ وُچھِو، تُہۍ چھِو پننین مٲلن ہٕندِس بدلہٕ گۅنہگارن ہٕندِس سٍتـ̡ ہُریراونہٕ آمٕتـ̡ یُس اسرٲیلس سٍتـ̡ خداوند سُند شدید غصہٕ ہُرراوُن۔\n15.\\tیێلہِ یێلہِ تُہۍ أمِس نِش پتھ پھیرِو، سُہ تراوِ بییہِ بیابانن مَنٛز۔ تہٕ تُہۍ کٔرِو یِم سارِنٕے لوٗکھ تباہ کٔرِتھ۔\n16.\\tتہٕ تِم وٲتۍ أمِس نزدیک، تہٕ وونُن، أسۍ بناوو یَتہِ پننین چارواین ہٕندِ خٲطرٕ کۅکرِ تہٕ پننین لۄکٹٮ۪ن ہٕندِ خٲطرٕ شہر۔\n17. مگر أسۍ گژھو پانہٕ بنی اسرائیلس برونہہ کُن ہتھیار بٔنِتھ تیار، یوٚت تام أسۍ تِمن تِمن ہٕنزِ جایہ أنِو: تہٕ سانۍ لۄکٕٹۍ بچہٕ روزن زمینہٕ کین بسکینن ہٕندِ وجہ سٍتـ̡ تارٕ بند شہرن مَنٛز۔\n18.\\tأسـ̡ ہێکہِ نہٕ پننین گھرن منز واپس یِن، یوتام نہٕ اسرٲیلِچ اولاد پرٮ۪تھ أکِس انسانس پنُن وراثت حٲصل کرِ۔\n19.\\tکیازِ اسہِ میلہِ نہٕ تِمن سٍتـ̡ یِمن سٍتـ̡ یِمن سٍتـ̡ اردنس سٍتـ̡ یا برونہہ کُن۔ تکیازِ سون وراثت چھہ اسہِ نش یتھ طرفہ اردن مشرقس کُن پیومت۔\n20. تہٕ موسىٰ ووٚن تِمَن زِ اگر تُہۍ یہِ کٲم کٔرِو، اگر تُہۍ خداوند سٕندِ برونہہ کُن ہتھیار ہیتھ جنگہٕ خٲطرٕ گژھِو،\n21. تہٕ یێلہِ سارِوٕے ہٕندِس دُشمن ہٕندِس دُشمن ہٕندِس برونہہ کُن ژٔلِتھ یێلہِ سُہ پَنُن دُشمن پانس برونہہ کُن ژٔلِتھ دِیہِ،\n22. تہٕ زمین گژھہِ خداوند سٕندِس برونہہ کُن زیر کرنہٕ۔ تَمہِ پَتہٕ گژھِو تُہۍ واپس یِو، تہٕ خداوند سٕندِس برونہہ کُن تہٕ اسرٲیلِس برونہہ کُن بے قصور روزِو۔ تہٕ یہِ زمین آسہِ خداوند سٕندِ برونہہ کُن تُہند قبضہٕ۔\n23. مگر یێلہِ نہٕ تۅہہِ یہِ کٔرِو، تێلہِ چُھہ تۅہہِ خداہس سٍتـ̡ گۅناہ کورمُت، تہٕ پژھہٕ پٲٹھـ̡ پى۪ٹھہٕ پى۪ٹھ۔\n24. پَنٕنـ̡ شُرین ہٕندِ خٲطرٕ بَناوُن تہٕ پَنٕنـ̡ کَرٕنـ̡ ہٕندِ خٲطرٕ تہٕ پَنٕنـ̡ تہٕ سُہ کٔرِو یُس پننہِ ٲسہِ منزٕ نیران چُھ۔\n25.\\tتہٕ گاد سٕندِ بچہٕ تہٕ روبن سٕندِ اولادَو کٔر موسیٰ سٕندِس سٍتـ̡ وَنُن زِ تُہٕندِس خادمَس کٔرِن میانہِ آغدٕ سُند حُکُم۔\n26.\\tسانۍ لۅکٹۍ، سانۍ زنانہٕ، سانۍ چاروِ تہٕ سانۍ سارِنٕے چاروٲے آسن جلعاد کین شہرن مَنٛز۔\n27. مگر تُہند خادم گژھن جنگہٕ خٲطرٕ مسلح پرٮ۪تھ کانہہ شخص، یِتھ کٔنۍ میانہِ آقا چُھ وَنان۔\n28.\\tیِمن مُتلق دِژ موسیٰ علیعزر کاہن، تہٕ نون سُند نیچو یشوع تہٕ بنی اسرائیل کین قبیلن ہٕندِس بٔڈِس بابن ہُند حُکُم:\n29. تہٕ موسىٰ ین ووٚن تِمن زِ اگر گاد سٕندِ اولاد تہٕ روبن سٕندِ بچہٕ یِن تۅہہِ سٍتـ̡ اردنس مَنٛز نیرن، پرٮ۪تھ کانہہ نفر گژھہِ خداہس برونہہ کُن جنگہٕ خٲطرٕ مسلح تہٕ زمین ییہ تۅہہِ برونہہ کُن زیر کرنہٕ۔ تیلہِ دِیُو تِمن گلعادٕچ زمین قبضہٕ خٲطرٕ:\n30. مگر اگر نہٕ تِم تۅہہِ ہٕندِس ہتھیار ہیتھ نیرِ، تِمن آسہِ کنعان کِس سرزمینس مَنٛز تِمن ہٕندِس ملکیتس منز۔\n31.\\tتہٕ گاد سٕندِس اولادَو تہٕ روبن سٕندِس اولادَو دِژ جواب دِتھ زِ یِتھ کٔنۍ خداوند چُھہ پننین بندن ووٚنمُت، تِتھۍ کٔرِو أسۍ تہِ۔\n32.\\tأسۍ کرو خداوند سٕندِ برونہہ کُن ہتھیار بند کٔرِتھ کنعان کِس سرزمینس مَنٛز، یُتھ زِ یَتھ طرفہٕ یُس اردن ہُند وَراثت آسہِ۔\n33.\\tتہٕ موسىٰ دِژ تِمن گاد کِس اولادس تہٕ روبن سٕندِس اولادس تہٕ یوسف سٕندِس نیچوِس منشہ سٕندِس نصفس قبیلس تہٕ اموری ہُند بادشاہ سِحون سٕنز بادشٲہی تہٕ بشان کِس بادشاہ اوگ سٕنزِ بادشٲہی تہٕ بٔٹھِس سٍتـ̡ دِژ ملکٕکۍ شہر۔\n34.\\tتہٕ گاد سٕندیو بچو بنوو دیبون، تہٕ اتاروت تہٕ آرویئر،\n35.\\tتہٕ عتروت، شوپھان تہٕ جازر، تہٕ جوگبہہ، {یَظر: یَتھ تہِ وَننہٕ یِوان چھُ}\n36.\\tتہٕ بیتھنیمرہ تہٕ بیتھران، تار لگٲوِتھ شہر: تہٕ کۅکرِ ہٕندِ خٲطرٕ۔ {بیتھنیمرا: نمرہ تہِ ونان چھِ}\n37.\\tتہٕ روبن سٕندیو بچو بنوو ہیشبون، تہٕ الیالہ، تہٕ کِرجاتھیم۔\n38.\\tتہٕ نیبو تہٕ بعلمیون (تِہند ناو آو بدلاونہٕ،) تہٕ شِبمہ: تہٕ دِتُکھ تِمن شہرن ہٕندِ باقٕے ناو یِم تمو تعمیر کٔرۍ۔ {دِیُت...: ہیب۔ تِم ٲسۍ شہرن ہٕندۍ ناو ناوو سٍتۍ وَنان}\n39.\\tتہٕ منسیٰ سٕندِس نیچو ماکیر سٕندِ اولادٕ گٔیہِ جلعادس کُن تہٕ رٔٹِتھ کٔرِکھ امورِس نِش یُس اتھ مَنٛز اوس۔\n40. تہٕ موسىٰ دِژ گلعاد مناسی سٕندِس نیچوِس مکھیرس ۔ تہٕ سُہ اوس اَتھ منز روزان۔\n41.\\tتہٕ منسیٰ سُند نیچو یائر گۆو تہٕ یِمن ہٕندِس لۅکٹِس شہرس پیٹھ قبضہ کٔرِتھ وَنُن حَوثجیر۔\n42.\\tتہٕ نوبہ گوٚو کیناتھ تہٕ اَمہ کِس گامس پیٹھ قبضہٕ تہٕ وَنُن نوبہ پننہِ ناوٕ پیٹھ۔","1. یِم چھِ بنی اسرائیل ہُند سفر، یُس موسیٰ تہٕ ہارون سٕندِس اتھہٕ سٍتـ̡ پَنٕنـ̡ لشکر ہیتھ مصر کِس سرزمینہٕ پیٹھٕ درٛاو۔\n2. تہٕ موسىٰ کٔر خداوند سٕندِ حُکمہٕ مطٲبق تِہٕندِ سفرٕ مُطٲبق تہٕ یِمن ہُند سفر چُھ تِہندِ نیرنہٕ مُطٲبق۔\n3. تہٕ تِم گٔیہِ گۄڈنِکِس رٮ۪تس مَنٛز رمیسیس نِش روانہٕ، گۄڈنِکِس رٮ۪تہٕ کِس پنٛدٲہمہِ دۅہہٕ ۔ پَتہٕ دۅہہ گٔیہِ اسرائیلٕکۍ بنی سارِنٕے مصری نظرن برونہہ کُن تھدِ اتھہٕ سٍتـ̡ نیٚبر۔\n4. تکیازِ مصریو کٔر سٲری گۅڈنچہ اولاد دفن، یُس خداوند تمن منز مارٲومُت اوس، تہندِس خداہس پیٹھ تہِ دِژ فیصلہٕ۔\n5.\\tتہٕ بنی اسرٲیلِیو ہٹٲوِتھ رمیسس نِش تہٕ کٔرِکھ سوکوتھس مَنٛز۔\n6.\\tتہٕ تِم دراو سوکوتھ پیٹھ، تہٕ درٛاو ایتھمس مَنٛز، یُس بیابان کِس اندس مَنٛز چُھ۔\n7.\\tتہٕ تِمو ہیوٚت ایتھمس پیٹھ، تہٕ دُبارٕ پھیُر پیہہیروتھس کُن، یُس بعلزیفونس برونہہ کُن اوس، تہٕ تِمو کٔر مگڈولس برونہہ کُن۔\n8.\\tتہٕ تِم دراو پِہاہیروتھس برونہہ کُن، تہٕ گٔیہِ سمندرٕ کِس وسطس منز، بیابانن مَنٛز، تہٕ گٔیہِ ترٮ۪ن دۄہن ہُند سفر ایتھم کِس بیابانس مَنٛز، تہٕ گٔیہِ ماراہس مَنٛز۔\n9.\\tتہٕ تِمو ہیوٚت مارہ پیٹھ، تہٕ آیہ ایلیم کُلِس کُلۍ۔ تہٕ تِمو کٔر تتہِ پچ۔\n10.\\tتہٕ تِمو ژٔلِتھ ایلیم نِش تہٕ بحیرہ احمرس نِش ڈیرٕ ترٲوِتھ۔\n11. تہٕ تِمو ژٔٹِتھ بحیرہ احمر پیٹھ، تہٕ گۅناہ کِس بیابانس مَنٛز ڈیرٕ ترٲوِتھ۔\n12.\\tتہٕ تِمو دراو گۅناہ کِس بیابانہٕ منزٕ نیبر تہٕ ڈوفکاہَس مَنٛز ڈیرٕ ترٲوِتھ۔\n13.\\tتہٕ تِمو دراو ڈوفکہٕ پیٹھٕ تہٕ کوٚرُکھ الوشس مَنٛز ڈیرٕ۔\n14.\\tتہٕ تِمو ژٔلِتھ الوش نِش تہٕ رفیدیمس مَنٛز ڈیرٕ ترٲوِتھ ییتہِ نہٕ لُکن ہٕندِ خٲطرٕ آب اوس نہٕ۔\n15.\\tتہٕ تِم دراو رِفیدِم نِش تہٕ گٔیہِ سینا کِس بیابانس مَنٛز۔\n16.\\tتہٕ تِمو ہیوٚت سینا کِس صحرا منزٕ تہٕ کِبروتھٹاواہ کُن دِنہٕ۔ {کِبروتھاواہ: یعنی ہوس ہٕنز قبر}\n17.\\tتہٕ تِم دراو کِبروتھتاوہ پیٹھٕ تہٕ کٔرِکھ ہازیروتس مَنٛز ڈیرٕ۔\n18.\\tتہٕ تِم دراو ہزاروتھ پٮ۪ٹھٕ تہٕ رِتھمہِ کِس مَنٛز گٔیہِ۔\n19.\\tتہٕ تِم دراو رِتھمہٕ پیٹھ، تہٕ رِمونپاریزس کُن گٔیہِ۔\n20.\\tتہٕ تِم دراو رِمونپاریز پیٹھ، تہٕ لبناہس مَنٛز گٔیہِ۔\n21.\\tتہٕ تِمو لِبنہٕ نِش ہٹٲوِتھ رِساہَس کُن دِنہٕ۔\n22.\\tتہٕ تِمو گٔیہِ رِصہٕ پٮ۪ٹھٕ سفر تہٕ کیہلاہس مَنٛز گٔیہِ۔\n23.\\tتہٕ تِم گٔیہِ کیہِلاتھا پٮ۪ٹھٕ تہٕ لٔگِتھ شافر پہاڑس منٛز۔\n24.\\tتہٕ تِمو ژٔلِتھ شافر پہاڑ پیٹھٕ تہٕ کوٚرُکھ ہراداہس مَنٛز ڈیرٕ۔\n25.\\tتہٕ تِمو ہٲرِتھ ہرادہ منزٕ تہٕ کٔرِکھ مکھیلوتھس مَنٛز۔\n26.\\tتہٕ تِمو ہیوٚت مکھیلوتھ پیٹھٕ تہٕ کوٚرُکھ تہتھس مَنٛز ڈیرٕ ترٲوِتھ۔\n27.\\tتہٕ تِمو درٛاو تہٕ تاراہس کُن دِنہٕ۔\n28.\\tتہٕ تِمو ہیوٚت تارہ نِش تہٕ کٔرِکھ مِتھکاہَس مَنٛز۔\n29.\\tتہٕ تِم گٔیہِ مِتھکہٕ پٮ۪ٹھٕ تہٕ ہشموناہس مَنٛز گٔیہِ۔\n30. تہٕ تِم دراو ہشمونہ پیٹھ، تہٕ کوٚرُکھ موسیروتھس مَنٛز ڈیرٕ۔\n31.\\tتہٕ تِم گٔیہِ موسیروتھ پٮ۪ٹھٕ روانہٕ، تہٕ گٔیہِ بینیجاکانَس مَنٛز۔\n32.\\tتہٕ تِمو ہیوٚر بینیجاکان پٮ۪ٹھٕ تہٕ کوٚرُکھ ہورہیگِدگڈس مَنٛز ڈیرٕ۔\n33.\\tتہٕ تِم گٔیہِ ہورہیگِڈ گُرٕ پٮ۪ٹھٕ تہٕ کٔرِکھ جوتباتھ مَنٛز۔\n34.\\tتہٕ تِمو ژٔلِتھ تہٕ کٔرِکھ ایبروناہَس مَنٛز ڈیرٕ۔\n35. تہٕ تِم دراو ایبرونہ پیٹھ، تہٕ کوٚرُکھ ایزیونگبرس مَنٛز ڈیرٕ۔\n36.\\tتہٕ تِمو ژٔلِتھ ژٔلِتھ زِن کِس بیابانس مَنٛز، یُس {قادیش} چھُ۔\n37.\\tتہٕ تِمو گٔیہِ کادیش پؠٹھٕ تہٕ کٔرِکھ ادوم کِس سرزمینہٕ کِس اندس مَنٛز ہور پہاڑس مَنٛز۔\n38.\\tتہٕ ہارون پادٕرۍ ووت خداوند سٕندِس حُکمس سٍتـ̡ کُنہِ تہِ سٍتـ̡ پٲٹھـ̡ پۆنژمہِ ریتہٕ کِ\n39.\\tتہٕ ہارون اوس ہتھ وُہُن تریہ وُہُر ییلہ سُہ ہور کِس پہاڑس مَنٛز مٔر۔\n40.\\tتہٕ بادشاہ عراد کنعانی، یُس جنوبس مَنٛز کنعان کِس سرزمینس مَنٛز روزان اوس، بوز بنی اسرائیلٕچ یِنٕچ خبر ۔\n41.\\tتہٕ تِم دراو ہور پہاڑ پیٹھ، تہٕ گٔیہِ زلموناہس مَنٛز۔\n42.\\tتہٕ تِم دراو زالمونہٕ پیٹھٕ تہٕ گٔیہِ پونون کُن۔\n43.\\tتہٕ تِم دراو پونون پٮ۪ٹھٕ تہٕ اوبوتھس منز دِنہٕ۔\n44.\\tتہٕ تِم دراو اوبوت پیٹھٕ تہٕ موآب کِس سرحدس پیٹھ گٔیہِ اجیباریم کِس علاقس مَنٛز۔ {اجیباریم: یا، اباریم کِس انبار}\n45.\\tتہٕ تِم دراو اِیم پٮ۪ٹھٕ تہٕ دِبونگڈس کُن گٔیہِ۔\n46.\\tتہٕ تِمو ہیوٚت دیبونگڈ پیٹھٕ تہٕ کوٚرُکھ المندیبلتھیمس مَنٛز ڈیرٕ۔\n47.\\tتہٕ تِمو ہیوٚت المندیبلتھیم پیٹھ، تہٕ نیبو برونہہ کُن کٔرِکھ اباریم کِس پہاڑن مَنٛز۔\n48.\\tتہٕ تِم دراو اباریم کِس پہاڑو پیٹھ، تہٕ گٔیہِ اردن {نزدیک} یریحو کِس موآب کِس مٲدانس مَنٛز۔\n49.\\tتہٕ تِمو کٔر اردن کُن، بیت جیسموت پیٹھہٕ موآب کِس مٲدانس مَنٛز ابیلشِتِم تام۔ {Abelshittim: یا، شِٹِمٕکۍ مٲدان}\n50. تہٕ خداوند کٔر موآب کِس میدانس مَنٛز یریحہ کِس نزدیک، موسیٰ سٍتـ̡ وونُن،\n51.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کرو تہٕ تِمن ونُن، ییلہ تم اردن پیٹھٕ کنعان کِس سرزمینس مَنٛز منتقل گژھِو۔\n52. تیلہِ کٔرِو تِہٕندِس سارِنٕے بسکیٖن دِنہٕ وٲلِس پانس برونہہ کُن ژٔلِتھ، تہٕ تِہٕنزِ سارِنٕے تصویرٕ تباہ کٔرِو، تہٕ تِہٕنزِ سارِنٕے تھدِ جایہِ ژٔٹِتھ کٔرِو۔\n53. تہٕ تم کرو زمینہٕ کین بسکینن نِش بے دخل تہٕ اَتھ مَنٛز روزُن، کیازِ مے چھے ژے زمین دِژمٕژ یُس اتھ پیٹھ قبضہ کرنہٕ خٲطرٕ دِژمُت۔\n54. تہٕ تُہۍ کٔرِو زمین پننین خاندانن مَنٛز وراثتہٕ خٲطرٕ قرعہٕ کٔرِتھ: {تہٕ} یوتاہ زیادٕ وراثت دِیُو، تہٕ کم وراثت دِیُو: پرتھ أکِس شخصہٕ سُند {وراثت} گژھہِ تتھ جایہِ یتہِ تٔمۍ سُند لُٹ پییہِ۔ پننین آباؤ اجدادن ہٕندِ قبیلہٕ مطٲبق گژھہِ تۅہہ وٲرث۔ {مزید دِیو...: ہیب۔ تٔمۍ سُند وراثت ضرب کرُن} {کم دِیُن...: ہیب۔ پنن وراثت کم کرُن}\n55.\\tمگر اگر نہٕ تۅہہ زمینہٕ کین بسکینن پانس برونہہ کُن کڈِتھ کٔرِو۔ تیلہ گژھہِ یہ سپدِ، یُس تہِ تۅہہ یِمن نِش روزان چھُ، تم گژھن تۅہہِ اچھن منز چُھکھ تہٕ تۅہہِ اندۍ پکھۍ کانٹۍ، تہٕ تۅہہِ تتھ زمینس منز یُس تہِ روزان چھِو۔\n56.\\tامہ علاوہ گژھہِ یہ سپدُن، {یہ} بہٕ کرٕ ژے سٍتۍ، یتھہ پاٹھۍ میہ تمن سٍتۍ کرُن سونچ۔","1. تہٕ خداوند دِژ موسیٰ سٍتـ̡ وَنُن،\n2. بنی اسرٲیلِس کٔرِو حُکُم تہٕ تِمن ونُن، ییلہ تم کنعان کِس سرزمینس مَنٛز وٲتِو۔ (یہِ {چُھ} سُہ زمین یُس توے وراثتس مۅکھہٕ وَسنہٕ خٲطرٕ یِیہِ، {حتیٰ کہ} کنعانٕچ سرزمین تہٕ اَمہ کِس ساحلس سٍتۍ:)\n3. تیلہِ گژھہِ تُہند جنوبُک علاقہٕ زِن بیابان پیٹھٕ ایڈوم کِس بٹھس سٍتـ̡ تہٕ تُہند جنوبی سرحد آسہِ نوٗنہٕ سمندرُک نیبر بٹھہٕ مشرقس کُن۔\n4.\\tتہٕ تُہند سرحد گژھہِ جنوبہ پیٹھہ اکرب کِس کھسنس کُن پھیرِ، تہٕ زینس کُن گژھہِ تہ اَمہ کُن گژھہِ جنوبہٕ پیٹھہٕ کادیشبرنیاہس کُن، تہٕ گژھہِ ہزاردرس کُن تہٕ ازمون کُن گژھِ۔\n5. تہٕ سرحد گژھہِ ازمون پیٹھہ دریائے مصر تام اکھ کمپاس اننہٕ، تہٕ اَمہ منزہ نیرن وول گژھہِ سمندرس کُن۔\n6.\\tتہِ {یتھے پاٹھۍ}مغربی سرحدس پیٹھ تہِ آسہِ تۅہہِ بٔڈ سمندر تہِ: یہ آسہِ تُہند مغربی سرحد۔\n7. تہٕ یِہ آسہِ تُہند شمٲلی سرحد: عظیم سمندرٕ پیٹھٕ کٔرِو تۅہہ ہور پہاڑ کُن اشارٕ:\n8.\\tکوہ کوہ پیٹھہ گژھ تہِ پننہِ سرحدس پیٹھ حمتھ کِس دروازس تام اشارہ کرُن۔ تہٕ سرحد نیبر گژھن زیدادس کُن:\n9.\\tتہٕ سرحد گژھہِ ظفرون کُن، تہٕ اَمہِ منزٕ نیرُن گژھہِ ہزارنَس کُن: یِہ آسہِ تُہند شمٲلی سرحد۔\n10.\\tتہٕ تُہۍ کٔرِو پننِس مشرِقی سرحدس ہُند اِشارٕ ہزارنَن پٮ۪ٹھٕ شیفامس تام:\n11.\\tتہٕ بٔٹھۍ گژھہِ شیفام پیٹھہ ربلہ تام بٔنِتھ عین کِس مشرقس کُن۔ تہٕ سرحد گژھہِ وسۍ، تہٕ واتہِ چنیرتھ کس سمندرس کِس اندس تام مشرقس کُن: {سمندرُک طرف: ہیب۔ سمندرُک کندھ}\n12.\\tتہٕ سرحد گژھہِ اردن کُن تہٕ اَمہ منزٕ نیرُن گژھہِ نوٗنہٕ سمندرس کُن، یۅہے آسہِ تُہند سرزمین۔\n13. تہٕ موسىٰ دِیُت بنی اسرٲیلِس حُکُم زِ یہِ چُھ سُہ زمین یُس تۅہہِ قرعہ اندازی سٍتـ̡ وٲرث دِنُک حُکُم دِیُن، یُس خداوند نَو قبیلن تہٕ نصف قبیلس دِنُک حُکُم دِیُتمُت چھُ۔\n14.\\tروبن سٕندِس اولادَن ہٕندِس قبیلس تہٕ گاد سٕندِس قبیلس مُطٲبق چُھ تِمن ہٕندِس مٲلن ہٕندِس گرٕ مُطٲبق تہٕ گاد سٕندِس قبیلس مُطٲبق چُھ تِمن ہُند وراثت حٲصل کورمُت۔ تہٕ مناسہ کِس نصف قبیلس چُھ پنُن وراثت حٲصل کورمُت:\n15.\\tدۅشوے قبیلہ تہ نصف قبیلہ چھہ اتھ طرفہ اردن {نزدیک} یریحہ کس مشرقس کُن آفتاب کھسنہٕ کُن پنُن وراثت حٲصل کورمُت۔\n16.\\tتہٕ خداوند کٔر موسیٰ سٍتـ̡ کتھ کٔرِتھ،\n17.\\tیِم چھِ تِمن نفرن ہٕندِ ناو یِم تۅہہِ سٍتـ̡ زمین تقسیم کرِ: الیعزر پادٕر، تہٕ یشوع نون سُند نیچو۔\n18. تہٕ تُہۍ نِو پرٮ۪تھ قبیلُک اکھ شہزادہٕ، یُس وراثتس سٍتـ̡ زمین تقسیم کرنہٕ خٲطرٕ۔\n19.\\tتہٕ یِمن ہٕندِ ناو چھِ: یہوداہ کِس قبیلہٕ سٍتـ̡ کالب، یپھُنہٕ سُند نیچو۔\n20.\\tتہٕ شمعون سٕندِس اولادَن ہٕندِس قبیلس منز، امیہود سُند نیچو شیموئیل۔\n21. بینجمن قبیلہٕ منز، ایلیداد چِسلون سُند نیچو۔\n22.\\tتہٕ دان سٕندٮ۪ن شُرین ہُند قٔبیٖلُک شہزادٕ، بُکی یُس جوگلی سُند نیچو۔\n23.\\tیوسف سٕندِس اولادَن ہُند شہزادٕ، منسیٰ سٕندِس بچن ہٕندِس قبیلہٕ خٲطرٕ، حنیئل یُس ایفود سُند نیچو۔\n24.\\tتہٕ افریم سٕندِس اولادَن ہٕندِس قبیلُک شہزادہ، شیفتان سُند نیچو کیموئیل۔\n25.\\tتہٕ زبولون سٕندٮ۪ن بچن ہٕندِس قبیلُک شہزادہ، پرناخ سُند نیچو الیزافان۔\n26.\\tتہٕ عیساکار سٕندٮ۪ن بچن ہٕندِس قبیلُک شہزادہ، پالٹیئل یُس عزان سُند نیچو۔\n27.\\tتہٕ آشر سٕندٮ۪ن بچن ہٕندِس قبیلُک شہزادہ، شیلومی سُند نیچو۔\n28.\\tتہٕ نفتالی ہٕندِس بچن ہٕندِس قبیلُک شہزادہ، امیہود سُند نیچو پیڈاہل۔\n29.\\tیِم چھِ یِم خداوند یِمن کنعان کِس سرزمینس مَنٛز بنی اسرٲیلِس وَرثس بٲگراونُک حُکُم دِیُتمُت۔","1. تہٕ خداوند کٔر موآب کِس مٲدانس مَنٛز یریحہ کِس نزدیک، موسیٰ سٍتـ̡ وونُن،\n2. بنی اسرٲیلِس دِیُن حُکُم زِ تِم دِن لاوِین پَنٕنـ̡ شہرن ہٕندِس وراثتس مَنٛز روزن۔ تہٕ تُہۍ دِیِو لاوِین ہٕندِس مضافاتس أندۍ پٔکۍ شہرن خٲطرٕ۔\n3. تہٕ شہرن منز روزن پزِ تِمن منز روزُن۔ تہٕ تِمن ہٕندِ مضافاتی علاقہٕ آسہِ تِہندِ چارواین تہٕ تِہندِ مالہٕ خٲطرٕ تہٕ سارِنٕے درندَن ہٕندِ خٲطرٕ۔\n4. تہٕ شہرن ہٕندِس مضافاتی علاقس یُس تم لاوِین دِیِو، شہرٕچ دیوارٕ پیٹھٕ تہٕ نیبر کُن اکھ ساس کیوبِٹ وٲتِتھ۔\n5.\\tتہٕ شہرٕ نیبر مشرقس طرفہٕ زٕ ساس کیوبٹ، جنوبس طرفہٕ زٕ ساس کیوبٹ، تہٕ مغرب طرفہٕ زٕ ساس کیوبٹ تہٕ شمالس طرفہٕ زٕ ساس کیوبٹ۔ تہٕ شہر آسہِ درمیان: یِہ آسہِ تِمن خٲطرٕ شہرن ہٕندِس مضافاتس منز۔\n6. تہٕ یِمن شہرن مَنٛز یِم تُہۍ لاوِین دِیِو، تِمن مَنٛز گژھن پناہ دِنہٕ خٲطرٕ شےٚ شہر، یِم تُہۍ مُقٲمی سٕندِ خٲطرٕ مقرر کٔرِو، یُس سُہ ژلِتھ ژلِتھ تہٕ تِمن سٍتـ̡ ژٲجی تہٕ زٕ شہر شٲمل کٔرِو۔ {تمن خٲطرٕ...: ہیب۔ تمن پیٹھۍ دِیُن}\n7. {توتہِ} تِم سٲری شہر یِم تُہۍ لاوِین دِیِو، تِم گژھن تِمن ہٕندِس مضافاتس سٍتـ̡ دِنہٕ۔\n8. تہٕ یِم شہر تُہۍ دِیِو، تِم گژھن بنی اسرٲیلِن ہٕندِس قبضس مَنٛز، یِمن نِش واریاہ دِیِو۔ مگر یِمو سٍتـ̡ چُھہ کم دِنہٕ آمُت: پرٮ۪تھ کانہہ دِیہِ پَنُن شہرٕ لیوِین دِنہٕ یُس أمِس وَرثس مُطٲبق دِنہٕ یُس أمِس وَرثس مُطٲبِق دِیہِ۔ {وہ...: ہیب۔ تِم چِھ وراثتس منز میلان۔\n9. تہٕ خداوند ووٚن موسیٰ سٍتـ̡ وَنُن،\n10. بنی اسرٲیلِس سٍتـ̡ کتھ کرو تہٕ تِمن ونُن، ییلہ تم اردن کِس سرزمینس پیٹھ کنعان کِس سرزمینس مَنٛز یِو۔\n11. تیلہٕ کٔرِو تُہۍ پنٕنۍ شہر پننہِ خٲطرٕ پناہ گاہٕکۍ شہر مقرر کٔرِتھ۔ تاکہ قاتل گژھہِ تتہِ ژلِتھ، یُس کانہہ تہِ شخص بے خبری منز ماران چھُ۔ {at...: Heb. غلطی ذریعہ}\n12. تہٕ تِم گژھن انتقام نِش پناہ خٲطرٕ توے شہر۔ زِ انسان قاتل گژھہِ نہ مرُن، یوٚت تام نہ سُہ جمٲژ برونہہ کنہِ فٲصلس منز کھڑا سپدِ۔\n13. تہٕ یِمن شہرن مَنٛز یِم تُہۍ شےٚ شہر دِیِو، یِمن ہٕندِس پَنٕنـ̡ پۯاوٕنـ̡ ۔\n14. یێمہِ طرفہٕ دِیُن اردن تریہ شہر، تہٕ کنعان کِس سرزمینس مَنٛز تریہ شہر دِن، یُس پناہ گاہک شہر آسن۔\n15.\\tیِم شیہ شہر گژھن بنی اسرٲیلـ̡ ہٕندِ خٲطرٕ، تہٕ یِمن مَنٛز روزن وٲلِس سٍتـ̡ روزن وٲلِس خٲطرٕ پناہ گاہ۔\n16.\\tتہٕ اگر سُہ أمِس ششتٕرِ ہٕندِ آلہٕ سٍتـ̡ مارِ، سُہ چُھہ قاتل: قاتل یِیہِ یٔقیٖنی طور مارنہٕ۔\n17. تہٕ اگر سُہ أمِس کٔنہِ کٔنہِ لگٲوِتھ مارِ، تہٕ سُہ مَرِ، سُہ چُھ قاتل: قاتل یِیہِ یٔقیٖنی طور مارنہٕ۔ {with...: Heb. اَتھٕ کِس کٔنہِ سٍتۍ}\n18.\\tیا اگر سُہ لٔکرِ ہتھیار سٍتـ̡ مارِ تہٕ سُہ مرُن، سُہ چُھ قاتل: قاتل گژھہِ یقینا مارنہٕ۔\n19.\\tخونُک انتقام لینے وول کرِ قاتل پانہ مارُن: ییلہ سُہ أمِس مِلِہ، سُہ کرِ سُہ مٲرِتھ۔\n20. مگر اگر سُہ أمِس نفرتُک زور دِیہِ، یا انتظار کٔرِتھ أمِس کُن دِیہِ، سُہ مرُن۔\n21. یا دُشمن سٍتـ̡ دِیُن أمِس اَتھٕ سٍتـ̡ مارُن، یُس أمِس مارُن آسہِ۔ {کیازِ} چُھ سُہ {چُھ} اکھ قاتل: خونُک انتقام کرن وول کرِ قاتلس مٲرِتھ، ییلہِ سُہ أمِس سمکھِ۔\n22. مگر اگر سُہ أمِس اچانک دُشمن ورٲے دِیہِ، یا أمِس پیٹھ کانہہ چیز تراوُن آسہِ،\n23.\\tیا کُنہِ تہِ کٔنہِ سٍتـ̡ یێمہِ سٍتـ̡ انسان مرُن، یێمہِ سٍتـ̡ نہٕ أمِس سٍتـ̡ مٔرِتھ، تہٕ سُہ چُھہ نہٕ أمِس دُشمن سٍتـ̡ مَرُن، تہٕ سُہ اوس نہٕ تٔمِس دُشمن سٍتـ̡ نَہ تٔمِس نِش دِنہٕ یِ\n24. تیلہِ کرِ جماعت یِمن فیصلن مطٲبق قاتل تہٕ خونُک انتقام لینے وٲلِس درمیان فٲصلہٕ:\n25. تہٕ جماعت کرِ قاتل خونُک انتقام لینے وٲلِس اتھہٕ نِش نجات تہٕ جماعت کرِ سُہ تٔمۍ سٕندِس پناہ گاہٕ کِس شہرس مَنٛز واپس، یتہِ سُہ ژلنہٕ آمُت اوس، تہٕ سُہ روزِ اَتھ مَنٛز بٔڈِس پادٕرۍ سٕندِس مرنس تام، یُس مُقدس تیٖلہٕ سٍتـ̡ مسح کرنہٕ آمُت اوس۔\n26.\\tمگر اگر قاتل کُنہِ تہِ وِزِ پننہِ پناہ گاہِ ہٕندِس شہرس کِس سرحدس نیبر یِیہ، ییتہِ سُہ ژلِتھ آسہِ۔\n27.\\tتہٕ خونُک انتقام کرن وول چھُ أمِس پننہِ پناہ گاہٕ کِس شہرٕچ سرحدٕ ورٲے ژھٲنڈِتھ، تہٕ خونُک انتقام کرن وول چھُ قاتل ماران۔ سُہ گژھِ نہٕ خونُک قصوروار آسُن: {یہ...: ہیب۔ تس گژھہِ نہ کانہہ خون}\n28.\\tتکیازِ تس گژھہِ پنہٕ نِس پناہ گاہٕ کِس شہرس مَنٛز روزُن، مگر بڈِ پادٕرۍ سٕندِ مرنہٕ پتہٕ گژھہِ قاتل پننہِ ملکِس مَنٛز واپس۔\n29.\\tتێلہِ گژھن یِم {چیز} تۅہہِ سارِنٕے گھرن مَنٛز تۅہہِ سٍتـ̡ فیصلہٕ کِس قانونس مۅکھہٕ۔\n30. یُس تہِ کٲنسہِ شخصس قتل کرِ، قاتل گژھہِ گواہ سٕندِ دٔسۍ مارنہٕ یُن، مگر اکھ گواہ گژھِ نہٕ کٲنٛسہِ شخصس خلاف گوٲہی دِنہٕ۔\n31.\\tامہِ علاوہ گژھہِ نہ قاتل سٕنزِ زندگی خٲطرٕ کانہہ تسلی حٲصل کٔرتھ، یُس موتُک قصوروار آسہِ، مگر سُہ گژھہِ یقینا موت دِنہٕ۔ {قصوروار...: ہیب۔ مرنس منز غلطی}\n32. تہٕ یُس تٔمۍ سٕندِس پناہ گاہٕ کِس شہرس کُن ژلِتھ آسہِ، تہٕ سُہ گژھہِ پادٕرۍ سٕندِس مرنس تام زمینس منز روزنہٕ خٲطرٕ دُبارٕ روزُن۔\n33.\\tتێلہِ کٔرِو نہٕ سُہ زمینہٕ آلودہ کٔرِتھ یتھ مَنٛز تہٕ یێلہِ سٍتـ̡ یێلہِ سٍتـ̡ چُھہ زمینہٕ ناپاک سپدان تہٕ زمینہٕ ہێکہِ نہٕ یُس خونہٕ سٍتـ̡ یێلہِ یێلہِ سٍتـ̡ {زمین ہیکہِ نہ...: ہیب۔ زمینُک کانہہ کفارہ ہیکہِ نہٕ ٲسِتھ}\n34. تَمہِ مۄکھٕ کٔرِو نہٕ سُہ زمینہٕ ناپاک یَتھ مَنٛز بہٕ روزان چھُس، یێلہِ بہٕ چھُس یێلہِ بہٕ بَسان۔","1. تہٕ جلعاد سٕندٮ۪ن بچن ہٕندِس خاندانن ہٕندِس بٔڈۍ باپ یُس مکیر سُند نیچو، یُس مناسہ سُند نیچو، یوسف سٕندٮ۪ن نیچوین ہٕندِس خاندانس منز، آو نزدیک، تہٕ موسیٰ سٕندِس برونہہ کُن کتھ کٔرٕن، یُس بنی اسرٲیلِس ہٕندِس بٔڈِس بابن ہٕندِس بٔڈِس سٍتـ̡ اوس۔\n2. تہٕ تِمو ووٚن، خداوند دِیُت میٲنِس آقا سُند حُکُم زِ سُہ دِیہِ زمینہٕ اِسرٲیلِس سٍتـ̡ قرعہٕ دِنہٕ خٲطرٕ، تہٕ میٲنِس مٲلکَس دِیُت حُکُم زِ سُہ دِیہِ سٲنِس بٲے زیلوفہد سٕنز وَراثت تٔمۍ سٕنزِ کورِ۔\n3. تہٕ یێلہِ تِمن سٍتـ̡ اسرٲیلـ̡ سٍتـ̡ باقٕے قبیلن ہٕندِس نیچوِس سٍتـ̡ خاندر کرنہٕ یِن، تێلہِ یِیہِ تِہُند وَرث سانہِ مٲلِس سٕندِس وَرثس مَنٛز نِنہٕ یُن، تہٕ یِیہِ تِمن قبیلہٕ سٕندِس وَرثس مَنٛز نِنہٕ یِنہٕ۔ {کُنہِ کتھ...: ہیب۔ کٔمۍ سٕندِس نِش آسہِ}\n4. تہٕ یێلہِ یێلہِ بنی اسرٲیلِچ وراثت گژھہِ، تێلہِ یِیہِ تِہُند وَراثت تِمن قبیلہٕ سٕندِس وَرثس مَنٛز تھاونہٕ یُن، یێلہِ یِیہِ تِہُند وَراثت سانین آباؤ اجدادن ہٕندِس قبیلہٕ سٕندِس وَرثس نِش نِنہٕ۔ {کُنہِ کتھ...: ہیب۔ کٔمۍ سٕندِس نِش آسہِ}\n5. تہٕ موسىٰ دِیُت خداوند سٕندِ کلامَس مُطٲبِق بنی اسرٲیلِس حُکُم تہٕ وَنُن زِ یوسف سٕندِس نیچوَن ہٕندِس قبیلس چُھ رژھ رژھ وَنان۔\n6. یہِ چُھ سُہ چیز یُس خداوند زیلوفہد سٕنزِ کورِ مُتعلِق حُکُم دِوان چھُ، یُس تِم بہتر سمجھان چھِ۔ صرف پننِس مٲل سٕندِس قبیلہٕ کِس عیالس سٍتۍ گژھن تِم خانٛدر۔ {خانٛدر: ہیب۔ خانٛدارِنۍ بٔنِو}\n7.\\tیِتھے پٲٹھـ̡ گژھہِ نہٕ بنی اسرٲیلـ̡ ہٕندِس قبیلہٕ سٍتـ̡ وَراونہٕ یِنہٕ۔ {کیپ...: ہیب۔ کلیو ٹو دی وغیرہ}\n8. تہٕ پرتھ کانہہ کورِ یُس اسرٲیلِہ سٕندِس قبیلس مَنٛز وراثت آسہِ، سُہ گژھہِ پننِس مٲلہِ سٕندِس قبیلہٕ کِس خاندانس مَنٛز أکِس سٍتـ̡ خانٛدارِنہٕ، یُتھ زن اسرٲیلٕکۍ اولاد پرٮ۪تھ أکِس مردس پنہٕ نِس مٲلِس سٕندِس وراثتس سٍتـ̡ لُطف حٲصل کٔرِتھ۔\n9. نۂ وراثت گژھِ اَکہِ قبیلہٕ پیٹھٕ بییِس قبیلس منز منتقل کرنہٕ۔ مگر بنی اسرائیل سٕندِ قبیلہٕ سٍتـ̡ پَنُن پان رژھرُن۔\n10. یِتھے پٲٹھۍ خداوند موسیٰ سُند حُکُم دِیُت، تِتھے پٲٹھۍ کٔر زیلوفہد سٕنزِ کورِ:\n11.\\tمہلہ، ترزاہ تہٕ ہوگلہ تہٕ ملکہ تہٕ نوح یِمن ہٕندِس مٲلہِ سٕندِس بٲے سٕندِس نیچوِس سٍتـ̡ خاندر کرنہٕ آمٕتۍ۔\n12.\\tتہٕ تِمن ہُند خاندر سپُد یوسف سٕندِس نیچوِس مناشہ سٕندِس نیچوین ہٕندِس خاندانس مَنٛز، تہٕ تِہُند وَراثت روٗد تِہٕندِس مٲلہِ سٕندِس قبیلس مَنٛز۔ {into...: Heb. کینژن خاندانن منز ٲسۍ}\n13.\\tیِم چھِ تِم حُکُم تہٕ فیصلہٕ، یِم خداوند موسیٰ سٕندِ اتھہٕ سٍتـ̡ موآب کِس میدانس مَنٛز اردن {نزدیک} یریحہ کِس میدانس مَنٛز بنی اسرائیل خٲطرٕ حُکُم دِیُت۔"];
